local config = {
  ui_story_5040_50400101_1_dialog_content = "（ああ…久しぶりの休みなのに…）",
  ui_story_5040_50400101_2_dialog_content = "（…いやいや、元気出さなきゃ！）",
  ui_story_5040_50400101_3_dialog_content = "「ピピッ、<color=#FFB400>冠月祭</color>まであと3日」",
  ui_story_5040_50400101_4_dialog_content = "「冠月祭は恋人たちが互いの気持ちを伝える\nアストラの伝統的な行事で、結婚式にふさわしい日と言われています」",
  ui_story_5040_50400101_5_dialog_content = "分かってるって…去年から忙しくて冠月祭のことを忘れてなければ、\n僕だって今こんなことには…",
  ui_story_5040_50400101_6_dialog_content = "とにかく、バイスとカレンが気に入ってた\nあのレコードプレーヤーを買って、驚かせてあげなきゃ！",
  ui_story_5040_50400101_7_dialog_content = "（そういえば、2人とも休みだって言ってたけど、\nどこに行ったのかな？その方が都合はいいけど）",
  ui_story_5040_50400101_8_dialog_content = "PlayerNameさんが私を訪ねて来られるとは珍しいですね。\n何かご用でしょうか？",
  ui_story_5040_50400101_9_dialog_content = "申し訳ありませんが、冠月祭が近くクーリエ隊は繁忙期なのです。\nあまりお話している時間がありません。",
  ui_story_5040_50400101_10_dialog_content = "おまけに、R・W支部の方で\n白夜城宛ての荷物が大量に取り違えられたとかで…",
  ui_story_5040_50400101_11_dialog_content = "そうなんだ？僕に何か手伝えることはある？",
  ui_story_5040_50400101_12_dialog_content = "実は冠月祭で買いたいものがあるから、\nお金を稼ぐために仕事を探してるんだ。",
  ui_story_5040_50400101_13_dialog_content = "先日タタがお世話になったばかりで、\nさらに手間を取っていただくのは気がひけますが…",
  ui_story_5040_50400101_14_dialog_content = "そういうことでしたら、お言葉に甘えましょう。\nR・W支部へ行っていただきたい用事があります。",
  ui_story_5040_50400101_15_dialog_content = "北境にいる古くからの友人が結婚式を挙げるのですが…\n他の多くの方たちと同様、冠月祭の日に挙式の予定なのです。",
  ui_story_5040_50400101_16_dialog_content = "ですが、お相手の女性が先日R・W砂漠でけがをしてしまったそうです。\n治るのを待っていては、北境での結婚式に間に合わないでしょう。",
  ui_story_5040_50400101_17_dialog_content = "あ、巨像で送っていってあげればいいってこと？\nそれぐらいなら、何てことないよ。",
  ui_story_5040_50400101_18_dialog_content = "（…そういえば、ナルセールは\n友だちの結婚式なのに出席しないのかな？）",
  ui_story_5040_50400101_19_dialog_content = "（まぁ、詳しいことは着いてから聞くことにしよう。\n…ここがR・W支部だよね？）",
  ui_story_5040_50400101_20_dialog_content = "<color=#e8d9bb>トントン――</color>",
  ui_story_5040_50400101_21_dialog_content = "あの…",
  ui_story_5040_50400101_22_dialog_content = "あら～、わざわざお手伝いに来てくれた空の末裔くんね～？\n待ってたわよぉ。",
  ui_story_5040_50400101_23_dialog_content = "ナルセールから巨像は速いって聞かされてたけど、\n思ったよりは遅かったわねぇ。",
  ui_story_5040_50400101_X23_dialog_content = "（お、大きなヘビ！このヘビも言霊なのかな！？すごいな！）",
  ui_story_5040_50400101_X24_dialog_content = "（それと、この部屋…なんだかきれいすぎて、\nR・Wの雰囲気には似つかわしくない）",
  ui_story_5040_50400101_24_dialog_content = "（この部屋…なんだかきれいすぎて、\nR・Wの雰囲気には似つかわしくない）",
  ui_story_5040_50400101_25_dialog_content = "初めまして。\nナルセールの依頼で手伝いにきたPlayerNameだよ。",
  ui_story_5040_50400101_26_dialog_content = "それで、2人は…？",
  ui_story_5040_50400101_27_dialog_content = "想像してたより若いのね～。\nまずは自己紹介しましょうか――",
  ui_story_5040_50400101_28_dialog_content = "アタシはR・W支部のエルダー、<color=#FFB400>イェリア</color>よ。\nで、こっちは<color=#FFB400>ターラ</color>。今回の依頼の対象ってところかしら。",
  ui_story_5040_50400101_29_dialog_content = "初めまして、ターラよ。\nウワサの空の末裔に会えるなんて、ラッキーだわ！",
  ui_story_5040_50400101_30_dialog_content = "いやいや、そんな大したものじゃないよ…\nそれで、イェリアも一緒に北境へ行くの？",
  ui_story_5040_50400101_31_dialog_content = "あはは、仕事でちょっとミスがあってねぇ。\nナルセールに後始末をお願いしなきゃならなくなったのよ。",
  ui_story_5040_50400101_32_dialog_content = "だから、アタシが代わりに結婚式に立ち会うことになったの。",
  ui_story_5040_50400101_33_dialog_content = "（ナルセールの言ってた「取り違え」をしたのって、\nもしかしてイェリア？）",
  ui_story_5040_50400101_34_dialog_content = "立ち合い？そういえば、クーリエが結婚式に立ち会うと、\n幸せになれるって聞いたことがあるなぁ。",
  ui_story_5040_50400101_35_dialog_content = "そうなの！でも、冠月祭の日にクーリエを招待するのって、\nほんとに大変なのよ。ナルセールにずいぶん借りができちゃったわ！",
  ui_story_5040_50400101_36_dialog_content = "ナルセールって、1日も時間が取れないほど忙しいの？",
  ui_story_5040_50400101_37_dialog_content = "冠月祭の前後はもともと一番忙しい時期だもの。\n招待状やら手紙やらの配達で、毎日飛び回ってるわ。",
  ui_story_5040_50400101_38_dialog_content = "おまけに、誰かさんが\n「うっかり」大量の荷物を取り違えちゃったし。",
  ui_story_5040_50400101_39_dialog_content = "わざわざ来てくれた空の末裔くんにイヤミを言うヒマがあるなら、\n早く未来の旦那さんに会いに行った方がいいんじゃな～い？",
  ui_story_5040_50400101_40_dialog_content = "そうだね。巨像がいくら速いと言っても、\n早めに出発した方がいいよ。",
  ui_story_5040_50400101_41_dialog_content = "わぁ！PlayerNameの巨像って、\nあのオオトカゲとはぜんっぜん違うのね！",
  ui_story_5040_50400101_42_dialog_content = "あはは、ずいぶん気に入ってくれたみたいだね。",
  ui_story_5040_50400101_43_dialog_content = "それにしても、砂漠出身の新婦と北境出身の新郎なんて、\n珍しいカップルなんじゃない？そう思うのは僕だけ？",
  ui_story_5040_50400101_44_dialog_content = "実際、すごく珍しいわ！",
  ui_story_5040_50400101_45_dialog_content = "世界は広いもの、なんだって起こるわぁ。\nでも、光霊の目から見れば、確かに珍しいかしらね～。",
  ui_story_5040_50400101_46_dialog_content = "やっぱりそうなんだ。",
  ui_story_5040_50400101_47_dialog_content = "ところで、イェリア。\n君もR・W砂漠出身なの？",
  ui_story_5040_50400101_48_dialog_content = "その通りよ。認めたくはないけどねぇ。",
  ui_story_5040_50400101_49_dialog_content = "イェリアって変わり者よね？\n生粋の砂漠育ちなのに、R・Wにはろくに知り合いもいないみたいだし。",
  ui_story_5040_50400101_50_dialog_content = "さんざん聞いて回って、\nやっとここを見つけたんだから。",
  ui_story_5040_50400101_51_dialog_content = "ふふ、生き方は人それぞれでしょ。",
  ui_story_5040_50400101_52_dialog_content = "ま、アタシのことはいいの。\n今回はあなたが主役なんだから。",
  ui_story_5040_50400101_53_dialog_content = "そうだよ！\n僕、本物の花嫁さんに会うのは初めてなんだ。",
  ui_story_5040_50400101_54_dialog_content = "そんな大したものじゃないわよ。\n砂漠の人間はみんな恋とか愛とかにオープンだしね。",
  ui_story_5040_50400101_55_dialog_content = "とにかく、時間も限りあるんだし、\nせっかくなら巨像を見学したいわ。",
  ui_story_5040_50400101_56_dialog_content = "PlayerName、案内してよね！",
  ui_story_5040_50400101_57_dialog_content = "分かったよ…あ！そんなに急がないで！",
  ui_story_5040_50400101_58_dialog_content = "こんな風に言っていいのか分からないけど、\nターラってあんまり花嫁っていうイメージに合わないね。",
  ui_story_5040_50400101_59_dialog_content = "人それぞれってことよ。\n空の末裔くん、陰口は良くないわね～。",
  ui_story_5040_50400101_60_dialog_content = "…うん、そうだね。",
  ui_story_5040_50400101_61_dialog_content = "（イェリア、結婚式にはまったく無関心みたいだ）",
  ui_story_5040_50400101_62_dialog_content = "ふぅ。やっと着いたね。",
  ui_story_5040_50400101_63_dialog_content = "ターラは花婿さんのところへ行ったんでしょ？\nこの近くに村があるんだよね…？",
  ui_story_5040_50400101_64_dialog_content = "降臨町ね。北境の端の方にあるのよ。\n昔ながらの伝統を守って、神殿で挙式する人が多いわ。",
  ui_story_5040_50400101_65_dialog_content = "じゃあ、僕たちもその神殿へ行けばいいのかな？",
  ui_story_5040_50400101_66_dialog_content = "新郎新婦は別の所にいると思うわ。",
  ui_story_5040_50400101_67_dialog_content = "（…そもそも、もう花嫁は送り届けたし、\n僕まで結婚式に出る必要あるのかな？）",
  ui_story_5040_50400101_68_dialog_content = "あ、もう帰ってもいいのかなって思ってな～い？",
  ui_story_5040_50400101_69_dialog_content = "（見抜かれた！？）",
  ui_story_5040_50400101_70_dialog_content = "ナルセールの知り合いなんだし、\nターラたちも結婚式に顔を出して欲しいって思ってるんじゃないかしら？",
  ui_story_5040_50400101_71_dialog_content = "せっかくここまで来たんだしねぇ。白夜城ほどハデじゃないけど、\n北境の結婚式もなかなか風情があるわよ～。",
  ui_story_5040_50400101_72_dialog_content = "それもそうだね。ところで…イェリアってR・W支部の所属でしょ？\nなのに、北境のことにも詳しいんだね？",
  ui_story_5040_50400101_73_dialog_content = "北境だけじゃないわ。\n仕事以外のことなら、イェリアの知らないことは無いの。",
  ui_story_5040_50400101_74_dialog_content = "あ、戻ってきたんだね。\n花婿さんは？",
  ui_story_5040_50400101_75_dialog_content = "ターラ！",
  ui_story_5040_50400101_76_dialog_content = "ご、ごめん、遅くなって…！",
  ui_story_5040_50400101_77_dialog_content = "まったくよ！",
  ui_story_5040_50400101_78_dialog_content = "とりあえず、紹介するわ…こっちがイェリア。\nこの前話したR・W砂漠のクーリエ隊のエルダーよ。",
  ui_story_5040_50400101_79_dialog_content = "で、こっちがPlayerName、空の末裔よ！\n巨像もほんとにすごかったわ！",
  ui_story_5040_50400101_80_dialog_content = "…で、この人が<color=#FFB400>アドニス</color>、あたしの婚約者…\n改めて言うと、変な気分になるわね。いつも名前で呼んでるから。",
  ui_story_5040_50400101_81_dialog_content = "エルダー・イェリア、PlayerNameさん、はじめまして。",
  ui_story_5040_50400101_82_dialog_content = "申し訳ありません。今日は何かとドタバタしていまして…\nナルセールとは同級生で、今回もいろいろ助けてもらってるんです。",
  ui_story_5040_50400101_83_dialog_content = "結婚式にはPlayerNameさんもぜひご出席ください。",
  ui_story_5040_50400101_84_dialog_content = "そうだ、ちゃんと家には帰ったの？",
  ui_story_5040_50400101_85_dialog_content = "ま、まだだよ。",
  ui_story_5040_50400101_86_dialog_content = "…まだ話してないの？",
  ui_story_5040_50400101_87_dialog_content = "いつまで先延ばしするつもり！？",
  ui_story_5040_50400101_88_dialog_content = "す、すぐに話すよ。明日には帰るから…",
  ui_story_5040_50400101_89_dialog_content = "そうやっていつも先延ばしじゃない！\nほんとに話す気があるの？疑わしくなってくるわ！",
  ui_story_5040_50400101_90_dialog_content = "…",
  ui_story_5040_50400101_91_dialog_content = "（…どういうことだろう？）",
  ui_story_5040_50400101_92_dialog_content = "なんだかワケありみたいねぇ。",
  ui_story_5040_50400101_93_dialog_content = "…ねえ、アタシも空の末裔くんもナルセールに頼まれて来てるの。\n事情を聞かせてくれてもいいんじゃないかしら？",
  ui_story_5040_50400101_94_dialog_content = "ふん、あなたが話しなさいよ！",
  ui_story_5040_50400101_95_dialog_content = "…お恥ずかしい話ですが、実は僕たち…\n勝手に結婚式を挙げようとしてるんです。",
  ui_story_5040_50400101_96_dialog_content = "僕の両親は最初からターラとの結婚に反対していて…",
  ui_story_5040_50400101_97_dialog_content = "なるほどねぇ。",
  ui_story_5040_50400101_98_dialog_content = "北境の男が砂漠から嫁取りだなんて、\n確かにそうそうない話だもの。",
  ui_story_5040_50400101_99_dialog_content = "でも、僕は真剣なんです！\n今度こそ両親に、きちんと自分の気持ちを話します！",
  ui_story_5040_50400101_100_dialog_content = "それから2人でどこか遠くへ行って暮らします！\nR・W砂漠でも、他の所でも、どこへでも行きます！",
  ui_story_5040_50400101_101_dialog_content = "…つまり、駆け落ちするってこと？",
  ui_story_5040_50400101_102_dialog_content = "もちろん、できれば両親に認めてもらいたいとは思っています。\nですが…",
  ui_story_5040_50400101_103_dialog_content = "「ですが」何？\nまだ話してないんでしょ？",
  ui_story_5040_50400101_104_dialog_content = "自分の気持ちをはっきり伝えるのが、\nそんなに難しいの？",
  ui_story_5040_50400101_105_dialog_content = "僕は…",
  ui_story_5040_50400101_106_dialog_content = "ねえ、アドニスくん。さっきから聞こうと思ってたんだけど、\nあなた、北境から出たことないでしょ？",
  ui_story_5040_50400101_107_dialog_content = "は、はい、ありません。\nターラとも北境で出会ったんです。",
  ui_story_5040_50400101_108_dialog_content = "あらあら、温室育ちのお花が砂漠でその日暮らしの生活を送ろうなんて、\nずいぶんな勇気じゃない？",
  ui_story_5040_50400101_109_dialog_content = "決心はついています！\nターラと一緒ならどんな困難も乗り越えてみせます！",
  ui_story_5040_50400101_110_dialog_content = "だったら、親に話すぐらい簡単じゃないの！？",
  ui_story_5040_50400101_111_dialog_content = "あ、あの、お取込み中すみません！",
  ui_story_5040_50400101_112_dialog_content = "アドニスさん、あなた宛ての荷物です。\n至急との事なので、先にお受け取りいただけますか？",
  ui_story_5040_50400101_113_dialog_content = "あら、北境の小鳥ちゃん？",
  ui_story_5040_50400101_114_dialog_content = "イ、イェリア先輩？",
  ui_story_5040_50400101_115_dialog_content = "この前何通か手紙を取り違えた時には\n色々ありがとね～。とっても感謝してるわ。",
  ui_story_5040_50400101_116_dialog_content = "「何通か」ではすまない量だったと思いますが…\n今度からは気を付けてくださいよ。",
  ui_story_5040_50400101_117_dialog_content = "<size=33>二度と思い出したくないぐらい苦労したんですから…</size>",
  ui_story_5040_50400101_118_dialog_content = "<color=#FFB400>キア</color>、ありがとう。",
  ui_story_5040_50400101_119_dialog_content = "何が届いたの？",
  ui_story_5040_50400101_120_dialog_content = "ああ、そういえば、送り主の霊媒師が言っていました。\n効き目が強い薬なので注意して使うように、だそうです。",
  ui_story_5040_50400101_121_dialog_content = "薬？何の？",
  ui_story_5040_50400101_122_dialog_content = "そ、それは…帰ったら話すよ。",
  ui_story_5040_50400101_123_dialog_content = "いいから、今すぐ教えて！\nいったい何の薬なの！？",
  ui_story_5040_50400101_124_dialog_content = "はぁ…",
  ui_story_5040_50400101_125_dialog_content = "腕のいい霊媒師に作ってもらった<color=#FFB400>魔法の万能薬</color>だよ。\n自分の気持ちをコントロールしたい時…つまり、勇気が欲しい時とかに飲むんだ。",
  ui_story_5040_50400101_126_dialog_content = "これさえあれば、両親に話す時、\n弱気にならずにいられるかなって思って…",
  ui_story_5040_50400101_127_dialog_content = "（魔法の薬？そんなもの、本当にあるのかな？）",
  ui_story_5040_50400101_128_dialog_content = "はあ？何言ってるの？\nまさかそんなモノを信じてるの！？ちょっと見せて！",
  ui_story_5040_50400101_129_dialog_content = "ほんと、信じられないわ！\nこの時代にまだ霊媒師を信じる人がいたなんて…",
  ui_story_5040_50400101_130_dialog_content = "もう3年も付き合ってるのに、\nそんなものに頼らなきゃ親に話せないって言うの！？",
  ui_story_5040_50400101_131_dialog_content = "ぼ、僕たちのためだと思ったんだよ！",
  ui_story_5040_50400101_132_dialog_content = "どこまで弱虫なのよ？\nあたしたちの将来に自信が持てないの！？",
  ui_story_5040_50400101_133_dialog_content = "そんなものに頼らなきゃ、気持ちを貫けないってこと！？\nどうなのよ、アドニス！",
  ui_story_5040_50400101_134_dialog_content = "あなたがこんな調子なら、結婚式はもう…",
  ui_story_5040_50400101_135_dialog_content = "<color=#e8d9bb>ガサッ！</color>",
  ui_story_5040_50400101_136_dialog_content = "<size=45>グアア！！</size>",
  ui_story_5040_50400101_137_dialog_content = "<size=45>グアア――！！</size>",
  ui_story_5040_50400101_138_dialog_content = "暗鬼？どこから出てきたの！？",
  ui_story_5040_50400101_139_dialog_content = "どうしてここに暗鬼が出るのよ！？",
  ui_story_5040_50400101_140_dialog_content = "とんだお客さんだわ、面倒ねぇ。",
  ui_story_5040_50400201_1_dialog_content = "<color=#e8d9bb>――ドン！</color>",
  ui_story_5040_50400201_2_dialog_content = "グアアッ！",
  ui_story_5040_50400201_3_dialog_content = "グアア――！",
  ui_story_5040_50400201_4_dialog_content = "どういうこと！？\nいったいどこからこんな大量の暗鬼が…",
  ui_story_5040_50400201_5_dialog_content = "面倒だけど、気を付けた方がいいわね。",
  ui_story_5040_50400201_6_dialog_content = "真ん中の暗鬼、なんだか様子がおかしいわ。",
  ui_story_5040_50400201_7_dialog_content = "はぁ…はぁ…",
  ui_story_5040_50400201_8_dialog_content = "ターラ！後ろだ！",
  ui_story_5040_50400201_9_dialog_content = "アドニス、来ちゃダメ！ここはあたしたちに任せて！",
  ui_story_5040_50400201_10_dialog_content = "ターラさん、気を付けてください！\nあのおかしな暗鬼、ずっとターラさんを見てますよ！",
  ui_story_5040_50400201_11_dialog_content = "ちょうだい…",
  ui_story_5040_50400201_12_dialog_content = "私に…ちょうだい…",
  ui_story_5040_50400201_13_dialog_content = "ほ、ほしい…私にちょうだい…",
  ui_story_5040_50400201_14_dialog_content = "何を言ってるの！？",
  ui_story_5040_50400201_15_dialog_content = "（公用語をしゃべった？）",
  ui_story_5040_50400201_16_dialog_content = "ターラ、その手に持ってる薬ビンを投げて。",
  ui_story_5040_50400201_17_dialog_content = "え？",
  ui_story_5040_50400201_18_dialog_content = "<color=#e8d9bb>ヒュン――バリン――</color>",
  ui_story_5040_50400201_19_dialog_content = "ターラ！！",
  ui_story_5040_50400201_20_dialog_content = "危ない、避けて！",
  ui_story_5040_50400201_21_dialog_content = "<color=#e8d9bb>ジワッ…</color>",
  ui_story_5040_50400201_22_dialog_content = "きゃあっ！！",
  ui_story_5040_50400201_23_dialog_content = "ふぅ…！薬…",
  ui_story_5040_50400201_24_dialog_content = "グアアア――",
  ui_story_5040_50400201_25_dialog_content = "グガァア！",
  ui_story_5040_50400201_27_dialog_content = "暗鬼が逃げた？",
  ui_story_5040_50400201_28_dialog_content = "小さいのがまだ残ってるわ。",
  ui_story_5040_50400201_29_dialog_content = "アドニス、婚約者をしっかり守ってあげなさい。",
  ui_story_5040_50400202_1_dialog_content = "やっと倒したね。皆、大丈夫？",
  ui_story_5040_50400202_2_dialog_content = "ターラ！ターラ！！",
  ui_story_5040_50400202_3_dialog_content = "大変です！気を失っているみたいです！",
  ui_story_5040_50400202_4_dialog_content = "2人とも、ちょっとどいて。\nアタシが診るわ。",
  ui_story_5040_50400202_5_dialog_content = "大した外傷はないわね。\n逃げた暗鬼が何かしたワケでもなさそうだし…",
  ui_story_5040_50400202_6_dialog_content = "ただのかすり傷よ。",
  ui_story_5040_50400202_7_dialog_content = "でも、気を失っているんですよ？\n頭でもぶつけたんじゃないでしょうか？",
  ui_story_5040_50400202_8_dialog_content = "まずは落ち着きなさい。アタシが見た限り、問題はないわ。\nとにかく安全な所で休ませてあげましょ。",
  ui_story_5040_50400202_9_dialog_content = "…そういえば、ビンの中の薬がターラさんにかかっていましたよね。",
  ui_story_5040_50400202_10_dialog_content = "何か良くないものでも入ってたんでしょうか！？",
  ui_story_5040_50400202_11_dialog_content = "私に分かるわけないじゃないですか…\nあなたが注文した物でしょう？私は配達を頼まれただけです。",
  ui_story_5040_50400202_12_dialog_content = "とにかく、まずは落ち着こうよ。\nターラをどこかで休ませなきゃ。",
  ui_story_5040_50400202_13_dialog_content = "そうですね…では、皆さん、申し訳ありませんが、\n僕の家までお願いします。",
  ui_story_5040_50400202_14_dialog_content = "まだ配達が残っていますので、私は失礼します。\nターラさんの面倒、ちゃんと見てあげてくださいよ？",
  ui_story_5040_50400202_15_dialog_content = "<color=#e8d9bb>トントントン――</color>",
  ui_story_5040_50400202_16_dialog_content = "アドニスか？どうした、こんな時間に…",
  ui_story_5040_50400202_17_dialog_content = "おい、何があった！？",
  ui_story_5040_50400202_18_dialog_content = "父さん、話せば長くなるんだ。\nまずは中に入れてくれないかな。",
  ui_story_5040_50400202_19_dialog_content = "アドニス、お友だち？\nそれに、この子…ターラじゃないの。",
  ui_story_5040_50400202_20_dialog_content = "急に押しかけてすみません…",
  ui_story_5040_50400202_21_dialog_content = "母さん、ターラがケガをしてるんだ。\nさっき暗鬼に襲われて…まずは休ませてあげたいんだ。話は後でいいかな？",
  ui_story_5040_50400202_22_dialog_content = "暗鬼ですって！？応急処置用の薬草ならあったはずよ。\nあなたは？他の人はケガはないの？",
  ui_story_5040_50400202_23_dialog_content = "あわてないで。彼女はかすり傷だし、ただショックで気絶してるだけ。\n他の人たちもなんともないわ。",
  ui_story_5040_50400202_24_dialog_content = "アタシはターラを寝かせてくるから、\nあなたたちで話をしておいて。",
  ui_story_5040_50400202_25_dialog_content = "とにかく、こういうわけで…",
  ui_story_5040_50400202_26_dialog_content = "ふざけるにも程がある！！",
  ui_story_5040_50400202_27_dialog_content = "そんな大事なこと、どうして話してくれなかったの？",
  ui_story_5040_50400202_28_dialog_content = "あの子がケガをしなかったら、\n私たちに内緒で式を挙げて、北境を離れるつもりだったなんて。",
  ui_story_5040_50400202_29_dialog_content = "僕は…",
  ui_story_5040_50400202_30_dialog_content = "バカ正直なだけかと思っていたが、\nここまでバカだったとは！",
  ui_story_5040_50400202_31_dialog_content = "ノーヴィオ先生に教えていただいたことを、\n全部忘れてしまったのか！？",
  ui_story_5040_50400202_32_dialog_content = "北境を離れても本当に生きていけると思うなら、\n好きにするがいい！だが、二度とこの家には戻ってくるな！",
  ui_story_5040_50400202_33_dialog_content = "お前のような息子は勘当だ！",
  ui_story_5040_50400202_34_dialog_content = "父さん、母さん！\n縁を切るなんて、そういうつもりじゃないんだよ！",
  ui_story_5040_50400202_35_dialog_content = "言い訳はたくさんだ。もう聞きたくない！",
  ui_story_5040_50400202_36_dialog_content = "お父さんは今、頭に血が上ってるだけよ。",
  ui_story_5040_50400202_37_dialog_content = "でもアドニス…私たちががっかりしてるのは本当。",
  ui_story_5040_50400202_38_dialog_content = "…",
  ui_story_5040_50400202_39_dialog_content = "うぅ…",
  ui_story_5040_50400202_40_dialog_content = "（こ、こんな場所に居合わせるのは、初めてだ…）",
  ui_story_5040_50400202_41_option_content = "アドニスをなぐさめる",
  ui_story_5040_50400202_42_dialog_content = "そんなに落ち込まないで。\nご両親はビックリしてるんだよ。",
  ui_story_5040_50400202_43_dialog_content = "誰だって、急にこんなことがあったら、\nパニックになるのが普通だよ。",
  ui_story_5040_50400202_44_dialog_content = "でも、親子でしょ。\nちゃんと話し合えば、きっと分かってもらえるよ。",
  ui_story_5040_50400202_45_dialog_content = "うぅ…両親とは分かり合えないし、\nターラにもケガをさせてしまった…",
  ui_story_5040_50400202_46_dialog_content = "僕は本当にダメな男だ…",
  ui_story_5040_50400202_47_dialog_content = "（ダメだ…自己否定で悪循環に入ってる）",
  ui_story_5040_50400202_48_option_content = "イェリアに助けを求める",
  ui_story_5040_50400202_49_dialog_content = "イェリア、どうしよう？",
  ui_story_5040_50400202_50_dialog_content = "え？何が？",
  ui_story_5040_50400202_51_dialog_content = "（まさか、この状況で他の考え事？\nよくそんなことできるなあ…）",
  ui_story_5040_50400202_52_dialog_content = "こういう時、なんて言えばいいの？",
  ui_story_5040_50400202_53_dialog_content = "本人の問題だもの。\n他人がとやかく言ってもムダよぉ。",
  ui_story_5040_50400202_54_dialog_content = "聞こえのいいことを言ったところで、\nなんの解決にもならないわ。",
  ui_story_5040_50400202_55_dialog_content = "（確かにその通りではあるけど、\n何もしないのもよくない気がする）",
  ui_story_5040_50400202_56_dialog_content = "（この空気…いたたまれないなぁ…）",
  ui_story_5040_50400202_57_dialog_content = "申し訳ありません。\nお二人にはお見苦しいところをお見せしました。",
  ui_story_5040_50400202_58_dialog_content = "そんなことないよ。\n僕たちに何かできることがあれば、何でも言って。",
  ui_story_5040_50400202_59_dialog_content = "いえ…全部僕がいけないんです。",
  ui_story_5040_50400202_60_dialog_content = "わざわざ遠くから来ていただいたのに、\nきちんとおもてなしもできず…",
  ui_story_5040_50400202_61_dialog_content = "あらあら、今はそんなこと言ってる場合じゃないでしょ？",
  ui_story_5040_50400202_62_dialog_content = "空の末裔くん、アドニスと散歩でもして気分転換してきて。\nアタシはターラを見ておくわぁ。",
  ui_story_5040_50400202_63_dialog_content = "分かったよ。じゃあ、行こうか。",
  ui_story_5040_50400202_64_dialog_content = "はい…",
  ui_story_5040_50400202_65_dialog_content = "…",
  ui_story_5040_50400202_66_dialog_content = "そろそろ起きたら？",
  ui_story_5040_50400202_67_dialog_content = "！？",
  ui_story_5040_50400202_68_dialog_content = "どうして分かったの？",
  ui_story_5040_50400202_69_dialog_content = "ケガなんてするはずないでしょ。\nあの暗鬼、攻撃なんて全然してなかったもの。",
  ui_story_5040_50400202_70_dialog_content = "気を失うワケがないわ。",
  ui_story_5040_50400202_71_dialog_content = "…",
  ui_story_5040_50400202_72_dialog_content = "アタシはナルセールに頼まれた用事を済ませたいだけ。\nそれ以外のことには興味ないの。",
  ui_story_5040_50400202_73_dialog_content = "そもそもアタシとは関係ないことだしね～。",
  ui_story_5040_50400202_74_dialog_content = "ただ…おせっかいかもしれないけど、一言いいかしら？\nこの後いったいどうするつもり？",
  ui_story_5040_50400202_75_dialog_content = "あたしは…はぁ…",
  ui_story_5040_50400202_76_dialog_content = "正直言うと、自分でも分からないわ。\n砂漠じゃ悩み事なんて何もなかったのに…もうウンザリよ。",
  ui_story_5040_50400202_77_dialog_content = "アドニスと一緒にいると楽しいってことは否定しないけど、\nあんなに頼りないんじゃ、ほんとに結婚するべきか不安になるわ…",
  ui_story_5040_50400202_78_dialog_content = "人間の性格なんて一朝一夕で変わるものじゃないわ。\n長く付き合ってたのなら、今さら気づいたワケじゃないでしょ？",
  ui_story_5040_50400202_79_dialog_content = "…ええ。",
  ui_story_5040_50400202_80_dialog_content = "3年前に北境の遺跡を探検してたら暗鬼に襲われて、\n逃げたまではよかったけど、途中で行き倒れちゃったの。",
  ui_story_5040_50400202_80X1_dialog_content = "それをアドニスが見つけて、\n家に連れ帰ってくれたのよ。",
  ui_story_5040_50400202_81_dialog_content = "あの日は大雪が降ってて、\nもし彼が助けてくれなかったら、どうなってたことか…",
  ui_story_5040_50400202_82_dialog_content = "はぁ…それからいろいろ話すようになったんだけど、\nお互い知らないことばっかりで、とても楽しかったわ。",
  ui_story_5040_50400202_83_dialog_content = "砂漠に帰ってからも、\nずっと手紙のやり取りをしてたの。",
  ui_story_5040_50400202_84_dialog_content = "アドニスは気が利くし、優しいの…\nあたしは親がいないから、あんなに優しくしてもらったのは初めてだったわ。",
  ui_story_5040_50400202_85_dialog_content = "心から感動しちゃったの。",
  ui_story_5040_50400202_86_dialog_content = "ふ～ん、そうだったのねぇ。",
  ui_story_5040_50400202_87_dialog_content = "でも、その後北境を離れるって話になるたびに、\nアドニスが煮え切らない態度で…なんだか別人みたい。",
  ui_story_5040_50400202_88_dialog_content = "以前はあんなじゃなかったのよ。\n何かを決心するって、そんなに難しい？",
  ui_story_5040_50400202_89_dialog_content = "あんなに弱気でハッキリしない人は初めてよ！\nほんとにあたしのこと、好きなのかしら？",
  ui_story_5040_50400202_90_dialog_content = "ずっと前から準備してきた結婚式なのに…\nとっておきのプレゼントも用意してあったの…はぁ…",
  ui_story_5040_50400202_91_dialog_content = "突っ込んだことを聞いていいかしら？\nあなた、今まで恋愛ってしたことある？",
  ui_story_5040_50400202_92_dialog_content = "今まで？ないわ、アドニスが初恋よ。",
  ui_story_5040_50400202_93_dialog_content = "だろうと思ったわ～。\n要するに、現実離れした幻を見てたってことねぇ。",
  ui_story_5040_50400202_94_dialog_content = "愛することは美しいかも知れないけど、お互いの性格を尊重しないと。\nどんな人でも中身は複雑で、白黒はっきりつけられたりはしないものよ。",
  ui_story_5040_50400202_95_dialog_content = "ど、どういう意味…？\nあたしにはよく…",
  ui_story_5040_50400202_96_dialog_content = "ふふ、そのうちわかるわ～。",
  ui_story_5040_50400202_97_dialog_content = "…",
  ui_story_5040_50400202_98_dialog_content = "あ…待って！\nいいことを思いついたわ！",
  ui_story_5040_50400202_99_dialog_content = "？",
  ui_story_5040_50400202_102_dialog_content = "決めたわ！",
  ui_story_5040_50400202_103_dialog_content = "あたし、記憶喪失のふりをする！\n初めからやり直して、アドニスがどんな態度をとるか確かめてやるわ！",
  ui_story_5040_50400202_104_dialog_content = "…",
  ui_story_5040_50400202_105_dialog_content = "本気で言ってるのぉ？",
  ui_story_5040_50400202_106_dialog_content = "お願い、手伝って！",
  ui_story_5040_50400202_107_dialog_content = "あなたたちが結婚しないなら、\nホントの所、アタシにはもう関係ないことよ？",
  ui_story_5040_50400202_108_dialog_content = "だ、ダメよ！\nナルセールにどう説明するつもり！？",
  ui_story_5040_50400202_109_dialog_content = "あら？それって脅迫？",
  ui_story_5040_50400202_110_dialog_content = "そ、そうじゃないわ！\n助けて、優しいイェリアお姉様！一生のお願い！",
  ui_story_5040_50400202_111_dialog_content = "あたしたち同郷でしょ！ね？お願いっ！",
  ui_story_5040_50400202_112_dialog_content = "…人使いが荒いわねぇ。",
  ui_story_5040_50400202_113_dialog_content = "はぁ、面倒なことになったわ…",
  ui_story_5040_50400202_114_dialog_content = "やった！やっぱりイェリアは最高だわ！",
  ui_story_5040_50400202_115_dialog_content = "ただし！アタシは黙っててあげるだけよ。\nあとは自分でどうにかしなさい。",
  ui_story_5040_50400202_116_dialog_content = "うまくいくかどうかは、全部あなた次第よ。",
  ui_story_5040_50400202_117_dialog_content = "<color=#e8d9bb>次の日――</color>",
  ui_story_5040_50400202_118_dialog_content = "イェリア、アドニス、おはよう。",
  ui_story_5040_50400202_119_dialog_content = "おはよう、空の末裔くん。",
  ui_story_5040_50400202_120_dialog_content = "おはようございます。\nターラはもう起きてますか…？",
  ui_story_5040_50400202_121_dialog_content = "（ふわぁ～）",
  ui_story_5040_50400202_122_dialog_content = "ターラ！目が覚めたんだね！\n身体は問題ないかい？",
  ui_story_5040_50400202_123_dialog_content = "…？",
  ui_story_5040_50400202_124_dialog_content = "どうかしたかい？\nどうしてそんな目で僕を見てるんだ？",
  ui_story_5040_50400202_125_dialog_content = "あなた…誰？",
  ui_story_5040_50400202_126_dialog_content = "な、何を言ってるんだ？ターラ？",
  ui_story_5040_50400202_127_dialog_content = "あなた、誰よ！？触らないで！",
  ui_story_5040_50400202_128_dialog_content = "ここはどこ？あなたはいったい誰？",
  ui_story_5040_50400202_129_dialog_content = "確か昨日、イェリアたちと巨像で北境に来たのよね。\nヘンねぇ、なんで北境なんかに来たのかしら？",
  ui_story_5040_50400202_130_dialog_content = "ターラ、冗談はよしてくれ…",
  ui_story_5040_50400202_131_dialog_content = "さすがに笑えないぞ…",
  ui_story_5040_50400202_132_dialog_content = "アドニス、大丈夫？",
  ui_story_5040_50400202_133_dialog_content = "（妙だな…ターラから感情の起伏は感じられない…\nもしかして…演技してる？）",
  ui_story_5040_50400202_134_dialog_content = "（恋愛のことはよく分からないし、\n本当のことを言ったら大変なことになるかも…ひとまず様子を見よう）",
  ui_story_5040_50400202_135_dialog_content = "すまない、僕が悪いんだ。全部僕が悪いんだ…",
  ui_story_5040_50400202_136_dialog_content = "あんな薬に頼ろうとした僕がいけないんだ！",
  ui_story_5040_50400202_137_dialog_content = "こうなったのは薬のせいってこと？",
  ui_story_5040_50400202_138_dialog_content = "霊媒師があの薬はどんな効果も願い通りの万能薬だと言っていました。\n記憶喪失になってもおかしくない！それ以外に考えられません！",
  ui_story_5040_50400202_139_dialog_content = "きっと僕のことが嫌いになって忘れたいと思っていたところに、\n薬をかぶったせいで記憶喪失になってしまったんです！",
  ui_story_5040_50400202_140_dialog_content = "全部僕のせいです！",
  ui_story_5040_50400202_141_dialog_content = "だったら、その霊媒師に話を聞きに行けばいいんじゃない？",
  ui_story_5040_50400202_142_dialog_content = "ここで悔やんでたって、どうにもならないし。",
  ui_story_5040_50400202_143_dialog_content = "霊媒師…",
  ui_story_5040_50400202_144_dialog_content = "そうだ、その通りです！思い出しました。\nあの人はたまに市場で店を出しているんです。",
  ui_story_5040_50400202_145_dialog_content = "行きましょう、今すぐ！",
  ui_story_5040_50400202_146_dialog_content = "ふぅ…こ、この人です！",
  ui_story_5040_50400202_147_dialog_content = "（は…走るのが速い…）",
  ui_story_5040_50400202_148_dialog_content = "おや？あんたは確か…？",
  ui_story_5040_50400202_149_dialog_content = "先日魔法の万能薬を買った者です。\n聞きたいことがあります！",
  ui_story_5040_50400202_150_dialog_content = "なに…ああ！あの時の！",
  ui_story_5040_50400202_151_dialog_content = "どうだったかな？私が精魂込めて作った薬だ。\nすごい効き目だったろう？",
  ui_story_5040_50400202_152_dialog_content = "簡単に事情を説明すると、僕の婚約者に薬の効果が出て、\n記憶喪失になってしまったんです。今すぐ解毒薬をください！",
  ui_story_5040_50400202_153_dialog_content = "む？そんなはずは…",
  ui_story_5040_50400202_154_dialog_content = "あの薬は何にでも効く、\n何でも願いがかなう薬だと言っていたでしょう？",
  ui_story_5040_50400202_155_dialog_content = "そ、そりゃあ確かにそうは言ったが…",
  ui_story_5040_50400202_156_dialog_content = "ただ、解毒薬となると少々面倒だ。",
  ui_story_5040_50400202_157_dialog_content = "えっ？どういうことですか？",
  ui_story_5040_50400202_158_dialog_content = "あの薬は誰も見たことがないという伝説の、\nR・W砂漠にいる希少なピンクのサンドワームの光るウロコで作ったものだからだ！",
  ui_story_5040_50400202_159_dialog_content = "ねぇ、アタシはその砂漠から来たんだけど。\nそんな話、聞いたこともないわぁ。",
  ui_story_5040_50400202_160_dialog_content = "…！",
  ui_story_5040_50400202_161_dialog_content = "オホン！もちろん一般人は知っているはずがない。\nそれほど希少なんだ。",
  ui_story_5040_50400202_162_dialog_content = "ピンクのサンドワームは、\n普通の人間じゃ一生探したって一度も見られない！",
  ui_story_5040_50400202_163_dialog_content = "（この人、ウソをついてる…\nそれにそもそも、サンドワームなんて探す人はいないでしょ！？）",
  ui_story_5040_50400202_164_dialog_content = "その身体はピンク色をしていて、\nウロコが七色に光り、貝殻のようにキラキラと輝くんだ！",
  ui_story_5040_50400202_165_dialog_content = "とにかく、解毒薬にはそいつのウロコが必要だ。\n自分たちでどうにか手に入れることだな。",
  ui_story_5040_50400202_166_dialog_content = "そ、そんな！無理を言わないでくださいよ！",
  ui_story_5040_50400202_167_dialog_content = "別に私には関係ない。あんたが欲しいって話だろう？\nこのことは好意で教えてやっただけだ。さ、商売のジャマはしないでくれ。",
  ui_story_5040_50400202_168_dialog_content = "…",
  ui_story_5040_50400202_169_dialog_content = "ダメだ、もう何もかも終わりだ…",
  ui_story_5040_50400202_170_dialog_content = "使いっ走りぐらいならいくらでもするけど、\nサンドワームと戦うなんて…僕には無理だ。",
  ui_story_5040_50400202_171_dialog_content = "時どき家の中に出てくる虫だって怖いのに、\n砂漠のサンドワームなんてとても…",
  ui_story_5040_50400202_172_dialog_content = "うーん…あなたほどの弱虫、\n確かにめずらしいわねぇ。",
  ui_story_5040_50400202_173_dialog_content = "（…お願いだから、余計なことを言わないで…）",
  ui_story_5040_50400202_174_dialog_content = "物事はいい方に考えましょ。少なくともターラの命に別状はないもの。\n失くしたのもあなたに関する記憶だけみたいだしねぇ。",
  ui_story_5040_50400202_175_dialog_content = "だったら、希少なサンドワームを探すなんて夢を見るより、\nもう一度ターラの気持ちを取り戻せばいいんじゃない？",
  ui_story_5040_50400202_176_dialog_content = "そうか。何もかも忘れたわけじゃないし、\nターラ自身が無事なら、いくらでも希望はあるね。",
  ui_story_5040_50400202_177_dialog_content = "長い間恋人同士でいられたのには、理由があるはずだよ。\nもう一度初めからやり直すのも難しくないんじゃないかな？",
  ui_story_5040_50400202_178_dialog_content = "そうですね。お2人の言う通りです。",
  ui_story_5040_50400202_179_dialog_content = "でも、いったい何から始めればいいのか…\n今の僕はターラにとって見知らぬ人ですから…",
  ui_story_5040_50400202_180_dialog_content = "そのことだけど、アタシは今回ナルセールの代理で\n結婚式に出るために来たの。覚えてる？",
  ui_story_5040_50400202_181_dialog_content = "冠月祭ってもともと結婚式を挙げる人が多いうえに、\nクーリエを呼びたがる人も多いのよね。",
  ui_story_5040_50400202_182_dialog_content = "それは僕も聞いたことがあるよ。クーリエが結婚式の席にいると、\n希望に満ちた幸せな結婚生活を送れるって言われてるんだよね。",
  ui_story_5040_50400202_183_dialog_content = "そうなのよ。だからクーリエ隊もここ数年は、\n結婚するカップルや恋人向けに冠月祭のイベントをやってるの。",
  ui_story_5040_50400202_184_dialog_content = "もともとこの時期は忙しいから、\nまとめてイベントで済ませて、クーリエたちの負担を減らそうってワケよ。",
  ui_story_5040_50400202_185_dialog_content = "え、そうなんだ？\n初めて聞いたよ。",
  ui_story_5040_50400202_186_dialog_content = "当然じゃな～い？だって「カップル」向けなのよぉ？\n独りものに知らせてどうするの？",
  ui_story_5040_50400202_187_dialog_content = "うっ…",
  ui_story_5040_50400202_188_dialog_content = "どういうことですか？",
  ui_story_5040_50400202_189_dialog_content = "つまり、クーリエを招待するっていう風習に代わるイベントで、\nカップルに幸運をもたらすことに変わりはないってことよ。",
  ui_story_5040_50400202_190_dialog_content = "支部ごとに内容は違ってるけどね。\nでも、条件を満たすとクーリエ隊の羽の印章を押してもらえるの。",
  ui_story_5040_50400202_191_dialog_content = "あなたもターラと一緒にクーリエ隊のイベントに参加してみたら？\nついでに外の世界も見られるわよ。",
  ui_story_5040_50400202_192_dialog_content = "北境から…出るということですか？",
  ui_story_5040_50400202_193_dialog_content = "外の世界に触れた刺激で過去の記憶を蘇らせるの。\n一種の民間療法みたいなものかしら？",
  ui_story_5040_50400202_194_dialog_content = "そういう方法もあるってだけの話よ。\nイベントはきっかけに過ぎないし、どうするかはあなた次第ねぇ。",
  ui_story_5040_50400202_195_dialog_content = "閉じこもって考えてばかりいても仕方ないでしょ？\n外に出てみなきゃ、解決方法だって見つからないわ。",
  ui_story_5040_50400202_196_dialog_content = "アタシには関係ないことだけど、\n外であっさり記憶を取り戻す方法が見つかるかもしれないでしょ。",
  ui_story_5040_50400202_197_dialog_content = "イェリアの言う通りだね！",
  ui_story_5040_50400202_198_dialog_content = "僕も昔、一人きりで長い間過ごしてたんだ。\n知識も全部聞いただけのものだった。",
  ui_story_5040_50400202_199_dialog_content = "でも、そのあと外の世界に出て、\n大陸には自分の知らないことがたくさんあるって知ったんだ。",
  ui_story_5040_50400202_200_dialog_content = "いろいろなところを回ってみたら、記憶を取り戻すだけじゃなくて、\n原因についても何か分かるかもしれないよ！",
  ui_story_5040_50400202_201_dialog_content = "お2人とも…",
  ui_story_5040_50400202_202_dialog_content = "本当に…何と言ったらいいのか…",
  ui_story_5040_50400202_203_dialog_content = "僕たちのために色々考えてくださって、心から感謝します。\n今一番大事なのはターラを治すことですよね。",
  ui_story_5040_50400202_204_dialog_content = "僕たちの愛情はそんなに脆いものじゃありません！\nたとえ一度失ったとしても、必ず取り戻せます！",
  ui_story_5040_50400202_205_dialog_content = "…",
  ui_story_5040_50400202_206_dialog_content = "…",
  ui_story_5040_50400202_207_dialog_content = "僕の考えは今話した通りだよ。",
  ui_story_5040_50400202_208_dialog_content = "認めてもらえないのは分かってる。\nでも、僕は…",
  ui_story_5040_50400202_209_dialog_content = "そうか。なら行けばいい。",
  ui_story_5040_50400202_210_dialog_content = "えっ？",
  ui_story_5040_50400202_211_dialog_content = "お前たちがその旅の後もまだ一緒にいたいというなら、\n私たちも前向きに考えてやらなくもない。",
  ui_story_5040_50400202_212_dialog_content = "ほ、本当に？",
  ui_story_5040_50400202_213_dialog_content = "よかった！ありがとう！父さん、母さん！",
  ui_story_5040_50400202_214_dialog_content = "でも…あなたは生まれてこの方、一度も北境を出たことがないのよ。\n外の世界は危険だから、十分に気を付けてね。",
  ui_story_5040_50400202_215_dialog_content = "<size=33>イェリア、2人の態度、どうして急に変わったんだろう？</size>",
  ui_story_5040_50400202_216_dialog_content = "そうねぇ、どうしてかしら～？",
  ui_story_5040_50400202_217_dialog_content = "すみません、少しよろしいですか？",
  ui_story_5040_50400202_218_dialog_content = "おや？あなたは確か…",
  ui_story_5040_50400202_219_dialog_content = "クーリエ隊のエルダー、イェリアと申します。",
  ui_story_5040_50400202_220_dialog_content = "何かありましたかな？愚息のことなら…",
  ui_story_5040_50400202_221_dialog_content = "お気持ちはよく分かります。",
  ui_story_5040_50400202_222_dialog_content = "親として、子どもが幸せになってほしいと願うのは当然ですもの。\n息子さんの純粋で子どもっぽいところが心配なのでしょう？",
  ui_story_5040_50400202_223_dialog_content = "今まで家を離れたこともない子が、\n急に荒野でその日暮らしの生活を送ると言い出したら…",
  ui_story_5040_50400202_224_dialog_content = "同じ立場であれば、私も受け入れられないでしょうね。",
  ui_story_5040_50400202_225_dialog_content = "ええ…あなたのおっしゃる通りですよ。\n生きていくことはそう簡単ではありません！",
  ui_story_5040_50400202_226_dialog_content = "アドニスは小さい頃からノーヴィオ先生の指導を受けて、\nよく気の利く賢い子に育ちましたが…純粋すぎるのです。",
  ui_story_5040_50400202_227_dialog_content = "何もその身で経験していないと、\nすべてが美しく見えるものですからね。",
  ui_story_5040_50400202_228_dialog_content = "でしたら、この機会に経験させてみてはいかがですか？",
  ui_story_5040_50400202_229_dialog_content = "ヒナも親元を離れなければ、\n生きる力を身に付けることはできません。",
  ui_story_5040_50400202_230_dialog_content = "生きていく力がなければ、ただ受け身で待つだけで、\n自分から幸せをつかみ取ることもできません。",
  ui_story_5040_50400202_231_dialog_content = "どこで誰と暮らすかということは、\nそれに比べたら小さな問題だと思います。",
  ui_story_5040_50400202_232_dialog_content = "そうは思われませんか？",
  ui_story_5040_50400202_233_dialog_content = "イェリアが何を言ったのか知らないけど、\n問題が解決できるなら、それでいいよね。",
  ui_story_5040_50400301_1_dialog_content = "郵便です！受け取りをお願いします！",
  ui_story_5040_50400301_2_dialog_content = "ありがとう、キアちゃん。\nこんな遅くまで仕事かい？",
  ui_story_5040_50400301_3_dialog_content = "冠月祭が近いので、皆さん手紙を待ってるでしょうから。\n少しでも早く届けたいんです。",
  ui_story_5040_50400301_4_dialog_content = "新人さんはマジメだね。頑張れよ。",
  ui_story_5040_50400301_5_dialog_content = "ふぅ…もうこんな時間ですか。",
  ui_story_5040_50400301_6_dialog_content = "ようやく終わりました。\n今日はここまでにしましょう。",
  ui_story_5040_50400301_7_dialog_content = "（アドニスさんからターラさんが記憶喪失になったと聞きましたが…\n昨日の暗鬼と関係があるんでしょうか？）",
  ui_story_5040_50400301_8_dialog_content = "（なんだか心配です。\n帰りに昨日の所に寄ってみましょう）",
  ui_story_5040_50400301_9_dialog_content = "（確かこの辺りだったはず…）",
  ui_story_5040_50400301_10_dialog_content = "…えっ？",
  ui_story_5040_50400301_11_dialog_content = "ここの霜…どうして紫なんでしょう？\n昨日の薬のせいでしょうか？",
  ui_story_5040_50400301_12_dialog_content = "紫の霜が森の中まで続いて…",
  ui_story_5040_50400301_13_dialog_content = "うーん、とにかく…見に行ってみましょう！",
  ui_story_5040_50400301_14_dialog_content = "<color=#e8d9bb>カア――カア――</color>",
  ui_story_5040_50400301_15_dialog_content = "（真っ暗…怖いですね、やっぱり戻りましょうか？）",
  ui_story_5040_50400301_16_dialog_content = "いや、でも…\n薬のあとがここで途切れてるということは…？",
  ui_story_5040_50400301_17_dialog_content = "あ…",
  ui_story_5040_50400301_18_dialog_content = "<size=50>きゃああ！！</size>",
  ui_story_5040_50400301_19_dialog_content = "そこにいるのは誰ですか！？",
  ui_story_5040_50400301_20_dialog_content = "た…助けて…",
  ui_story_5040_50400301_21_dialog_content = "わ、私を…助けて…",
  ui_story_5040_50400301_22_dialog_content = "だ、誰ですか！？",
  ui_story_5040_50400301_23_dialog_content = "わ…私！",
  ui_story_5040_50400301_24_dialog_content = "暗鬼！？",
  ui_story_5040_50400301_25_dialog_content = "や…やめて…",
  ui_story_5040_50400301_26_dialog_content = "…襲ったり…しない…",
  ui_story_5040_50400301_27_dialog_content = "…どういうことですか？公用語を話せるんですか？\nあなたは昨日、ターラさんを襲った暗鬼ですよね…",
  ui_story_5040_50400301_28_dialog_content = "私は…傷つけたり…しない…",
  ui_story_5040_50400301_29_dialog_content = "来ないで！何をするつもりですか！？",
  ui_story_5040_50400301_30_dialog_content = "た…助けて…",
  ui_story_5040_50400301_31_dialog_content = "ください…",
  ui_story_5040_50400301_32_dialog_content = "何ですって…？",
  ui_story_5040_50400301_33_dialog_content = "私…記憶が…ない…",
  ui_story_5040_50400301_34_dialog_content = "自分が…誰か…分からない…",
  ui_story_5040_50400301_35_dialog_content = "こわい…",
  ui_story_5040_50400301_36_dialog_content = "すごく…こわい…",
  ui_story_5040_50400301_37_dialog_content = "自分が誰か分からない？\nだったら、昨日はなぜ私たちを襲ったんですか？",
  ui_story_5040_50400301_38_dialog_content = "襲って…ない…",
  ui_story_5040_50400301_39_dialog_content = "薬…ほしかった…",
  ui_story_5040_50400301_40_dialog_content = "薬？",
  ui_story_5040_50400301_41_dialog_content = "市場に…隠れてた時…",
  ui_story_5040_50400301_42_dialog_content = "あの薬…万能と…聞いた…",
  ui_story_5040_50400301_43_dialog_content = "だから…あの…薬…記憶…取り戻せる…",
  ui_story_5040_50400301_44_dialog_content = "でも…あなたたちに…持っていかれた…",
  ui_story_5040_50400301_45_dialog_content = "そういうことでしたか…",
  ui_story_5040_50400301_46_dialog_content = "でも、そもそも暗鬼に記憶なんてあるんですか…？\nまさか、昔は光霊だったとでも？",
  ui_story_5040_50400301_47_dialog_content = "たぶん…そう…でも、忘れた…",
  ui_story_5040_50400301_48_dialog_content = "だから…こわい…",
  ui_story_5040_50400301_49_dialog_content = "（相手は暗鬼…関わらない方が…\nでも、ウソを言ってるようには思えませんし…）",
  ui_story_5040_50400301_50_dialog_content = "（暗鬼を助けたなんて知られたら、\nクーリエの仕事はできなくなりますよね？もしかしたら、捕まるかも…）",
  ui_story_5040_50400301_51_dialog_content = "寒い…",
  ui_story_5040_50400301_52_dialog_content = "ああ…もうっ！",
  ui_story_5040_50400301_53_dialog_content = "立って、私に付いてきてください。",
  ui_story_5040_50400301_54_dialog_content = "ありがとう…！",
  ui_story_5040_50400301_55_dialog_content = "先に言っておきますが、おかしなマネをしたら、\nすぐに言霊に助けを呼んでもらいますからね！",
  ui_story_5040_50400301_56_dialog_content = "わかった…",
  ui_story_5040_50400301_57_dialog_content = "…それから…そうですね…",
  ui_story_5040_50400301_58_dialog_content = "何か着た方がいいでしょう。",
  ui_story_5040_50400301_59_dialog_content = "よし、これで大丈夫です！",
  ui_story_5040_50400301_60_dialog_content = "いい…の…？",
  ui_story_5040_50400301_61_dialog_content = "構いませんが、本当にこの服でいいですか？\n以前花嫁の付き添いをやった時に着たドレスですよ。",
  ui_story_5040_50400301_62_dialog_content = "でも…こうすれば確かに光霊にも見えますね。\nドレスが少し浮いていますが…",
  ui_story_5040_50400301_63_dialog_content = "あり…がと…ドレス、気に入った。",
  ui_story_5040_50400301_64_dialog_content = "まぁ、いいでしょう。気に入ったなら着ていてください。\n私はキアです。あなたは？名前は覚えてますか？",
  ui_story_5040_50400301_65_dialog_content = "わから…ない。",
  ui_story_5040_50400301_66_dialog_content = "では、とりあえずセーブルと呼ぶことにしましょう。",
  ui_story_5040_50400301_67_dialog_content = "わ…わかった…",
  ui_story_5040_50400301_68_dialog_content = "昔のことはまったく覚えてないんですか？",
  ui_story_5040_50400301_69_dialog_content = "うん…",
  ui_story_5040_50400301_70_dialog_content = "ずっと北境暮らしだったとか？",
  ui_story_5040_50400301_71_dialog_content = "ちがう…たぶん…すごく…遠いところ…いた。",
  ui_story_5040_50400301_72_dialog_content = "そうですか。",
  ui_story_5040_50400301_73_dialog_content = "<color=#e8d9bb>次の日――</color>",
  ui_story_5040_50400301_74_dialog_content = "準備はいい？",
  ui_story_5040_50400301_75_dialog_content = "アドニス、ターラ。\n遠出になるから、持ち物は万全にね。",
  ui_story_5040_50400301_76_dialog_content = "はい！ニシンの缶詰めにシカ肉の缶詰め、サメ肉の缶詰めも\n全部1か月分は持ちました！",
  ui_story_5040_50400301_77_dialog_content = "それから氷干しにしたアザラシの肉にアマエビ、\nコウギョの皮の干物が2か月分あります。",
  ui_story_5040_50400301_78_dialog_content = "あとは緊急用の携帯コンロにハンマーとナイフ、\nそれからスコップにやかん、長靴や防寒具と雨具も…",
  ui_story_5040_50400301_79_dialog_content = "確認しておくけどぉ…アタシたち、白夜城に行くの。\n秘境でサバイバルしにいくんじゃないわよ？",
  ui_story_5040_50400301_80_dialog_content = "すごい荷物だ…\n白夜城をどんなところだと思ってるの？",
  ui_story_5040_50400301_81_dialog_content = "でも、白夜城の後はカナン城とR・W砂漠に行くのでしょう？\n万全の準備をしておかないと…",
  ui_story_5040_50400301_82_dialog_content = "それはそうだけど、たぶん必要ないんじゃないかな。\nこれから行くところで食べ物に困ることはないよ。",
  ui_story_5040_50400301_83_dialog_content = "…",
  ui_story_5040_50400301_84_dialog_content = "冗談じゃないわ！\n旅行？知らない人と？",
  ui_story_5040_50400301_85_dialog_content = "ターラ、落ち着いて。\n君に早く記憶を取り戻してもらうためなんだよ。",
  ui_story_5040_50400301_86_dialog_content = "まさか、昔のことを思い出したくないのかい？",
  ui_story_5040_50400301_87_dialog_content = "もちろん思い出したいわ。\nでも、こんなのめちゃくちゃよ。",
  ui_story_5040_50400301_88_dialog_content = "それに、あたしが失くしたのはあなたとの記憶だけよ。",
  ui_story_5040_50400301_89_dialog_content = "そうかも知れないけど、僕と君との思い出は、\n僕にとっても、君にとっても、大切なものなんだ。",
  ui_story_5040_50400301_90_dialog_content = "でも…",
  ui_story_5040_50400301_91_dialog_content = "君の気持ちは尊重するよ。\nでも僕は、旅をして君の記憶を取り戻したいんだ。",
  ui_story_5040_50400301_92_dialog_content = "君はどうしたい？\nもしどうしても嫌だっていうなら、無理強いはしないよ。",
  ui_story_5040_50400301_93_dialog_content = "（まったく…どうして結局、\nいつもあたしが折れちゃうのかしら）",
  ui_story_5040_50400301_94_dialog_content = "大丈夫だよ、ターラ。面倒なことは僕がするから！\n何も心配しなくていいんだ！",
  ui_story_5040_50400301_95_dialog_content = "君はただ旅を楽しんでくれればいいんだよ。",
  ui_story_5040_50400301_96_dialog_content = "知り合いでも何でもない人に優しくされたって、\n感動なんてできないわよ。",
  ui_story_5040_50400301_97_dialog_content = "とにかく、家に帰りたいわ。",
  ui_story_5040_50400301_98_dialog_content = "それなら、一緒に行こう。\n最後の目的地は砂漠だから。",
  ui_story_5040_50400301_99_dialog_content = "他の場所はとにかく楽しめばいいよ。\nどうしたら記憶を取り戻せるかは、道中で一緒に考えよう。",
  ui_story_5040_50400301_100_dialog_content = "うぅ…分かったわよ。",
  ui_story_5040_50400301_101_dialog_content = "準備ができたなら出発しよう。白夜城まで送るよ。\n僕もナルセールに報告しないといけないし。",
  ui_story_5040_50400301_102_dialog_content = "PlayerNameさん！待ってください！",
  ui_story_5040_50400301_103_dialog_content = "え？",
  ui_story_5040_50400301_104_dialog_content = "はぁ…はぁ…なんとか間に合いました！",
  ui_story_5040_50400301_105_dialog_content = "あら～？北境の小鳥ちゃん？\n息を切らしてるのもかわいいわねぇ。",
  ui_story_5040_50400301_106_dialog_content = "イェリア先輩、からかわないでください！\nオホン…皆さん、白夜城へ向かうんですよね？私たちも乗せていただけますか？",
  ui_story_5040_50400301_107_dialog_content = "「私たち」？",
  ui_story_5040_50400301_108_dialog_content = "あなた以外は、その暗鬼そっくりの変わった女の子のことかしらぁ？",
  ui_story_5040_50400301_109_dialog_content = "あ、暗鬼に似てるなんて、失礼ですよ！",
  ui_story_5040_50400301_110_dialog_content = "か、彼女はセーブルと言って…\nわ、私の遠い親戚なんです！",
  ui_story_5040_50400301_111_dialog_content = "こ…こんにち…は。",
  ui_story_5040_50400301_112_dialog_content = "（セーブルから強烈な暗力を感じる。\n絶対に気のせいじゃない）",
  ui_story_5040_50400301_113_dialog_content = "（でも、暴れたりするつもりはないみたいだ…\nまずは様子を見てみよう）",
  ui_story_5040_50400301_114_dialog_content = "ふ～ん、そうだったのぉ。\n服も変わってるわねぇ。",
  ui_story_5040_50400301_115_dialog_content = "せ、セーブルはドレスが大好きなんです！\nせっかくのおでかけだからと、頑張っておしゃれをしてるんですよ。",
  ui_story_5040_50400301_116_dialog_content = "（なぜかは分かりませんが、セーブルがドレスを大好きなことは本当…\n何か特別な理由でもあるんでしょうか？）",
  ui_story_5040_50400301_117_dialog_content = "君たちも白夜城に行きたいの？",
  ui_story_5040_50400301_118_dialog_content = "いい時期ですし、セーブルをいろいろなところに連れて行ってあげたいんです。\n乗せていってもらえませんか？ちょうど白夜城宛ての手紙もありますし…",
  ui_story_5040_50400301_119_dialog_content = "もちろん、構わないよ。\n準備ができたなら、出発しようか？",
  ui_story_5040_50400301_120_dialog_content = "<color=#e8d9bb>ソラヴァン内部</color>",
  ui_story_5040_50400301_121_dialog_content = "ところで、イェリアは休まなくて大丈夫なの？",
  ui_story_5040_50400301_122_dialog_content = "ふふ、読書も休憩のうちよ～。",
  ui_story_5040_50400301_123_dialog_content = "疲れなんかまったく感じないわぁ。",
  ui_story_5040_50400301_124_dialog_content = "疲れたなら寝るといいわ、空の末裔くん。",
  ui_story_5040_50400301_125_dialog_content = "イェリアってすごいんだね。\n君の読んでる本、僕にはまったく分からないや。",
  ui_story_5040_50400301_126_dialog_content = "得意分野は人それぞれでしょ？\nアタシは古書が好きなだけよ～。",
  ui_story_5040_50400301_127_dialog_content = "光霊づきあいより、ずっと気楽だわ。",
  ui_story_5040_50400301_128_dialog_content = "えっ？",
  ui_story_5040_50400301_129_dialog_content = "それはそうと、白夜城に着いたら、\nナルセールのところへ行くの？",
  ui_story_5040_50400301_130_dialog_content = "お互いやらなきゃいけないこともあるし、\n戻ったらまず、状況説明ね。",
  ui_story_5040_50400301_131_dialog_content = "きゃああ！！",
  ui_story_5040_50400301_132_dialog_content = "！？",
  ui_story_5040_50400301_133_dialog_content = "暗鬼です！イェリア先輩、PlayerNameさん、気を付けて！",
  ui_story_5040_50400301_134_dialog_content = "た…助けて…！",
  ui_story_5040_50400301_135_dialog_content = "巨像の中に暗鬼が？\nさっき紛れ込んできたのかな…？",
  ui_story_5040_50400301_136_dialog_content = "話はあとよ～。\nまずは片付けちゃわないと。",
  ui_story_5040_50400302_1_dialog_content = "<color=#e8d9bb>暗鬼を退治し、それぞれ休息をとった。\nしばらく後、無事白夜城に到着した――</color>",
  ui_story_5040_50400302_2_dialog_content = "白夜城の入城検査って本当に厳しいね。\n幸い、僕たちは大して調べられなかったけど…",
  ui_story_5040_50400302_3_dialog_content = "（空の末裔さんがいなかったら、\nセーブルの正体がバレていたかもしれません。付いてきて正解でした…）",
  ui_story_5040_50400302_4_dialog_content = "PlayerNameさん、イェリア先輩！\n私は配達ついでにセーブルを案内したいので、これで失礼します！",
  ui_story_5040_50400302_5_dialog_content = "…早い！もうどこかへ行っちゃった。",
  ui_story_5040_50400302_6_dialog_content = "…",
  ui_story_5040_50400302_7_dialog_content = "おお…ここが白夜城ですか！\n北境とは雰囲気が全然違いますね。",
  ui_story_5040_50400302_8_dialog_content = "ターラ、君はそう思わないかい？",
  ui_story_5040_50400302_9_dialog_content = "…あたしは初めてじゃないから。",
  ui_story_5040_50400302_10_dialog_content = "…そ、そうだったね。",
  ui_story_5040_50400302_11_dialog_content = "じゃあ、このままナルセールのところへ行こう。",
  ui_story_5040_50400302_12_dialog_content = "ナルセール！久しぶり！",
  ui_story_5040_50400302_13_dialog_content = "あなたは…アドニスではありませんか。",
  ui_story_5040_50400302_14_dialog_content = "本当にお久しぶりです。どうして白夜城へ？\nノーヴィオ先生とご両親はお元気ですか？",
  ui_story_5040_50400302_15_dialog_content = "みんな元気だよ。心配はいらない。",
  ui_story_5040_50400302_16_dialog_content = "こちらの女性が手紙によく書いていたターラさ。",
  ui_story_5040_50400302_17_dialog_content = "…",
  ui_story_5040_50400302_18_dialog_content = "ナルセール、実はちょっと事情があって\n白夜城に戻ってきたんだ…",
  ui_story_5040_50400302_19_dialog_content = "<color=#e8d9bb>ナルセールに状況説明をした――</color>",
  ui_story_5040_50400302_20_dialog_content = "そんなことがあったのですか？",
  ui_story_5040_50400302_21_dialog_content = "記憶を失う魔法の薬など、初めて聞きました…",
  ui_story_5040_50400302_22_dialog_content = "そうなんだよ。僕も困ってるんだ。",
  ui_story_5040_50400302_23_dialog_content = "私に何かできることはありますか？\n長い付き合いです。遠慮なくおっしゃってください。",
  ui_story_5040_50400302_24_dialog_content = "実はイェリアさんの提案でね。\nクーリエ隊の冠月祭の催しに参加して、印章を集めることにしたんだ。",
  ui_story_5040_50400302_25_dialog_content = "そうすれば、いろいろなところを見てまわれるし、\nターラの記憶喪失を治す手がかりも見つかるかもしれないから。",
  ui_story_5040_50400302_26_dialog_content = "羽の印章ですか。",
  ui_story_5040_50400302_27_dialog_content = "確かにクーリエ隊は冠月祭のシーズンに、\n若いカップル向けの「試練」を開催しています。",
  ui_story_5040_50400302_28_dialog_content = "ただ…",
  ui_story_5040_50400302_29_dialog_content = "どうしたんだい？何か不都合でも？",
  ui_story_5040_50400302_30_dialog_content = "私たちは陛下のご指導を賜っていた頃からの長いお付き合いです。\nよくノーヴィオ先生やあなたを氷の宮殿で見かけました。",
  ui_story_5040_50400302_31_dialog_content = "ですから、あなたがターラさんを生涯の伴侶とするという決心が、\n熟慮の末の結論であることを願っています。",
  ui_story_5040_50400302_32_dialog_content = "冠月祭も、クーリエ隊のイベントも、形式にすぎません。\n大切なのはあなたたち自身の気持ちです。",
  ui_story_5040_50400302_33_dialog_content = "うん、分かってるよ。",
  ui_story_5040_50400302_34_dialog_content = "冠月祭をきっかけにしたいというのなら、\n私に反対する理由はありません。",
  ui_story_5040_50400302_35_dialog_content = "ありがとう、ナルセール！",
  ui_story_5040_50400302_36_dialog_content = "それで、冠月祭の試練ですが…",
  ui_story_5040_50400302_37_dialog_content = "こちらはクーリエ隊が今年の冠月祭に出す記念切手です。\nこれを全部売り切れば、試練達成となります。",
  ui_story_5040_50400302_38_dialog_content = "分かった、それぐらい簡単だ！\nねぇ、ターラ？",
  ui_story_5040_50400302_39_dialog_content = "ええ、たぶんね…",
  ui_story_5040_50400302_40_dialog_content = "でも、そんな細かい仕事、あたしはやったことないわ。",
  ui_story_5040_50400302_41_dialog_content = "2人で力を合わせれば、きっと大丈夫だよ。\nさあ、今すぐ行こう！",
  ui_story_5040_50400302_42_dialog_content = "幸運を祈ってるよ。",
  ui_story_5040_50400302_43_dialog_content = "お疲れ様でした、PlayerNameさん、イェリア。",
  ui_story_5040_50400302_44_dialog_content = "ですが、アドニスたちはクーリエ隊の他の支部へも行くようですね。\nPlayerNameさん、お手数ですがお願いできますか？",
  ui_story_5040_50400302_45_dialog_content = "もちろん！人助けなら喜んで手伝うよ。",
  ui_story_5040_50400302_46_dialog_content = "じゃあ、空の末裔くんは休んでるといいわぁ。",
  ui_story_5040_50400302_47_dialog_content = "試練の方はアタシが2人に付き添うから。",
  ui_story_5040_50400302_48_dialog_content = "イェリア、その前に少しお話があります。",
  ui_story_5040_50400302_49_dialog_content = "…",
  ui_story_5040_50400302_50_dialog_content = "何か言うことはありませんか？",
  ui_story_5040_50400302_51_dialog_content = "さあねぇ、何のことかしらぁ？",
  ui_story_5040_50400302_52_dialog_content = "とぼけないでください。\nそちらの支部から白夜城に転送されてきたこの荷物の山、何だか分かりますか？",
  ui_story_5040_50400302_53_dialog_content = "ええ～？何だったかしらねぇ？\nアタシ、あまりよく見てないし～。",
  ui_story_5040_50400302_54_dialog_content = "きちんと確認もせずに転送してくるなんて…\nおかげでカラスと私はてんてこまいです。",
  ui_story_5040_50400302_55_dialog_content = "冠月祭はただでさえ荷物や手紙が多いというのに、\nあなたのおかげで白夜城のクーリエ隊は麻痺寸前ですよ。",
  ui_story_5040_50400302_56_dialog_content = "上にはまだ報告していませんが、\n報告が上がったら、そうとうなお叱りを受けることになるでしょう。",
  ui_story_5040_50400302_57_dialog_content = "借りってことにしておいてよ。\n今回だって代わりに北境までお使いに行ってあげたじゃな～い？",
  ui_story_5040_50400302_58_dialog_content = "はぁ…それにしても、アドニスがこんなことになっているとは…",
  ui_story_5040_50400302_59_dialog_content = "最後まで2人を助けてあげてください。",
  ui_story_5040_50400302_60_dialog_content = "まったく、面倒ねぇ…アタシには理解できないわぁ。\nどう見ても不釣り合いじゃない。ムリに一緒になることないのに。",
  ui_story_5040_50400302_61_dialog_content = "人は複雑な存在だと、\nいつも言っているのはあなたでしょう？",
  ui_story_5040_50400302_62_dialog_content = "いずれあなたにも分かることです、イェリア。\n永遠に独りで生きていける者などいないのですから。",
  ui_story_5040_50400302_63_dialog_content = "ターラ、こっちが個別包装の切手だよ。",
  ui_story_5040_50400302_64_dialog_content = "君は毎年、冠月祭の切手を送ってきてくれてたよね。\n覚えてるかい？どれも大切にとってあるんだ。",
  ui_story_5040_50400302_65_dialog_content = "そうなの？覚えてないわ。",
  ui_story_5040_50400302_66_dialog_content = "いいんだ。これからは僕が君に切手を送るよ。\nそれにしても、今年のデザインもステキだね。",
  ui_story_5040_50400302_67_dialog_content = "あ…！袋が！",
  ui_story_5040_50400302_68_dialog_content = "気を付けて！",
  ui_story_5040_50400302_69_dialog_content = "よかった、落とさなくて。",
  ui_story_5040_50400302_70_dialog_content = "こんな細かい仕事、あたしにはムリよ。\n向いてないの。銃でも売る方が合ってるわ。",
  ui_story_5040_50400302_71_dialog_content = "アハハ、そうかもね。でも、得意なものは人それぞれだよ。\n同じ枝に咲く花だって、それぞれ違いがあるぐらいだから。",
  ui_story_5040_50400302_72_dialog_content = "切手は僕がやるから、\nお客さんの対応をお願いするよ。",
  ui_story_5040_50400302_73_dialog_content = "それなら、出来ないこともないかしら。",
  ui_story_5040_50400302_74_dialog_content = "<color=#e8d9bb>しばらくして――</color>",
  ui_story_5040_50400302_75_dialog_content = "記念切手を1つくださいますか？",
  ui_story_5040_50400302_76_dialog_content = "私のはまだ？",
  ui_story_5040_50400302_77_dialog_content = "もう少し待って。\n冠月祭を記念する大事な切手だから、きちんとラッピングしないと。",
  ui_story_5040_50400302_78_dialog_content = "はい、お待たせしました！",
  ui_story_5040_50400302_79_dialog_content = "ターラ、大丈夫かい？",
  ui_story_5040_50400302_80_dialog_content = "口を動かすだけだもの、平気よ。\nあなたこそ、切手の扱いに気を付けて。",
  ui_story_5040_50400302_81_dialog_content = "ふ～ん、繁盛してるみたいじゃない。",
  ui_story_5040_50400302_82_dialog_content = "ええ、今のところはね。",
  ui_story_5040_50400302_83_dialog_content = "そうねぇ…これなら売り切れそうね、いいことだわ。",
  ui_story_5040_50400302_84_dialog_content = "さあ、これが最後の1セット…完売だ！",
  ui_story_5040_50400302_85_dialog_content = "ふぅ、なんとか終わったわ。",
  ui_story_5040_50400302_86_dialog_content = "おめでとう、二人とも。",
  ui_story_5040_50400302_87_dialog_content = "もうちょっと心を込めて言ったら？",
  ui_story_5040_50400302_88_dialog_content = "ふわ…すみません、クーリエ隊の切手はありますかしら？",
  ui_story_5040_50400302_89_dialog_content = "ごめんなさい、\nちょうど最後の1つが売れちゃったところよ。",
  ui_story_5040_50400302_90_dialog_content = "今年の切手もステキだと思いますけれど、\n私が欲しいのは別のものですわ。",
  ui_story_5040_50400302_91_dialog_content = "去年の冠月祭の記念切手はまだ残っていますかしら？\nもしあれば…十分なお礼をさせていただきますわ。",
  ui_story_5040_50400302_92_dialog_content = "それは…",
  ui_story_5040_50400302_93_dialog_content = "僕たちでは臨時のお手伝いなので、分かりませんね…\nイェリアさん、ご存じですか？",
  ui_story_5040_50400302_94_dialog_content = "クーリエ隊は同じ切手を2度は売らないし、\n必要以上の在庫も持たないわぁ。",
  ui_story_5040_50400302_95_dialog_content = "少なくとも、表のルートで入手するのはムリねぇ。",
  ui_story_5040_50400302_96_dialog_content = "そうですか…どうしましょう…？",
  ui_story_5040_50400302_97_dialog_content = "何かお困りなんですか？",
  ui_story_5040_50400302_98_dialog_content = "ええ…実は私、友人に頼まれて切手を買いにきました。",
  ui_story_5040_50400302_99_dialog_content = "友人の恋人が啓光で暮らしているので…\n友人はその恋人に、毎年冠月祭の切手を送っていますの。",
  ui_story_5040_50400302_100_dialog_content = "ただ、友人の家はたいそう保守的なご家庭で…\n2人のお付き合い、親御さんにひどく反対されているのです。",
  ui_story_5040_50400302_101_dialog_content = "ですから、私を通してこっそりと切手を買い、\n手紙を送るしかありませんの。",
  ui_story_5040_50400302_102_dialog_content = "あらあら、まさに白夜城って感じの話ねぇ。",
  ui_story_5040_50400302_103_dialog_content = "白夜城にも切手を送る風習があるの？",
  ui_story_5040_50400302_104_dialog_content = "白夜城では、冠月祭になると恋人同士が互いに切手を贈るわねぇ。\nまぁ、貴族の人たちはもっとゼイタクにやるらしいけど。",
  ui_story_5040_50400302_105_dialog_content = "そうですわねぇ。私は見栄を張り合って無駄遣いするよりも、\nゆっくり二度寝でもしている方が好きですが…",
  ui_story_5040_50400302_106_dialog_content = "…ああ、話を戻しますと、その友人の恋人がどうやら、\n去年の記念切手をうっかり失くしてしまったらしいのです…",
  ui_story_5040_50400302_107_dialog_content = "とても気を落としていて、自分を責めているようですわ。\nそれで友人が恋人をなぐさめようと、同じものを私に頼んだというわけですの。",
  ui_story_5040_50400302_108_dialog_content = "たかが切手よね？\n他のもので埋め合わせすればいいんじゃない？",
  ui_story_5040_50400302_109_dialog_content = "そんなことはできないよ。思い出の詰まったものなんだ。\nどんな豪華な贈り物だって、代わりにはならない。",
  ui_story_5040_50400302_110_dialog_content = "白夜城の貴族と啓光の女の子ねぇ…面白いわぁ。",
  ui_story_5040_50400302_111_dialog_content = "きっと障害も多いでしょ？",
  ui_story_5040_50400302_112_dialog_content = "乗り越えられないものではないと思いますが、\n確かに障害は多いですし、長い道のりでしょうね。",
  ui_story_5040_50400302_113_dialog_content = "友人は時間をかけてじっくりご両親や友人たちを説得し、\n自分の気持ちと決意を分かってもらうと言っていましたわ。",
  ui_story_5040_50400302_114_dialog_content = "でも、まだまだ時間がかかるでしょうねぇ。",
  ui_story_5040_50400302_115_dialog_content = "白夜城って聞いた話の通り、\n家同士の釣り合いにこだわるのねぇ。",
  ui_story_5040_50400302_116_dialog_content = "そうかもしれません。\nですが、釣り合いの取れた大貴族同士でも、幸せになれるとは限りませんわ。",
  ui_story_5040_50400302_117_dialog_content = "法廷勤めをしていると、\n貴族の離婚話もしばしば扱うことになりますの。",
  ui_story_5040_50400302_118_dialog_content = "どの案件も複雑な事情ばかりで…\n貴族間の利益関係も絡みますし、解決には骨を折ります。",
  ui_story_5040_50400302_119_dialog_content = "ですので、誰も引き受けたがりませんわ。",
  ui_story_5040_50400302_120_dialog_content = "貴族の人と言えども、心の悩みは尽きないんですね。",
  ui_story_5040_50400302_121_dialog_content = "そうです。ですから私は、\n己の気持ちに正直になることが一番だと思っておりますわ。",
  ui_story_5040_50400302_122_dialog_content = "波風を立てることを恐れて\n無理に「釣り合う」人と一緒になっても、幸せにはなれません。",
  ui_story_5040_50400302_123_dialog_content = "白夜城の貴族からそんな言葉を聞くなんて、驚いたわねぇ。",
  ui_story_5040_50400302_124_dialog_content = "選ぶ道は人それぞれと言えばいいのでしょうか？\n愛情にそもそも定義はありませんし、好きは好きでしかありません。",
  ui_story_5040_50400302_125_dialog_content = "誰かを好きになることは止められません。\n暮らしている場所や出身とは関係のないことですわ。",
  ui_story_5040_50400302_126_dialog_content = "その点、私も身をもって知っておりますから。",
  ui_story_5040_50400302_127_dialog_content = "とても素晴らしいお話です！\n僕もその通りだと思います！",
  ui_story_5040_50400302_128_dialog_content = "あら～？ということは、\nあなたにも好きな人がいるのかしら？",
  ui_story_5040_50400302_129_dialog_content = "いいえ。ただ少し前に偶然、\nモフモフした興味深い生き物に出会ったのです。",
  ui_story_5040_50400302_130_dialog_content = "公用語を話せる、本当に不思議な生き物でした。",
  ui_story_5040_50400302_131_dialog_content = "昨日その子に手紙を送ったのですが、\n返事をもらえるかどうか…",
  ui_story_5040_50400302_132_dialog_content = "イェリアさん、彼女の力になれる方法、\n何かありませんか？",
  ui_story_5040_50400302_133_dialog_content = "…",
  ui_story_5040_50400302_134_dialog_content = "アタシにもどうしようもないわねぇ。ただ…",
  ui_story_5040_50400302_135_dialog_content = "それなりの対価を払う気があるなら、\n影ノ街のアルーラに聞いてみたら？彼女のコレクションは相当なものよ。",
  ui_story_5040_50400302_136_dialog_content = "切手ぐらいは持ってるでしょ。",
  ui_story_5040_50400302_137_dialog_content = "そうですか、ありがとうございます！\n助かりましたわ。",
  ui_story_5040_50400302_138_dialog_content = "それでは、また眠くならないうちに、\n影ノ街へ行ってまいりますわ。",
  ui_story_5040_50400302_139_dialog_content = "イェリアってほんとに何でも知ってるのね。",
  ui_story_5040_50400302_140_dialog_content = "望みのものが手に入る事を祈るよ。",
  ui_story_5040_50400302_141_dialog_content = "とにかく…僕たちの仕事は無事に終わったね。\n戻って印を押してもらおう！",
  ui_story_5040_50400302_142_dialog_content = "そうね…",
  ui_story_5040_50400302_143_dialog_content = "ターラ？具合でも悪いの？",
  ui_story_5040_50400302_144_dialog_content = "な、何でもないわ。",
  ui_story_5040_50400302_145_dialog_content = "…",
  ui_story_5040_50400302_146_dialog_content = "<color=#e8d9bb>その頃――</color>",
  ui_story_5040_50400302_147_dialog_content = "何の収穫もナシですか…",
  ui_story_5040_50400302_148_dialog_content = "やっぱり何も思い出せませんか？",
  ui_story_5040_50400302_149_dialog_content = "ご…ごめん…",
  ui_story_5040_50400302_150_dialog_content = "謝らなくていいんですよ。\n何も悪いことはしてないんですから。",
  ui_story_5040_50400302_151_dialog_content = "ほかに何か手がかりは…？",
  ui_story_5040_50400302_152_dialog_content = "あ…あ…あれ…",
  ui_story_5040_50400302_153_dialog_content = "え？",
  ui_story_5040_50400302_154_dialog_content = "あれ…手に…持ってる…",
  ui_story_5040_50400302_155_dialog_content = "誰が、何を持ってるんですか？",
  ui_story_5040_50400302_156_dialog_content = "男の人…",
  ui_story_5040_50400302_157_dialog_content = "切…手…",
  ui_story_5040_50400302_158_dialog_content = "切手？今通り過ぎた人が持っていたものですか？\nあれは冠月祭の切手ですね。",
  ui_story_5040_50400302_159_dialog_content = "何か思い出したんですか？",
  ui_story_5040_50400302_160_dialog_content = "たぶん…持ってる…",
  ui_story_5040_50400302_161_dialog_content = "おや、これは…どこで手に入れたんです！？\n何年も前の冠月祭の切手ですよ！",
  ui_story_5040_50400302_162_dialog_content = "私…たぶん…たくさん…持ってる…",
  ui_story_5040_50400302_163_dialog_content = "同じような切手を、ですか？",
  ui_story_5040_50400302_164_dialog_content = "うん…",
  ui_story_5040_50400302_165_dialog_content = "切手をたくさん持ってたってことは、\nよく手紙を出してたと考えられますね…",
  ui_story_5040_50400302_166_dialog_content = "手がかりになるかもしれません！クーリエ隊が預かっている\n受取人不在の手紙を調べてみましょう！何か分かるかもしれません。",
  ui_story_5040_50400302_167_dialog_content = "あ、ありがと…キ…キア…",
  ui_story_5040_50400302_168_dialog_content = "<color=#e8d9bb>しばらくして――</color>",
  ui_story_5040_50400302_169_dialog_content = "ありませんか？",
  ui_story_5040_50400302_170_dialog_content = "全部…ちがう…",
  ui_story_5040_50400302_171_dialog_content = "うーん…とすると、白夜城に住んでいたわけではないのかもしれませんね。",
  ui_story_5040_50400302_172_dialog_content = "でも、手がかりができてよかったですね。\nアテもなく探すよりはずっとマシです。",
  ui_story_5040_50400302_173_dialog_content = "このままPlayerNameさんたちに付いて行って、\n啓光とR・Wの支部も探してみましょう。",
  ui_story_5040_50400302_174_dialog_content = "心配いりません、きっと見つかりますよ。",
  ui_story_5040_50400302_175_dialog_content = "キ…ア…",
  ui_story_5040_50400302_176_dialog_content = "ありが、とう…",
  ui_story_5040_50400302_177_dialog_content = "ど、どうして…助けて、くれる？",
  ui_story_5040_50400302_178_dialog_content = "自分でも分かりません。\nきっと困ってる人を放っておけない性格なんでしょう。",
  ui_story_5040_50400302_179_dialog_content = "（本当にどうかしてるのでしょうね…\n暗鬼にここまでするなんて…いったい私は何を考えてるんでしょうか）",
  ui_story_5040_50400302_180_dialog_content = "（エメラルド先生なら、どうしたでしょう？）",
  ui_story_5040_50400401_1_dialog_content = "<color=#e8d9bb>アドニス一行が無事に試練を達成し、\nナルセールに報告した後――</color>",
  ui_story_5040_50400401_2_dialog_content = "これがクーリエ隊の羽の印章？初めて見たよ。",
  ui_story_5040_50400401_3_dialog_content = "とても精巧に彫られていますね！",
  ui_story_5040_50400401_4_dialog_content = "ターラ、ほら！",
  ui_story_5040_50400401_5_dialog_content = "…何するの、なれなれしくしないで。",
  ui_story_5040_50400401_6_dialog_content = "印章自体にものすごく価値があるってワケじゃないけど、\n記念としての価値は高いわよ。",
  ui_story_5040_50400401_7_dialog_content = "ずっと昔、まだ隊としての組織がなかった時代から、\nクーリエは喜びや祝い事の象徴だったの。",
  ui_story_5040_50400401_8_dialog_content = "貴族の結婚式にもクーリエが呼ばれたりするの？",
  ui_story_5040_50400401_9_dialog_content = "白夜城の貴族たちこそ、いちばん風習にうるさいわ。\n大金をはたいてでも、っていう貴族もいるわねぇ。",
  ui_story_5040_50400401_10_dialog_content = "そういう事情もクーリエ隊が\nイベントをするようになった理由の1つよ。",
  ui_story_5040_50400401_11_dialog_content = "冠月祭は白夜城が発祥だから、とくに白夜城ではねぇ。\n風習もより深く根付いてるってわけ。",
  ui_story_5040_50400401_12_dialog_content = "ヘンなの。砂漠では祝日とかそういうの、\nまったく気にしないわ。",
  ui_story_5040_50400401_13_dialog_content = "典礼や儀式って、ロマンチックだと思うけどな。",
  ui_story_5040_50400401_14_dialog_content = "白夜城みたいな階級社会だと、\nそういうのって統治者が自分たちより低い階級を抑え込む手段なのよねぇ。",
  ui_story_5040_50400401_15_dialog_content = "だから、ことさら重んじられるの。",
  ui_story_5040_50400401_16_dialog_content = "難しい話だね…",
  ui_story_5040_50400401_17_dialog_content = "イェリアはあたしの分からないことばっかり言うわね。",
  ui_story_5040_50400401_18_dialog_content = "じゃあ、次は…",
  ui_story_5040_50400401_19_dialog_content = "イェリア、どこかその辺をぶらぶらしない？\n気分転換がしたいわ。",
  ui_story_5040_50400401_20_dialog_content = "なら、僕も一緒に…",
  ui_story_5040_50400401_21_dialog_content = "PlayerName、アドニスと一緒にいて。\nあたしは少し落ち着きたいの。別行動しましょ。",
  ui_story_5040_50400401_22_dialog_content = "僕はどっちでもいいよ。",
  ui_story_5040_50400401_23_dialog_content = "…",
  ui_story_5040_50400401_24_dialog_content = "はぁ…",
  ui_story_5040_50400401_25_dialog_content = "お芝居に疲れちゃったのかしら？",
  ui_story_5040_50400401_26_dialog_content = "分からなくなってきたの。\nアドニスはあたしが記憶喪失だって本気で信じてるみたい。",
  ui_story_5040_50400401_27_dialog_content = "一緒に切手を売ってた時のアドニスは…\nあたしのよく知ってる、繊細で優しいアドニスだった。",
  ui_story_5040_50400401_28_dialog_content = "でも、だからってあたしたちの間の問題が解決するわけじゃないし、\n肝心なことになれば、どうせまた弱気で臆病になっちゃうんでしょ。",
  ui_story_5040_50400401_29_dialog_content = "あたしたちは…最初からまったく別世界の住人で、\n一緒にいるべきじゃなかったのかもしれない…",
  ui_story_5040_50400401_30_dialog_content = "でも、好きだって気持ちを抑えられなくて、\nその事実を認めたくなかっただけなのかも。",
  ui_story_5040_50400401_31_dialog_content = "自分がどんな人間になるかは選べても、\n他人の考えはどうにもできないわ。",
  ui_story_5040_50400401_32_dialog_content = "自分が「この人だ」って決めたなら、\nどんな結果でも受け止めることね。",
  ui_story_5040_50400401_33_dialog_content = "気持ちが強くなればなるほど、\n失った時の痛みは強いわよ。",
  ui_story_5040_50400401_34_dialog_content = "…イェリアも経験があるの？",
  ui_story_5040_50400401_35_dialog_content = "あるワケないじゃな～い？\n傷付くって分かってることなんて、わざわざやらないわ。",
  ui_story_5040_50400401_36_dialog_content = "でも、いいことだってたくさんあるのよ。\nアドニスと一緒にいると楽しい時の方が多いわ。",
  ui_story_5040_50400401_37_dialog_content = "足りない安心感を埋め合わせてるだけでしょ。\n本質的には、価値の交換をしてるだけ。",
  ui_story_5040_50400401_38_dialog_content = "今のあなただって、相手から返ってくるものが\n期待と違ったから不満でいる。違う？",
  ui_story_5040_50400401_39_dialog_content = "あたしは…",
  ui_story_5040_50400401_40_dialog_content = "そんなの…知らないわ。\nあたしたちの感情を取引みたいに言わないで。",
  ui_story_5040_50400401_41_dialog_content = "好きにすればいいわ。",
  ui_story_5040_50400401_42_dialog_content = "ただ、どんなことも自分でやってみて初めて分かるものよ。\nここまできた以上、あなたも急ぐ必要はないわ。",
  ui_story_5040_50400401_43_dialog_content = "あなた自身のことなんだから、\n他人が何と言おうが関係ないでしょ？",
  ui_story_5040_50400401_44_dialog_content = "じっくり見極めることね。\n自分の気持ちに正直になって、決断すればいいだけよ～。",
  ui_story_5040_50400401_45_dialog_content = "…",
  ui_story_5040_50400401_46_dialog_content = "ここが影ノ街だよ。白夜城とは全然雰囲気が違うでしょ？",
  ui_story_5040_50400401_47_dialog_content = "そうですね…",
  ui_story_5040_50400401_48_dialog_content = "ほら見て。白夜城が真上にあるんだ。",
  ui_story_5040_50400401_49_dialog_content = "影ノ街の人たちにとって、\nこういう時期は絶好の稼ぎ時だろうね…",
  ui_story_5040_50400401_50_dialog_content = "変わった人も多いけど、\n影ノ街には面白いものがたくさんあるんだよ。",
  ui_story_5040_50400401_51_dialog_content = "何か気になるものはある？",
  ui_story_5040_50400401_52_dialog_content = "…",
  ui_story_5040_50400401_53_dialog_content = "（ダメだ…完全に落ち込んじゃってる）",
  ui_story_5040_50400401_54_dialog_content = "はぁ…いったいどうすればいいのか…\n僕にはもう分かりません…",
  ui_story_5040_50400401_55_dialog_content = "何をしても違う気がするんです。\n少しでも変化があれば…次の手がかりになるんですが…",
  ui_story_5040_50400401_56_dialog_content = "それは…",
  ui_story_5040_50400401_57_dialog_content = "昔は何でも話して、お互い知らない世界のことを知って、\nとても楽しくて…それがどうしてこんなことに…",
  ui_story_5040_50400401_58_dialog_content = "PlayerNameさん、空の末裔ならたくさんの女性とお知り合いでしょう？\n僕の今の気持ち、分かってもらえますか？",
  ui_story_5040_50400401_59_dialog_content = "お、女の子の知り合いなんてそんなにいないよ…",
  ui_story_5040_50400401_60_dialog_content = "でも、僕が思うに、本当に深い気持ちで結ばれてるなら、\nどんな困難でも乗り越えられるんじゃないかな？",
  ui_story_5040_50400401_61_dialog_content = "僕にも2人親友がいて、一緒にいろんな困難を乗り越えてきたんだ。\n命の危険だってあったよ。",
  ui_story_5040_50400401_62_dialog_content = "そういう経験の中でだんだんお互いを信用するようになって、\n相手のために犠牲になることだって怖くなくなったんだ。",
  ui_story_5040_50400401_63_dialog_content = "君とターラもそうなんじゃない？",
  ui_story_5040_50400401_64_dialog_content = "も、もちろん、ターラのためなら何だってできます。\n命をささげたって構いません。",
  ui_story_5040_50400401_65_dialog_content = "でも、僕は優柔不断で、すぐに決断できないことも多くて…\nターラには男らしくないと思われているでしょうね。",
  ui_story_5040_50400401_66_dialog_content = "そんなことないよ。\n性格は皆違うんだし、何が男らしさかなんて決まりはないよ。",
  ui_story_5040_50400401_67_dialog_content = "君に惹かれるところがあったから、\nターラだって結婚しようって思ったんじゃない？完璧である必要はないよ。",
  ui_story_5040_50400401_68_dialog_content = "ぐすっ…タ、ターラもそんな風に思ってくれたら…！",
  ui_story_5040_50400401_69_dialog_content = "…わ、分かったから、泣かないで…",
  ui_story_5040_50400401_70_dialog_content = "おうおうおう…",
  ui_story_5040_50400401_71_dialog_content = "こいつは大した光景じゃねえか？",
  ui_story_5040_50400401_72_dialog_content = "インスピレーションが来たぜ！ギン！",
  ui_story_5040_50400401_73_dialog_content = "世間の目が厳しく、お天道様の下じゃ会えねえ2人が――",
  ui_story_5040_50400401_74_dialog_content = "堂々と抱き合ってんじゃねーか。",
  ui_story_5040_50400401_75_dialog_content = "恋人たちの季節、冠月祭にも、\n影ノ街の人知れぬ片隅で密会するしかねえ――",
  ui_story_5040_50400401_76_dialog_content = "辺りに人だらけじゃねーか。",
  ui_story_5040_50400401_77_dialog_content = "こいつらのために何かしてやりたいぜ…\nついでにビジネスチャンスもつかむんだ！どうだ、いいアイデアだろ？",
  ui_story_5040_50400401_78_dialog_content = "ああ、そーだな。",
  ui_story_5040_50400401_79_dialog_content = "あの、何か誤解してない…？",
  ui_story_5040_50400401_80_dialog_content = "そこのお坊ちゃん、あんたいい感じだねぇ。\n名前は？",
  ui_story_5040_50400401_81_dialog_content = "ぼ、僕ですか？アドニスといいます。",
  ui_story_5040_50400401_82_dialog_content = "アドニスか。あんた、実にいいぜ。\n隣のやつには大きく差をつけてるな。",
  ui_story_5040_50400401_83_dialog_content = "なんで急に僕に矛先が向くの？",
  ui_story_5040_50400401_84_dialog_content = "あんた、愛する女のためならどんな無茶もするタイプだな？\nオレには分かるぜ…",
  ui_story_5040_50400401_85_dialog_content = "オレとオレのキャンディもビンビン感じてるぜ。",
  ui_story_5040_50400401_86_dialog_content = "回りくどい話は抜きだ。冠月祭のために滅多にお目にかかれねえ絵を\n仕入れたんだが、あんたにピッタリなのがあってな。",
  ui_story_5040_50400401_87_dialog_content = "許されざる恋人同士を描いた作品だ。",
  ui_story_5040_50400401_88_dialog_content = "今なら冠月祭特別価格ってことで、安くしといてやるぜ…",
  ui_story_5040_50400401_89_dialog_content = "あの、僕は…その…",
  ui_story_5040_50400401_90_dialog_content = "分かってるよ。欲しいんだろ？",
  ui_story_5040_50400401_91_dialog_content = "そういうことだろーな。",
  ui_story_5040_50400401_92_dialog_content = "僕は…",
  ui_story_5040_50400401_93_dialog_content = "ストップストップ！",
  ui_story_5040_50400401_94_dialog_content = "初めて影ノ街に来た人をカモにしないでもらえる！？",
  ui_story_5040_50400401_95_dialog_content = "おいおい、PlayerName…\nこいつはまっとうな商売だぜ。ただの商談だろうが。",
  ui_story_5040_50400401_96_dialog_content = "どこが！？",
  ui_story_5040_50400401_97_dialog_content = "…反論してやりてーところだが、\nどうも騒がしいな。",
  ui_story_5040_50400401_98_dialog_content = "<size=45>きゃああ！！</size>",
  ui_story_5040_50400401_99_dialog_content = "どうしたの！？",
  ui_story_5040_50400401_100_dialog_content = "あ、暗鬼です！",
  ui_story_5040_50400401_101_dialog_content = "こんなところに暗鬼が！？",
  ui_story_5040_50400401_102_dialog_content = "<size=45>グアア――</size>",
  ui_story_5040_50400401_103_dialog_content = "…ったく…面倒くせえな。\n商売のジャマしやがって。",
  ui_story_5040_50400401_104_dialog_content = "あ、暗鬼ですか！？",
  ui_story_5040_50400401_105_dialog_content = "アドニス、隠れてて！\n暗鬼は僕たちが何とかするよ。",
  ui_story_5040_50400402_1_dialog_content = "まったく、あの2人は…\n面倒ごとになるとすぐどこかに行っちゃうんだから…",
  ui_story_5040_50400402_2_dialog_content = "アドニス、大丈夫？",
  ui_story_5040_50400402_3_dialog_content = "はい、だ、大丈夫です。",
  ui_story_5040_50400402_4_dialog_content = "申し訳ありません。何の力にもなれず…\n暗鬼を見た途端、腰が抜けてしまって…",
  ui_story_5040_50400402_5_dialog_content = "いいんだよ。誰もが暗鬼との戦いに\n慣れてるわけじゃないし。",
  ui_story_5040_50400402_6_dialog_content = "まあ、ハチとギンが逃げてくれて幸いだったね。\n一度絡まれたら面倒なんだ。",
  ui_story_5040_50400402_7_dialog_content = "あの2人は騙しやすそうな人を見つけるのがうまいんだ。\n今度会ったらハッキリ断らなきゃダメだよ。",
  ui_story_5040_50400402_8_dialog_content = "はぁ…僕はいつだってこうなんです。",
  ui_story_5040_50400402_9_dialog_content = "あら？冠月祭の切手を売っていた方ではありませんか？",
  ui_story_5040_50400402_10_dialog_content = "え？",
  ui_story_5040_50400402_11_dialog_content = "アドニスのこと？ターラも一緒に居て、\nそれからクーリエ隊のイェリアも、監督してたはずだけど…",
  ui_story_5040_50400402_12_dialog_content = "アドニスさんというお名前ですのね。",
  ui_story_5040_50400402_13_dialog_content = "この人は…？",
  ui_story_5040_50400402_14_dialog_content = "ごきげんよう。私、ティナと申します。白夜城法廷の裁判官ですわ。\n先ほどは名乗りもせず、大変失礼いたしました。",
  ui_story_5040_50400402_15_dialog_content = "こんにちは、僕はPlayerName。",
  ui_story_5040_50400402_16_dialog_content = "午前中、冠月祭の切手についてお尋ねしたのです。",
  ui_story_5040_50400402_17_dialog_content = "あの時のクーリエさんのおかげで、\n影ノ街で無事手に入れることができました。",
  ui_story_5040_50400402_18_dialog_content = "本当ですか？よかったですね。\nでも、それはイェリアさんのおかげです。僕は何もしていませんよ。",
  ui_story_5040_50400402_19_dialog_content = "とにかく、去年の切手が見つかってよかったです。\nお友だちも恋人も、きっと喜ぶでしょうね。",
  ui_story_5040_50400402_20_dialog_content = "ええ。その後すぐに切手を渡しに行きました。\n友人はとても喜んでいましたわ。",
  ui_story_5040_50400402_21_dialog_content = "大事そうに切手を持って、お礼を言うなり\n飛ぶように帰っていきました。恋人への手紙を書くそうですわ。",
  ui_story_5040_50400402_22_dialog_content = "紹介していただいた方が他にも貴重なコレクションをお持ちだったので、\n改めて拝見しに行こうとしていたところ、お2人をお見かけしたのです。",
  ui_story_5040_50400402_23_dialog_content = "それにしても…顔色が優れないご様子ですね。\n何かあったのですか？",
  ui_story_5040_50400402_24_dialog_content = "それは…実は…",
  ui_story_5040_50400402_25_dialog_content = "そういうことでしたか。\nどうりで午前中どこかぎこちない感じがしていたのですね。",
  ui_story_5040_50400402_26_dialog_content = "この後は啓光に行かれるのですね？\n友人の恋人に頼んで、解毒薬のことを聞いておきましょうか？",
  ui_story_5040_50400402_27_dialog_content = "えっ？",
  ui_story_5040_50400402_28_dialog_content = "実を言うと、友人の恋人の女性は\nカナン城のブラック・アンブレラという実験室で務めているのです。",
  ui_story_5040_50400402_29_dialog_content = "薬のことであれば、何か知っているかもしれません。\n私の名前を出せば会えるはずですわ。",
  ui_story_5040_50400402_30_dialog_content = "お役に立てるかは分かりませんが、\n少しでもお力になれれば幸いです。",
  ui_story_5040_50400402_31_dialog_content = "どうもありがとうございます！",
  ui_story_5040_50400402_32_dialog_content = "啓光に着いたら、すぐに訪ねてみます！",
  ui_story_5040_50400402_33_dialog_content = "よかったね、アドニス。\nこれで手がかりが増えたよ。",
  ui_story_5040_50400402_34_dialog_content = "薬が見つかるよう祈っておりますわ。",
  ui_story_5040_50400402_35_dialog_content = "ふわぁ～…何だか眠くなってきました。\n帰って寝た方がよさそうですわ。",
  ui_story_5040_50400402_36_dialog_content = "親切って返ってくるものだね。\nカナン城に着いたら、訪ねてみよう。",
  ui_story_5040_50400402_37_dialog_content = "ええ！ありがとうございます、PlayerNameさん。",
  ui_story_5040_50400402_38_dialog_content = "<color=#e8d9bb>その日の夜――</color>",
  ui_story_5040_50400402_39_dialog_content = "ふぅ、ここでも何も見つかりませんか？",
  ui_story_5040_50400402_40_dialog_content = "…今…がんばってる…",
  ui_story_5040_50400402_41_dialog_content = "せかしてるわけじゃありません。\nゆっくり考えていいんですよ。",
  ui_story_5040_50400402_42_dialog_content = "ただ、影ノ街もずいぶん見て回りましたし、\nそろそろ戻りましょう。",
  ui_story_5040_50400402_43_dialog_content = "夜は白夜城の方が安全ですから。",
  ui_story_5040_50400402_44_dialog_content = "影ノ街…白夜…城…",
  ui_story_5040_50400402_45_dialog_content = "白…夜…",
  ui_story_5040_50400402_46_dialog_content = "どうしたんですか？\n白夜城を見つめて、何を考えてるんです？",
  ui_story_5040_50400402_47_dialog_content = "何か思い出しましたか？",
  ui_story_5040_50400402_48_dialog_content = "白夜…城…すごく…遠い…",
  ui_story_5040_50400402_49_dialog_content = "誰かの…ために…来た…",
  ui_story_5040_50400402_50_dialog_content = "誰かと…約束した…白夜…城で…待ってる？",
  ui_story_5040_50400402_51_dialog_content = "でも…来なかった…",
  ui_story_5040_50400402_52_dialog_content = "昔、他の場所から白夜城に来たことがあるってことですか？",
  ui_story_5040_50400402_53_dialog_content = "うん…そんな…気がする…",
  ui_story_5040_50400402_54_dialog_content = "ということは、あなたは白夜城出身ではないということですね。\nじゃあ、どこから来たんですか？覚えてますか？",
  ui_story_5040_50400402_55_dialog_content = "すごく…遠い所…",
  ui_story_5040_50400402_56_dialog_content = "うーん…「すごく遠い」ですか。",
  ui_story_5040_50400402_57_dialog_content = "とにかく、今はそれで十分です。\n白夜城じゃないと分かったんですから、ほかを当たればいいんです。",
  ui_story_5040_50400402_58_dialog_content = "PlayerNameさんたちは明日カナン城へ向けて出発するようですよ。\n私たちも一緒に付いていきましょう。",
  ui_story_5040_50400402_59_dialog_content = "カナン城のクーリエ隊を訪ねれば、\nまた何か新しい発見があるかもしれません。",
  ui_story_5040_50400402_60_dialog_content = "うん…",
  ui_story_5040_50400402_61_dialog_content = "<color=#e8d9bb>次の日――</color>",
  ui_story_5040_50400402_62_dialog_content = "皆、準備はいい？忘れ物はないよね？",
  ui_story_5040_50400402_63_dialog_content = "ふふ、啓光なんて久しぶりだわ。\nあそこの小鳥ちゃんたちはどうしてるかしらぁ？",
  ui_story_5040_50400402_64_dialog_content = "迷惑はかけないようにお願いしますよ…",
  ui_story_5040_50400402_65_dialog_content = "前にターラから啓光の話を聞いていたので、\nずっと行ってみたかったんです。",
  ui_story_5040_50400402_66_dialog_content = "あたしは啓光の新型トラックに興味があるわね。",
  ui_story_5040_50400402_67_dialog_content = "じゃあ、出発だ！",
  ui_story_5040_50400502_1_dialog_content = "おお…ここがカナン城！",
  ui_story_5040_50400502_2_dialog_content = "あたしも1度しか来たことないわ。",
  ui_story_5040_50400502_3_dialog_content = "何というか…カナン城っていつ来ても変わらないなぁ。",
  ui_story_5040_50400502_4_dialog_content = "PlayerNameはよくここに来るの？",
  ui_story_5040_50400502_5_dialog_content = "よくってわけじゃないけど、仲のいい友だちが啓光出身だから、\n一緒に何度か来たことがあるよ。",
  ui_story_5040_50400502_6_dialog_content = "友だちは休暇中らしいから、\nたぶん会えないだろうけど。",
  ui_story_5040_50400502_7_dialog_content = "カナン城に冠月祭はないのですか？\nまったくそういった雰囲気がありませんが…",
  ui_story_5040_50400502_8_dialog_content = "もちろん、あるわよ。\nみんなお祝いしてるわ。",
  ui_story_5040_50400502_9_dialog_content = "でも、場所が違えば生活スタイルも変わるものよ。\n啓光連邦は白夜城みたいに体裁にこだわらないの。",
  ui_story_5040_50400502_10_dialog_content = "ここの人は…現実的で控えめな過ごし方をするって言うのかしら。\n女の人は手作りのシナモンロールを好きな人に贈るそうよ～。",
  ui_story_5040_50400502_11_dialog_content = "で、男の方は服の袖の内側にハートを描いて、\nそこに好きな人の名前を書くみたいね～。",
  ui_story_5040_50400502_12_dialog_content = "なんだか少し、可愛らしいね。",
  ui_story_5040_50400502_13_dialog_content = "本当ですね。とてもロマンチックです！\n僕もやります！",
  ui_story_5040_50400502_14_dialog_content = "ちょっと…！？",
  ui_story_5040_50400502_15_dialog_content = "そういえば、イェリアってずいぶん物知りだね。",
  ui_story_5040_50400502_16_dialog_content = "イェリア先輩は色々な所に行ったことがあると聞いていますが、\n先輩の口からその話を聞いたことはほとんどありませんね。",
  ui_story_5040_50400502_17_dialog_content = "昔のことなんて話してもつまらないじゃな～い。\nところで…あそこにいるのって見間違いじゃなければ…",
  ui_story_5040_50400502_18_dialog_content = "！？",
  ui_story_5040_50400502_19_dialog_content = "啓光の小鳥ちゃんよねぇ。",
  ui_story_5040_50400502_20_dialog_content = "ドーヴ？配達の時間じゃないの？",
  ui_story_5040_50400502_21_dialog_content = "ううっ、配達中だよ。冠月祭でも仕事だポッポ…",
  ui_story_5040_50400502_22_dialog_content = "自分のペースで仕事してるだけ。",
  ui_story_5040_50400502_23_dialog_content = "本当かなぁ…？",
  ui_story_5040_50400502_24_dialog_content = "啓光の先輩ですか？ウワサは聞いたことがありますね。\n良くないウワサばかりですけど…",
  ui_story_5040_50400502_25_dialog_content = "ひどい！？私だってちゃんと仕事してるよ。\nでも、こんな荷物が多くちゃ、誰だって苦労するって。",
  ui_story_5040_50400502_26_dialog_content = "そもそも配達しきれるわけないし…\nだんだん面倒くさくなってきただけだって。",
  ui_story_5040_50400502_27_dialog_content = "つまり、サボってるってことだね…",
  ui_story_5040_50400502_28_dialog_content = "でも、その話はひとまず置いておくよ。\nドーヴ、冠月祭の羽の印章って知ってる？",
  ui_story_5040_50400502_29_dialog_content = "羽の印章？私が持ってるよ。",
  ui_story_5040_50400502_30_dialog_content = "え！？",
  ui_story_5040_50400502_31_dialog_content = "先輩たちは配達であちこち飛び回ってるから、\n私が保管を頼まれてるの。",
  ui_story_5040_50400502_32_dialog_content = "それ、君がサボってるから、\n先輩たちが残業せざるを得なくなってるって事じゃ…",
  ui_story_5040_50400502_33_dialog_content = "印章に用があるの？",
  ui_story_5040_50400502_34_dialog_content = "僕たちは羽の印章を押してもらいに来たんです。\n啓光のクーリエ隊の印をもらうには、どうすればいいでしょうか？",
  ui_story_5040_50400502_35_dialog_content = "ああ…そういうこと。",
  ui_story_5040_50400502_36_dialog_content = "だったら簡単なことだね。\n私の代わりに残りの荷物を届けてくれればいいよ。",
  ui_story_5040_50400502_37_dialog_content = "…規則とか大丈夫なの？",
  ui_story_5040_50400502_38_dialog_content = "どうせ印章は私が持ってるんだし、\nどうやってもらえるかは私が決めたっていいでしょ。",
  ui_story_5040_50400502_39_dialog_content = "悪い気もするけど、\nもし手伝ってくれるなら、心から感謝するよ！",
  ui_story_5040_50400502_40_dialog_content = "分かりました！任せてください！",
  ui_story_5040_50400502_41_dialog_content = "<color=#e8d9bb>しばらくして――</color>",
  ui_story_5040_50400502_42_dialog_content = "…",
  ui_story_5040_50400502_43_dialog_content = "…",
  ui_story_5040_50400502_44_dialog_content = "…",
  ui_story_5040_50400502_45_dialog_content = "…確かに、ずいぶんあるわねぇ。",
  ui_story_5040_50400502_46_dialog_content = "これ…もう多いって言うレベルじゃないよ！\nなんでこんなになるまで放っておいたの！？",
  ui_story_5040_50400502_47_dialog_content = "あたしたち2人が飲まず食わずで3日間、\n休みなく配達しても終わりそうにないわ…",
  ui_story_5040_50400502_48_dialog_content = "ごめん…まさか、こんなに多いとは思ってなくて…",
  ui_story_5040_50400502_49_dialog_content = "はぁ、仕方ない…皆でやろう。",
  ui_story_5040_50400502_50_dialog_content = "私も手伝います。\nついでにセーブルを連れて色々見て回れますし。",
  ui_story_5040_50400502_51_dialog_content = "申し訳ありません。僕たち2人のことなのに、\n皆さんにまたご迷惑をおかけしてしまって。",
  ui_story_5040_50400502_52_dialog_content = "一番多いところはあたしたちがやるわ。\n体力勝負の仕事なら得意なの。",
  ui_story_5040_50400502_53_dialog_content = "アタシは本を読みながら応援してるわね～。",
  ui_story_5040_50400502_54_dialog_content = "…イェリア先輩…いや、その方がいいかもしれません。\n余計な面倒が増えずに済みますし…",
  ui_story_5040_50400502_55_dialog_content = "じゃあ、すぐに始めましょ！",
  ui_story_5040_50400502_56_dialog_content = "うわっ…！",
  ui_story_5040_50400502_57_dialog_content = "もうっ、遅いわね、アドニス！",
  ui_story_5040_50400502_58_dialog_content = "ご、ごめん。階段が急だったから…",
  ui_story_5040_50400502_59_dialog_content = "気を付けてよ！",
  ui_story_5040_50400502_60_dialog_content = "その荷物、仕分けして。\nこの辺りのはあなたに任せる、遠くのはあたしが届けるわ。",
  ui_story_5040_50400502_61_dialog_content = "ダメだ、それじゃ君の仕事が多すぎる。",
  ui_story_5040_50400502_62_dialog_content = "あちこち駆け回るのには慣れてるし、\nその方が効率よく配達できるわ。",
  ui_story_5040_50400502_63_dialog_content = "そうだね…分かったよ。",
  ui_story_5040_50400502_64_dialog_content = "び、ビビアンさん！お届け物です！",
  ui_story_5040_50400502_65_dialog_content = "あら、PlayerNameではありませんか。\n今日はバイスと一緒では…",
  ui_story_5040_50400502_66_dialog_content = "確かに届けました！\nそれでは失礼します！",
  ui_story_5040_50400502_67_dialog_content = "なぜあなたが配達しているのですか？",
  ui_story_5040_50400502_68_dialog_content = "…ドーヴ…業績評価は、覚悟しておくことですね。",
  ui_story_5040_50400502_69_dialog_content = "こんにちは、配達です！",
  ui_story_5040_50400502_70_dialog_content = "ふぅ、こっちはこれで終わりですね。",
  ui_story_5040_50400502_71_dialog_content = "キア…すごい…",
  ui_story_5040_50400502_72_dialog_content = "ふふ…本職ですから。",
  ui_story_5040_50400502_73_dialog_content = "途中で何か見覚えのあるものがあったら、\nすぐに教えてくださいね。",
  ui_story_5040_50400502_74_dialog_content = "<color=#e8d9bb>数時間後――</color>",
  ui_story_5040_50400502_75_dialog_content = "もう…ダメだ…",
  ui_story_5040_50400502_76_dialog_content = "はぁ…はぁ…PlayerNameさん、終わったんですか？",
  ui_story_5040_50400502_77_dialog_content = "うん…なんとか…",
  ui_story_5040_50400502_78_dialog_content = "確かにずいぶん駆け回ったけど、\n2人は体力なさすぎよ。",
  ui_story_5040_50400502_79_dialog_content = "お疲れ様～。無事終わったみたいねぇ。",
  ui_story_5040_50400502_80_dialog_content = "キアはまだ？",
  ui_story_5040_50400502_81_dialog_content = "あの子の心配はいらないわ～。\nとっくに終わってるはずよ。北境の小鳥ちゃんだもの。",
  ui_story_5040_50400502_82_dialog_content = "たぶん今ごろ、\nあのお友達と一緒に街をぶらついてるんじゃない？",
  ui_story_5040_50400502_83_dialog_content = "へへへ…さすがPlayerNameだね。",
  ui_story_5040_50400502_84_dialog_content = "ドーヴ！？もしかして、ずっと近くでブラブラしてたの？",
  ui_story_5040_50400502_85_dialog_content = "ブラブラなんてしてないよ。\n仕事してたの。",
  ui_story_5040_50400502_86_dialog_content = "試練は無事に達成しました。\n印章を押してもらえますか？",
  ui_story_5040_50400502_87_dialog_content = "もちろん！\nさあ、押したての印章だよ！",
  ui_story_5040_50400502_88_dialog_content = "ポンっと！",
  ui_story_5040_50400502_89_dialog_content = "やった、これで啓光の印章も集まったね！",
  ui_story_5040_50400502_90_dialog_content = "…そうね。意味があるのかは分からないけど。",
  ui_story_5040_50400502_91_dialog_content = "意味はあるよ。\nだってほら、僕たちも少しずつ打ち解けてきたじゃないか？",
  ui_story_5040_50400502_92_dialog_content = "だ、誰が打ち解けたって！？",
  ui_story_5040_50400502_93_dialog_content = "ところで、印章はもらったし、次はどこへ行く？",
  ui_story_5040_50400502_94_dialog_content = "せっかくカナン城へ来たことですし、\n一緒においしいものでも食べて、そのあと映画を見ませんか？",
  ui_story_5040_50400502_95_dialog_content = "なんといっても、冠月祭の時期ですから！",
  ui_story_5040_50400502_96_dialog_content = "啓光の食べ物なんていつでも食べられるわよ。",
  ui_story_5040_50400502_97_dialog_content = "手紙を配達してる時、別のシェルターから最新式の自動小銃が\n届いてるって聞いたわ。整備工場を見学してみたいわね。",
  ui_story_5040_50400502_98_dialog_content = "武器の整備場？\n冠月祭に行くにはふさわしくないんじゃ…",
  ui_story_5040_50400502_99_dialog_content = "行きたくないなら、別行動にしましょ。",
  ui_story_5040_50400502_100_dialog_content = "僕はそういうつもりじゃ…",
  ui_story_5040_50400502_101_dialog_content = "2人とも、落ち着きなさいな。\nその前に、もっと重要なことがあるでしょ？",
  ui_story_5040_50400502_102_dialog_content = "ここに来た目的、忘れてないかしらぁ？",
  ui_story_5040_50400502_103_dialog_content = "そうだよ。記憶喪失を治す手がかりを探しに、\nブラック・アンブレラに行くって言ってたでしょ？",
  ui_story_5040_50400502_104_dialog_content = "あ…そうでした。",
  ui_story_5040_50400502_105_dialog_content = "…",
  ui_story_5040_50400502_106_dialog_content = "こういうことは早い方がいいわ。\n遅くならないうちに、やるべきことをやっちゃいましょ。",
  ui_story_5040_50400601_1_dialog_content = "（ここは本当に久しぶりだ）",
  ui_story_5040_50400601_2_dialog_content = "…という訳なんです。どうぞよろしくお願いします。",
  ui_story_5040_50400601_3_dialog_content = "話はうかがっております。\nティナさんにも、皆さんにも、心から感謝します！",
  ui_story_5040_50400601_4_dialog_content = "啓光と白夜城はそもそも微妙な関係なので…\n私たちの間にも色々とあるんです。",
  ui_story_5040_50400601_5_dialog_content = "でも、応援してくれる人もいるんですよ。\nティナさんもその一人です。",
  ui_story_5040_50400601_6_dialog_content = "彼女も貴族の身分なのですが、\nずっと私たちを応援してくれています。",
  ui_story_5040_50400601_7_dialog_content = "体調を保つために長時間の睡眠が必要な方なのですが、\n起きている貴重な時間で切手を探してくれたり…",
  ui_story_5040_50400601_8_dialog_content = "確かに、ティナさんは少し不思議なところのある方ですね。",
  ui_story_5040_50400601_9_dialog_content = "いつも礼儀正しくて、とてもやさしい方です。",
  ui_story_5040_50400601_10_dialog_content = "ですが、何か悩みもあるようですね。\n法廷のお仕事も「おかしな」ものばかりと聞いていますし…",
  ui_story_5040_50400601_11_dialog_content = "次はいつ会えるのか分かりませんが、\n私もティナさんのことはもっと知りたいと思っているんです。",
  ui_story_5040_50400601_12_dialog_content = "ただ、お話をうかがった限り、\nお二人も色々と大変なようですね。",
  ui_story_5040_50400601_13_dialog_content = "そうよ。どうして駆け落ちしちゃわないの？",
  ui_story_5040_50400601_14_dialog_content = "お互いにやらなければいけないことがありますから。\nまずは自分の責務が第一、恋人はその次です。",
  ui_story_5040_50400601_15_dialog_content = "私も彼も責任感が強いんです。\nだからこそお互いに惹かれ合ったんですよ。",
  ui_story_5040_50400601_16_dialog_content = "心さえつながっていれば、\n物理的な距離も周りの反対も問題ではありません。",
  ui_story_5040_50400601_17_dialog_content = "心が…つながってる？",
  ui_story_5040_50400601_18_dialog_content = "僕もそう思います。お互いの心が愛情で結ばれているなら、\nそれ以外のことは何の問題でもありません。",
  ui_story_5040_50400601_19_dialog_content = "ふふ、そうですね。では本題に入りましょうか。\nこちらがターラさんですね。状況は大体分かりました。",
  ui_story_5040_50400601_20_dialog_content = "ただ、少々お待ちいただけますか？私は実習生なので、\n具体的なことは同僚に聞いてみなければ分からないんです。",
  ui_story_5040_50400601_21_dialog_content = "よろしくお願いします！",
  ui_story_5040_50400601_22_dialog_content = "<size=33>イェリア、バレちゃうんじゃない？</size>",
  ui_story_5040_50400601_23_dialog_content = "続けられそうにないなら、\n認めちゃえばいいんじゃな～い？",
  ui_story_5040_50400601_24_dialog_content = "<size=33>そんなのダメよ！\nどんな顔して顔を合わせればいいの？</size>",
  ui_story_5040_50400601_25_dialog_content = "自分で思いついたことでしょ？\n今さら恥ずかしがったって仕方ないじゃない？",
  ui_story_5040_50400601_26_dialog_content = "<size=33>絶対にダメ！\nとにかく、何かあったらフォローしてよ！</size>",
  ui_story_5040_50400601_27_dialog_content = "…",
  ui_story_5040_50400601_28_dialog_content = "（記憶喪失、やっぱりウソだったのか…\nでも、僕はこのまま知らないフリをしておこう）",
  ui_story_5040_50400601_29_dialog_content = "イェリア、どうしたの？",
  ui_story_5040_50400601_30_dialog_content = "何でもないわ！\nこの研究室、スゴイわねって話してただけ！",
  ui_story_5040_50400601_31_dialog_content = "それはそうだね。所長のミジャードは\n測り知れない実力の持ち主なんだ。",
  ui_story_5040_50400601_32_dialog_content = "ターラ、どうして震えてるんだい？",
  ui_story_5040_50400601_33_dialog_content = "ちょっと冷えただけでしょ。",
  ui_story_5040_50400601_34_dialog_content = "え？そんなに寒いかな…？",
  ui_story_5040_50400601_35_dialog_content = "皆さん、こちらへどうぞ。\n実験室の先輩をご紹介します。",
  ui_story_5040_50400601_36_dialog_content = "ありがとう。",
  ui_story_5040_50400601_37_dialog_content = "ジョラ先輩、こちらがお話ししたターラさんです。\n記憶を失ってしまったらしいのですが…",
  ui_story_5040_50400601_38_dialog_content = "どうぞよろしくお願いします。",
  ui_story_5040_50400601_39_dialog_content = "これはこれは。同僚を助けてくださったそうですね。\nお返しするのは当然のことです。遠慮はいりません。",
  ui_story_5040_50400601_40_dialog_content = "ターラさん、近くで拝見してもよろしいですか？",
  ui_story_5040_50400601_41_dialog_content = "は、はい。",
  ui_story_5040_50400601_42_dialog_content = "今日は残念ですが、ミジャード室長が不在でして。\n記憶喪失は僕の専門ではありませんが、少しは心得が有ります。",
  ui_story_5040_50400601_43_dialog_content = "（ふぅ…その方がいいわ）",
  ui_story_5040_50400601_44_dialog_content = "うーん…見たところ特に問題はなさそうですが…\n念のため、基本的な身体能力検査をするとしましょう。",
  ui_story_5040_50400601_45_dialog_content = "身体能力検査とは、いったい何をするんでしょう？",
  ui_story_5040_50400601_46_dialog_content = "（ジョラの笑顔がなんだか怖い…）",
  ui_story_5040_50400601_47_dialog_content = "緊張することはありませんよ。\nほんの少し刺激を与えて、筋肉を動かすだけですから。",
  ui_story_5040_50400601_48_dialog_content = "グアアッ！",
  ui_story_5040_50400601_49_dialog_content = "え、そういうこと！？",
  ui_story_5040_50400602_1_dialog_content = "暗鬼を出すなら先に言ってよ！",
  ui_story_5040_50400602_2_dialog_content = "ちょっと！こんな検査方法なら、\n事前に説明するべきでしょ！",
  ui_story_5040_50400602_3_dialog_content = "おや、それは申し訳ありませんでした。\nですが、皆さんにとってはこの程度、大した運動にもならないでしょう？",
  ui_story_5040_50400602_4_dialog_content = "何しろ、実に興味深い組み合わせですから。\n…北境の方、砂漠出身の方、亜人族のクーリエ…空の末裔まで勢ぞろいです。",
  ui_story_5040_50400602_5_dialog_content = "今はそのことは重要じゃないよ。\n僕たちはターラの病気を治しに来たんだ。",
  ui_story_5040_50400602_6_dialog_content = "あたし、どこか悪いんでしょうか？",
  ui_story_5040_50400602_7_dialog_content = "今のところ、身体に異常はなさそうですね。",
  ui_story_5040_50400602_8_dialog_content = "検査もやったし、次はどうすればいいの？",
  ui_story_5040_50400602_9_dialog_content = "そうですね…記憶喪失のきっかけについて、\n他に情報はありませんか？",
  ui_story_5040_50400602_10_dialog_content = "そうですね…魔法の万能薬を作った霊媒師の話では、\n薬はとても貴重な原料から作られているそうです。",
  ui_story_5040_50400602_11_dialog_content = "確かR・W砂漠のピンクのサンドワームとかなんとか…\nなかなか出会えない希少な種だそうです。",
  ui_story_5040_50400602_12_dialog_content = "ピンクの…サンドワームですか？",
  ui_story_5040_50400602_13_dialog_content = "はい。",
  ui_story_5040_50400602_14_dialog_content = "ジョラ、知ってるの？",
  ui_story_5040_50400602_15_dialog_content = "…",
  ui_story_5040_50400602_16_dialog_content = "あのサンドワームがまた出てきたというのでしょうか…？",
  ui_story_5040_50400602_17_dialog_content = "<size=33>あり得ないわ…</size>",
  ui_story_5040_50400602_18_dialog_content = "<size=33>ターラ？</size>",
  ui_story_5040_50400602_19_dialog_content = "<size=33>ピンクのサンドワームのウロコ、あたしが持ってるのよ。\nどこかの霊媒師なんかが持ってるはずないわ！</size>",
  ui_story_5040_50400602_20_dialog_content = "<size=33>実際にそんなものがいるなら、\nウロコが1枚だけってことはないんじゃない？</size>",
  ui_story_5040_50400602_21_dialog_content = "<size=33>いいえ、ピンクのサンドワームのウロコは\n世間に1枚しか出回ってないはずよ。それがなんで、急にもう1枚…？</size>",
  ui_story_5040_50400602_22_dialog_content = "僕は植物が専門ですが、以前ある胞子を探している時に、\nミジャードさんから聞いたことがあります。",
  ui_story_5040_50400602_23_dialog_content = "その胞子はほどんど研究者がおらず、本に記載があるだけなのですが、\nピンクのサンドワームのウロコに寄生すると言われていました。",
  ui_story_5040_50400602_24_dialog_content = "室長がそういうサンドワームがいると言っていましたし、\nR・W砂漠で目撃した人もいるそうですが、実際希少なようですね。",
  ui_story_5040_50400602_25_dialog_content = "普通のサンドワームよりさらに凶暴で、近づける者もいないので、\n当然ウロコは貴重品、今まで市場に出たのは1枚だけとか…",
  ui_story_5040_50400602_26_dialog_content = "そのウロコを手に入れられるのであれば、\n解毒薬を研究して差し上げることもできますが…",
  ui_story_5040_50400602_27_dialog_content = "申し訳ないですが、\nそれ以外の方法は僕も今は思いつきません。",
  ui_story_5040_50400602_28_dialog_content = "…",
  ui_story_5040_50400602_29_dialog_content = "…",
  ui_story_5040_50400602_30_dialog_content = "ふ～ん、これで目標がハッキリしてきたわねぇ。",
  ui_story_5040_50400602_31_dialog_content = "イェリア？",
  ui_story_5040_50400602_32_dialog_content = "この後どうせ砂漠に行くんでしょ？\nだったらR・W支部は、ピンクのサンドワームのウロコ探しを「試練」にするわ。",
  ui_story_5040_50400602_33_dialog_content = "ちょっと、本気で言ってるの？",
  ui_story_5040_50400602_34_dialog_content = "そんなサンドワーム、誰も見たことないのよ。\n砂漠暮らしの長いあたしだって。",
  ui_story_5040_50400602_35_dialog_content = "アタシも聞いたことないわねぇ。",
  ui_story_5040_50400602_36_dialog_content = "じゃあ、どうしてそんなものを試練にするのよ？",
  ui_story_5040_50400602_37_dialog_content = "ターラの記憶喪失を治す方法がそれしかないと言うなら、\n僕は喜んで挑戦します。",
  ui_story_5040_50400602_38_dialog_content = "えっ？",
  ui_story_5040_50400602_39_dialog_content = "アドニス、何言ってるの？\n頭がおかしくなっちゃったの？",
  ui_story_5040_50400602_40_dialog_content = "無茶なのは分かってるよ…僕は何の能力もない。\n臆病で、家に出る虫だって怖い…伝説のサンドワームなんてとても無理だ。",
  ui_story_5040_50400602_41_dialog_content = "でも、僕のせいでターラがこんなことになってしまったんだ。\nこのまま放っておくわけにはいかないよ。",
  ui_story_5040_50400602_42_dialog_content = "それに、僕が弱虫だからターラが怒ってるのは分かってた。\nだから、自分を変えたいんだ。",
  ui_story_5040_50400602_43_dialog_content = "今回ばかりは、逃げるわけにはいかない。",
  ui_story_5040_50400602_44_dialog_content = "今の言葉、感動したよ！",
  ui_story_5040_50400602_45_dialog_content = "あの、アドニス！実はあたし…",
  ui_story_5040_50400602_46_dialog_content = "うーん、感動的ねぇ。\nサンドワームと戦うつもりってことかしら？",
  ui_story_5040_50400602_47_dialog_content = "もちろん、今のままじゃ無理なことは分かってます！\nですから、僕を鍛えてください！僕は変わらなきゃいけないんです！",
  ui_story_5040_50400602_48_dialog_content = "暗鬼と戦うことからでも構いません。\n強くなりたいんです！",
  ui_story_5040_50400602_49_dialog_content = "ほんとに戦えるの？",
  ui_story_5040_50400602_50_dialog_content = "確かお父さんが言ってたわねぇ。\nあなた、ノーヴィオに光力術を習ったことがあるんでしょ？",
  ui_story_5040_50400602_51_dialog_content = "はい。子どもの頃は図書館に通っていたんですが、\nノーヴィオ先生がよく指導してくださいました。",
  ui_story_5040_50400602_52_dialog_content = "強い光力術は使えませんが、基礎はできています。",
  ui_story_5040_50400602_53_dialog_content = "ふ～ん…",
  ui_story_5040_50400602_54_dialog_content = "…イェリア、何か物騒な事考えてない？",
  ui_story_5040_50400602_55_dialog_content = "心配しないで。\n同じ船に乗り合わせてるようなものだし、悪いようにはしないわ～。",
  ui_story_5040_50400602_56_dialog_content = "とにかく、あなたがその気なら話は早いわ。\n暗鬼と戦ってもらうことにしましょ…",
  ui_story_5040_50400602_57_dialog_content = "い、今からですか？",
  ui_story_5040_50400602_58_dialog_content = "でも、いきなり一人で暗鬼と戦わせるなんて酷よねぇ。\nふふ…アタシ、いい方法を思いついたわ。",
  ui_story_5040_50400602_59_dialog_content = "彼女に相手になってもらいましょ。",
  ui_story_5040_50400701_1_dialog_content = "イェリア先輩、\nわざわざ呼び出しだなんて、何の用ですか？",
  ui_story_5040_50400701_2_dialog_content = "イェリア、「彼女」ってまさか…",
  ui_story_5040_50400701_3_dialog_content = "グア…？",
  ui_story_5040_50400701_4_dialog_content = "あら、ダメかしらぁ？キアの親戚ちゃん、\n雰囲気も行動も暗鬼っぽさがあるじゃない。",
  ui_story_5040_50400701_5_dialog_content = "アドニスの練習相手になってもらうのに、\nちょうどいいと思わな～い？",
  ui_story_5040_50400701_6_dialog_content = "…うーん、確かにセーブルは光霊らしくないところもあるけど、\n暗鬼扱いはさすがに気の毒じゃないかな？",
  ui_story_5040_50400701_7_dialog_content = "（…とは言ったけど、\nセーブルは本当に暗鬼と何か関係があるんだろう）",
  ui_story_5040_50400701_8_dialog_content = "（でも、キアが連れて来たんだし、\n今のところおかしな行動もない…ここはまだ静観だ）",
  ui_story_5040_50400701_9_dialog_content = "たた…かい…？",
  ui_story_5040_50400701_10_dialog_content = "セーブルは戦えませんよ。\nもしケガでもしたらどうするんですか！？",
  ui_story_5040_50400701_11_dialog_content = "まぁまぁ、気楽にやりましょ。本気でやるワケじゃないし。\nアドニスに度胸をつけさせるだけよぉ。",
  ui_story_5040_50400701_12_dialog_content = "アドニスはどう？",
  ui_story_5040_50400701_13_dialog_content = "う…失礼かとは思いますが…\nセーブルさんに力を貸していただければ、とても助かります。",
  ui_story_5040_50400701_14_dialog_content = "僕の今の力で本物の暗鬼と戦えば、\nおそらく無事ではいられないと思うので…",
  ui_story_5040_50400701_15_dialog_content = "それに、普段は光力術をほとんど使わないので慣れてないんです。\n外ではいつもターラに守ってもらっていましたから。",
  ui_story_5040_50400701_16_dialog_content = "得意なことは人それぞれよ。\nムリすることはないわ。",
  ui_story_5040_50400701_17_dialog_content = "あなたを守ることぐらい、別に負担じゃないし…",
  ui_story_5040_50400701_18_dialog_content = "ターラ？",
  ui_story_5040_50400701_19_dialog_content = "今のままじゃダメなんだ。\n何としても、僕は今の自分を変えないと。",
  ui_story_5040_50400701_20_dialog_content = "お願いします、キアさん、セーブルさん！\nどうか力を貸してください！",
  ui_story_5040_50400701_21_dialog_content = "うーん…セーブル、どうしますか？",
  ui_story_5040_50400701_22_dialog_content = "や、役にたてる…なら…",
  ui_story_5040_50400701_23_dialog_content = "て…手伝う…！",
  ui_story_5040_50400701_24_dialog_content = "無理しなくていいんですよ。\nただの演習ですから。",
  ui_story_5040_50400701_25_dialog_content = "む、ムリ…してない…",
  ui_story_5040_50400701_26_dialog_content = "力に…なれる…うれしい…",
  ui_story_5040_50400701_27_dialog_content = "ありがとうございます！セーブルさん！",
  ui_story_5040_50400701_28_dialog_content = "グア――グア――",
  ui_story_5040_50400701_29_dialog_content = "幻聴かな？本物の暗鬼の声がした気がするけど？",
  ui_story_5040_50400701_30_dialog_content = "うわっ！？",
  ui_story_5040_50400701_31_dialog_content = "<size=45>グガアア――！</size>",
  ui_story_5040_50400701_32_dialog_content = "危ない！暗鬼よ！",
  ui_story_5040_50400701_33_dialog_content = "ど、どうしてです？いったいどこから！？",
  ui_story_5040_50400701_34_dialog_content = "不思議ねぇ。\nなんだかあなたと親戚のコに興味があるみたいだわ？",
  ui_story_5040_50400701_35_dialog_content = "単なる偶然かしら？",
  ui_story_5040_50400701_36_dialog_content = "…",
  ui_story_5040_50400701_37_dialog_content = "（セーブルが目当てなのでしょうか…？）",
  ui_story_5040_50400701_38_dialog_content = "暗…鬼…？",
  ui_story_5040_50400701_39_dialog_content = "他のことに気をとられちゃダメよ。\nまずはお邪魔虫たちを片付けることに集中しましょ。",
  ui_story_5040_50400701_40_dialog_content = "アドニス、気を付けて！\nあたしの後ろに隠れてて！",
  ui_story_5040_50400701_41_dialog_content = "わ、分かったよ。",
  ui_story_5040_50400702_1_dialog_content = "何とか全部倒したね。皆、大丈夫？",
  ui_story_5040_50400702_2_dialog_content = "何もないわ。\n暗鬼の1匹や2匹大したことじゃないもの。",
  ui_story_5040_50400702_3_dialog_content = "わ、私も無事です。",
  ui_story_5040_50400702_4_dialog_content = "あなたたちは慣れてるでしょうけど、\nあっちの2人はそうでもないみたいねぇ。",
  ui_story_5040_50400702_5_dialog_content = "ううっ！",
  ui_story_5040_50400702_6_dialog_content = "こ…こわい…",
  ui_story_5040_50400702_7_dialog_content = "（…こんな臆病な2人を戦わせても、\n度胸なんてつくかな…？）",
  ui_story_5040_50400702_8_dialog_content = "一息ついてからにする？\nそれとも、すぐに始める？",
  ui_story_5040_50400702_9_dialog_content = "きゅ、休憩は要りません。",
  ui_story_5040_50400702_10_dialog_content = "い…いらない…！",
  ui_story_5040_50400702_11_dialog_content = "セーブル、無理しちゃダメですよ！",
  ui_story_5040_50400702_12_dialog_content = "2人とも威勢がいいじゃな～い？\nそれじゃあ、始めましょ。",
  ui_story_5040_50400702_13_dialog_content = "<color=#e8d9bb>しばらくして――</color>",
  ui_story_5040_50400702_14_dialog_content = "…",
  ui_story_5040_50400702_15_dialog_content = "…",
  ui_story_5040_50400702_16_dialog_content = "…あの…いつ始めるの？\nもう15分にらみあったままだけど…",
  ui_story_5040_50400702_17_dialog_content = "い、行きますよ！",
  ui_story_5040_50400702_18_dialog_content = "…！！",
  ui_story_5040_50400702_19_dialog_content = "戦おうって気迫が感じられないわね。",
  ui_story_5040_50400702_20_dialog_content = "今度こそ本当に行きますよ！",
  ui_story_5040_50400702_21_dialog_content = "わ…わかった…",
  ui_story_5040_50400702_22_dialog_content = "<color=#e8d9bb>1時間後――</color>",
  ui_story_5040_50400702_23_dialog_content = "今度こそ、絶対に絶対に行きますよ！",
  ui_story_5040_50400702_24_dialog_content = "か、覚悟してください！",
  ui_story_5040_50400702_25_dialog_content = "（なんだか眠くなってきちゃった…\nこの調子じゃひと眠りしてもまだやってそうだ…）",
  ui_story_5040_50400702_26_dialog_content = "…ねぇ、アドニス。ほんとにムリする必要なんてないのよ。",
  ui_story_5040_50400702_27_dialog_content = "セーブル、頑張ってください！",
  ui_story_5040_50400702_28_dialog_content = "…",
  ui_story_5040_50400702_29_dialog_content = "ねぇ、本当に暗鬼が目の前にいて戦う時も、\n1時間棒立ちしてから始めるつもり？",
  ui_story_5040_50400702_30_dialog_content = "大事な人を守るために戦うんでしょ？",
  ui_story_5040_50400702_31_dialog_content = "もしターラが戦えなくなったとして、\n暗鬼が出てきたら、迷ってられるのかしら？",
  ui_story_5040_50400702_32_dialog_content = "どうなるかなんて、説明する必要はないわよねぇ。",
  ui_story_5040_50400702_33_dialog_content = "ぼ…僕は…",
  ui_story_5040_50400702_34_dialog_content = "それとも、ターラがケガをしても構わないってことぉ？\nやっぱり、臆病な性格は克服できないのかしらねぇ？",
  ui_story_5040_50400702_35_dialog_content = "そ、そんなわけはありません！",
  ui_story_5040_50400702_36_dialog_content = "怖気づいて一歩も踏み出せず、大事な人を危険にさらすなんて。\n誰がそんな人と一緒にいたいと思う？",
  ui_story_5040_50400702_37_dialog_content = "<size=33>ちょっと、さすがに言いすぎよ！？</size>",
  ui_story_5040_50400702_38_dialog_content = "<size=33>何だかかわいそうになってきました…\nセーブル、頑張って助けてあげましょう。</size>",
  ui_story_5040_50400702_39_dialog_content = "<size=45>グガ！グガアア――！</size>",
  ui_story_5040_50400702_40_dialog_content = "<size=55>うわあああ！！</size>",
  ui_story_5040_50400702_41_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_5040_50400702_42_dialog_content = "はぁ…はぁ…",
  ui_story_5040_50400702_43_dialog_content = "ううっ…",
  ui_story_5040_50400702_44_dialog_content = "せ、セーブル！大丈夫ですか！？",
  ui_story_5040_50400702_45_dialog_content = "だい…じょう…ぶ…",
  ui_story_5040_50400702_46_dialog_content = "アドニスが動いた！？",
  ui_story_5040_50400702_47_dialog_content = "進歩できたね、アドニス！\nもう物陰に隠れてた時の君じゃない！",
  ui_story_5040_50400702_48_dialog_content = "まぁ、攻撃とも言えない弱腰だけど、\n空の末裔くんの言う通り、大きな進歩ね。",
  ui_story_5040_50400702_49_dialog_content = "実戦じゃ、まだ通用しないわよ。",
  ui_story_5040_50400702_50_dialog_content = "進歩があったことに意味があるのよ！\n自分を超えるなんて、簡単にできることじゃないわ！",
  ui_story_5040_50400702_51_dialog_content = "ありがとう、ターラ！",
  ui_story_5040_50400702_52_dialog_content = "ぐすっ…皆さん、ありがとうございます！\nセーブルさんもありがとう！",
  ui_story_5040_50400702_53_dialog_content = "どういたし…まして…",
  ui_story_5040_50400702_54_dialog_content = "いい感じじゃない。\nこの調子で練習を続けましょ。",
  ui_story_5040_50400702_55_dialog_content = "イェリア、今日はもう止めておこうよ。\nもう日が暮れるし、みんな疲れただろうから。",
  ui_story_5040_50400702_56_dialog_content = "練習だって段階ってものがあるでしょ。\n今日はカナン城に戻ろう。",
  ui_story_5040_50400702_57_dialog_content = "うーん、そうねぇ。\n空の末裔くんが言うなら仕方ないわ。",
  ui_story_5040_50400702_58_dialog_content = "うう…",
  ui_story_5040_50400702_59_dialog_content = "どうしました？\nどこか具合が悪いんですか？",
  ui_story_5040_50400702_60_dialog_content = "な、何でも…ない…",
  ui_story_5040_50400702_61_dialog_content = "思い出した…気がする…",
  ui_story_5040_50400702_62_dialog_content = "えっ？",
  ui_story_5040_50400702_63_dialog_content = "砂漠…砂漠のこと…",
  ui_story_5040_50400702_64_dialog_content = "砂漠？R・W砂漠ですか？",
  ui_story_5040_50400702_65_dialog_content = "わから…ない…でも…",
  ui_story_5040_50400702_66_dialog_content = "砂漠…思い出した…",
  ui_story_5040_50400702_67_dialog_content = "さっきのアドニスの攻撃で記憶が刺激されたんでしょうか？",
  ui_story_5040_50400702_68_dialog_content = "もしR・W砂漠なら、ちょうどいいですね。\n次の目的地はR・W砂漠ですから！",
  ui_story_5040_50400702_69_dialog_content = "…",
  ui_story_5040_50400702_70_dialog_content = "皆、今日は疲れたでしょ？ここで解散して休もう。",
  ui_story_5040_50400702_71_dialog_content = "皆さんに付き合わせてしまって…\n本当にありがとうございます。",
  ui_story_5040_50400702_72_dialog_content = "あたしたち2人の問題なのに、\nあちこち連れまわしてごめんなさい。",
  ui_story_5040_50400702_73_dialog_content = "ターラ、皆さんに啓光の特産品でも買ってきて、\nおやつにでも食べてもらおうよ。今はそれぐらいしかお返しのしようもない…",
  ui_story_5040_50400702_74_dialog_content = "アハハ、そんなに気を使わないで。",
  ui_story_5040_50400702_75_dialog_content = "（啓光の特産品…おやつなんてあったかな？）",
  ui_story_5040_50400702_76_dialog_content = "そうね！じゃあ、暗くならないうちに行きましょ！",
  ui_story_5040_50400702_77_dialog_content = "私…行きたい…",
  ui_story_5040_50400702_78_dialog_content = "キア、2人だけで話したいことがあるんだけど、\nちょっといいかしらぁ？",
  ui_story_5040_50400702_79_dialog_content = "え？急にどうしたんですか…？\nもちろん、構いませんけど…",
  ui_story_5040_50400702_80_dialog_content = "セーブルは…",
  ui_story_5040_50400702_81_dialog_content = "空の末裔くんがいるじゃない。\n一緒に帰ってもらえばいいわ。",
  ui_story_5040_50400702_82_dialog_content = "それとも、あの子を一人にしておけない理由でもあるのかしら～？",
  ui_story_5040_50400702_83_dialog_content = "そ、そんなものありませんよ！",
  ui_story_5040_50400702_84_dialog_content = "では、PlayerNameさん、お願いします。\nセーブルを連れて先に戻ってください。",
  ui_story_5040_50400702_85_dialog_content = "うん、分かったよ。",
  ui_story_5040_50400702_86_dialog_content = "あの…",
  ui_story_5040_50400702_87_dialog_content = "どうかしたの？",
  ui_story_5040_50400702_88_dialog_content = "遠回り…したい…",
  ui_story_5040_50400702_89_dialog_content = "遠回り？",
  ui_story_5040_50400702_90_dialog_content = "他に行きたいところがあるってこと？",
  ui_story_5040_50400702_91_dialog_content = "私、前に…手紙…ひろった…",
  ui_story_5040_50400702_92_dialog_content = "持ち主に…返したい。",
  ui_story_5040_50400702_93_dialog_content = "手紙？どこで拾ったの？\nクーリエ隊に持って行った方がいいんじゃない？",
  ui_story_5040_50400702_94_dialog_content = "アドニスと…練習…した後、拾った。",
  ui_story_5040_50400702_95_dialog_content = "ということは、外で拾ったんだね？\nクーリエがうっかり落としちゃったのかな。",
  ui_story_5040_50400702_96_dialog_content = "クーリエ隊には届けずに直接持っていくつもり？",
  ui_story_5040_50400702_97_dialog_content = "住所…書いてある。",
  ui_story_5040_50400702_98_dialog_content = "じゃないと…たくさん…待つ。",
  ui_story_5040_50400702_99_dialog_content = "それもそうだね。\n冠月祭のシーズンだから、相手も待ってるだろうし。",
  ui_story_5040_50400702_100_dialog_content = "…ドーヴに君の半分でも責任感があったらなぁ…",
  ui_story_5040_50400702_101_dialog_content = "じゃあ、行こうか。僕も一緒に行くよ。\n住所を見せて、どこ？",
  ui_story_5040_50400702_102_dialog_content = "（…この手紙、なんか黄ばんでる。\n最近出したものじゃないみたいだ…）",
  ui_story_5040_50400702_103_dialog_content = "<color=#e8d9bb>トントントン――</color>",
  ui_story_5040_50400702_104_dialog_content = "たぶん…ここ。",
  ui_story_5040_50400702_105_dialog_content = "うん、ここで間違いなさそうだ。",
  ui_story_5040_50400702_106_dialog_content = "どちら様ですか？",
  ui_story_5040_50400702_107_dialog_content = "すみません、道で手紙を拾ったんだけど、\n宛て先がここだったから届けに来たんです。",
  ui_story_5040_50400702_108_dialog_content = "手紙？うちにですか？\n見せていただけますか？",
  ui_story_5040_50400702_109_dialog_content = "こ、これは…！？",
  ui_story_5040_50400702_110_dialog_content = "ここで間違いありませんよね？",
  ui_story_5040_50400702_111_dialog_content = "どこでこの手紙を拾ったんですか！？",
  ui_story_5040_50400702_112_dialog_content = "こっちの友だちがカナン城の外で拾いました。",
  ui_story_5040_50400702_113_dialog_content = "た、助けに…なった？",
  ui_story_5040_50400702_114_dialog_content = "な、なんと言えばよいのか…",
  ui_story_5040_50400702_115_dialog_content = "これは私の祖母宛ての手紙です。",
  ui_story_5040_50400702_116_dialog_content = "おばあさんの？",
  ui_story_5040_50400702_117_dialog_content = "はい。亡くなるまでずっと手紙が届かないかと気に掛けていました。\nですが、結局受け取ることはかないませんでした…",
  ui_story_5040_50400702_118_dialog_content = "もともと祖母の初恋の人だったらしいのです。\n相手は白夜城の人で…結局2人が結ばれることはありませんでした。",
  ui_story_5040_50400702_119_dialog_content = "ですが、祖父が早くに亡くなって、\n祖母は初恋の人と何年も後にまた連絡を取るようになったのです。",
  ui_story_5040_50400702_120_dialog_content = "ずっと良き友人として、手紙のやり取りを続けていました。\nそして、命ある限り互いに手紙を出し続けると約束していたそうです。",
  ui_story_5040_50400702_121_dialog_content = "ところがある日、手紙が来なくなり、\n祖母もその後すぐに病気になりました。",
  ui_story_5040_50400702_122_dialog_content = "それがまさか…",
  ui_story_5040_50400702_123_dialog_content = "はぁ…まさに運命のイタズラですね。",
  ui_story_5040_50400702_124_dialog_content = "そんなことがあるんですね…",
  ui_story_5040_50400702_125_dialog_content = "セーブル、僕たちはいいことができたみたいだね。",
  ui_story_5040_50400702_126_dialog_content = "本当にありがとうございました！\n手紙は開封せずに、祖母の墓に供えることにします。",
  ui_story_5040_50400702_127_dialog_content = "…",
  ui_story_5040_50400702_128_dialog_content = "これも冠月祭の奇跡なのでしょう。\nどうか差出人の気持ちが祖母へ届きますように…",
  ui_story_5040_50400702_129_dialog_content = "愛の…力？",
  ui_story_5040_50400702_130_dialog_content = "そうですね。私も愛にどれほどの力があるのか、\n分かっているわけではありませんが…",
  ui_story_5040_50400702_131_dialog_content = "愛は人を救いもし、傷つけもするものです。",
  ui_story_5040_50400702_132_dialog_content = "…いずれにせよ、今日は本当にありがとうございました。",
  ui_story_5040_50400702_133_dialog_content = "お礼ならこの子に言ってください。",
  ui_story_5040_50400702_134_dialog_content = "どういたしまして…",
  ui_story_5040_50400702_135_dialog_content = "他に用がなければ、僕たちも早めに戻ろうか。",
  ui_story_5040_50400702_136_dialog_content = "うん…",
  ui_story_5040_50400702_137_dialog_content = "<color=#e8d9bb>その頃――</color>",
  ui_story_5040_50400702_138_dialog_content = "イェリア先輩、話って何でしょう？",
  ui_story_5040_50400702_139_dialog_content = "…",
  ui_story_5040_50400702_140_dialog_content = "ずっと聞きたかったことがあるの。\nあなたの親戚って、どこから湧いて来たのかしら？",
  ui_story_5040_50400702_141_dialog_content = "！！",
  ui_story_5040_50400702_142_dialog_content = "セーブルのこと…ですか？",
  ui_story_5040_50400702_143_dialog_content = "他に誰がいるって言うの？",
  ui_story_5040_50400702_144_dialog_content = "それは、その…",
  ui_story_5040_50400702_145_dialog_content = "（う、すさまじいプレッシャーです…！）",
  ui_story_5040_50400702_146_dialog_content = "回りくどいことは趣味じゃないの。\n単刀直入に聞いておくわ。",
  ui_story_5040_50400702_147_dialog_content = "あの子、光霊じゃないわよね。",
  ui_story_5040_50400702_148_dialog_content = "…！",
  ui_story_5040_50400702_149_dialog_content = "もっとハッキリ言いましょうか。\nあの子、公用語のできる暗鬼よね？",
  ui_story_5040_50400702_150_dialog_content = "イェリア先輩…",
  ui_story_5040_50400702_151_dialog_content = "ふ～ん…クーリエになってまだちょっとなのに、\n度胸は想像以上だったみたいね。",
  ui_story_5040_50400702_152_dialog_content = "見直しちゃったわぁ。",
  ui_story_5040_50400702_153_dialog_content = "あの、エルダー・イェリア！お願いできる筋じゃないことは分かってます。\nでも…どうかこのことは秘密にしてください！",
  ui_story_5040_50400702_154_dialog_content = "そんな義理も情もないと思うけど？\nアタシが秘密にしてなきゃいけない理由がある？",
  ui_story_5040_50400702_155_dialog_content = "その通りです。こんなこと、\nお願いできる義理はありませんし、そんな立場でもありません。",
  ui_story_5040_50400702_156_dialog_content = "ですから、ただお願いしてるんです！",
  ui_story_5040_50400702_157_dialog_content = "…",
  ui_story_5040_50400702_158_dialog_content = "セーブルは記憶を失っていて、\n私に助けを求めてきたんです。",
  ui_story_5040_50400702_159_dialog_content = "手助けしたって何の得もないどころか、リスクがあるだけです。\n光霊と暗鬼はいつだって敵同士…それも分かっています。",
  ui_story_5040_50400702_160_dialog_content = "でも、私は皆の気持ちを伝える橋渡しがしたくて、\nクーリエになったんです。セーブルに対しても同じことです。",
  ui_story_5040_50400702_161_dialog_content = "あまりにもかわいそうだったからと言って、\nうかつに助けてあげると約束したのは、確かに私の考えが甘く、軽率でした。",
  ui_story_5040_50400702_162_dialog_content = "でも、私が自分の気持ちに正直になって、決めたことです。\nそれに伴う責任は負います。犠牲が必要なら…それも払います。",
  ui_story_5040_50400702_163_dialog_content = "もしアタシがセーブルを「始末する」って言ったら、\n身を挺してでもかばうつもりでしょ？",
  ui_story_5040_50400702_164_dialog_content = "はい、そうします。",
  ui_story_5040_50400702_165_dialog_content = "私はクーリエです。一度始めたことは必ずやり遂げます。\nこの件も自分できちんと処理します。",
  ui_story_5040_50400702_166_dialog_content = "…",
  ui_story_5040_50400702_167_dialog_content = "あなたって、想像してたより面白いわねぇ。\nちょっと子どもっぽいけど、マジメな子はキライじゃないの。",
  ui_story_5040_50400702_168_dialog_content = "じゃ、アタシは様子を見るってことにしましょ。\nうまくいくといいわね～。",
  ui_story_5040_50400702_169_dialog_content = "ということは…秘密にしていただけるということですか？",
  ui_story_5040_50400702_170_dialog_content = "ありがとうございます！\nイェリア先輩！",
  ui_story_5040_50400702_171_dialog_content = "何があろうと、最後まで責任を持ちます。\n安心してください！",
  ui_story_5040_50400801_1_dialog_content = "セーブル、君のおかげでいい人助けができたよ。\n僕たちも早く戻ろう。",
  ui_story_5040_50400801_2_dialog_content = "うん…",
  ui_story_5040_50400801_3_dialog_content = "大丈夫？ずっと顔色が良くないみたいだね。",
  ui_story_5040_50400801_4_dialog_content = "かお…いろ？",
  ui_story_5040_50400801_5_dialog_content = "うん。こんなこと言っていいか分からないけど、\n君の顔って…ずいぶん変わってるよね？",
  ui_story_5040_50400801_6_dialog_content = "栄養不足？それともどこか身体が悪いの？",
  ui_story_5040_50400801_7_dialog_content = "たぶん…ちがう…",
  ui_story_5040_50400801_8_dialog_content = "グアア――！",
  ui_story_5040_50400801_9_dialog_content = "グガアア！！",
  ui_story_5040_50400801_10_dialog_content = "え、どうして！？暗鬼！？",
  ui_story_5040_50400801_11_dialog_content = "カナン城に暗鬼が出るなんて、聞いたこともない！",
  ui_story_5040_50400801_12_dialog_content = "うわああ！！助けて！",
  ui_story_5040_50400801_13_dialog_content = "あ！…つ、つかまって…！",
  ui_story_5040_50400801_14_dialog_content = "こ、こわくない…",
  ui_story_5040_50400801_15_dialog_content = "セーブル、あぶない！\nその子を連れて後ろに下がって！",
  ui_story_5040_50400802_1_dialog_content = "セーブル、大丈夫？",
  ui_story_5040_50400802_2_dialog_content = "だ、大丈夫…",
  ui_story_5040_50400802_3_dialog_content = "うわああ！お、お姉ちゃん、こわい！",
  ui_story_5040_50400802_4_dialog_content = "私…",
  ui_story_5040_50400802_5_dialog_content = "子どもの言うことだよ、悪気はないんだ。\n気にしないで。",
  ui_story_5040_50400802_6_dialog_content = "ただ…どうしてカナン城に暗鬼が出たんだろう…？",
  ui_story_5040_50400802_7_dialog_content = "ふぅ…皆さん、お力添えありがとうございました！",
  ui_story_5040_50400802_8_dialog_content = "ジョラ？",
  ui_story_5040_50400802_9_dialog_content = "ミジャード室長の実験用暗鬼が脱走してしまったのです。\nどういうわけか、突然騒ぎ出して…",
  ui_story_5040_50400802_10_dialog_content = "お2人に感謝します。\nおかげで死傷者が出ずに済みました。",
  ui_story_5040_50400802_11_dialog_content = "実験用の暗鬼？僕たちを「検査」した時のみたいな？",
  ui_story_5040_50400802_12_dialog_content = "そうです。色々なタイプの暗鬼が捕獲されているのです。\nどういう実験をしているのかは、僕は知りませんが…",
  ui_story_5040_50400802_13_dialog_content = "いくら捕まえてきても、\nあっという間に「なくなって」しまうようで。",
  ui_story_5040_50400802_14_dialog_content = "！！！",
  ui_story_5040_50400802_15_dialog_content = "ちゃんと気を付けてよ！\n脱走して犠牲者でも出たら大ごとでしょ！？",
  ui_story_5040_50400802_16_dialog_content = "おっしゃる通りです。このような事、今までなかったのですが…\nもしかしたら、お2人に引き寄せられたのかもしれませんね。",
  ui_story_5040_50400802_17_dialog_content = "そうだ、セーブル。ミジャードに診てもらったら？\nきっと薬だって何でもそろってるよ。",
  ui_story_5040_50400802_18_dialog_content = "具合が悪いなら、薬をもらえばいいんじゃないかな。",
  ui_story_5040_50400802_19_dialog_content = "い…いらない！！",
  ui_story_5040_50400802_20_dialog_content = "よ、用事…お、思い出した！",
  ui_story_5040_50400802_21_dialog_content = "私…キアのところ…行く！",
  ui_story_5040_50400802_22_dialog_content = "え！？",
  ui_story_5040_50400802_23_dialog_content = "なかなか面白い方のようですね。",
  ui_story_5040_50400802_24_dialog_content = "（もう遅いし、セーブルたちも戻っているはず。\n私も帰りましょう）",
  ui_story_5040_50400802_25_dialog_content = "キ…キア！！",
  ui_story_5040_50400802_26_dialog_content = "セーブル？どうしてここへ？\nPlayerNameさんと一緒じゃなかったんですか？",
  ui_story_5040_50400802_27_dialog_content = "キア…と…一緒が…いい。",
  ui_story_5040_50400802_28_dialog_content = "そうですか？じゃあ、一緒に戻りましょう。",
  ui_story_5040_50400802_29_dialog_content = "<color=#e8d9bb>グウゥ―…</color>",
  ui_story_5040_50400802_30_dialog_content = "何の…音？",
  ui_story_5040_50400802_31_dialog_content = "あ、私のお腹の音です。\nごめんなさい。",
  ui_story_5040_50400802_32_dialog_content = "ずっと何も食べてなかったので、\nお腹が空いちゃいました。",
  ui_story_5040_50400802_33_dialog_content = "私も…お腹…すいた。",
  ui_story_5040_50400802_34_dialog_content = "セーブルもですか？\nじゃあ、どこかで何か食べてから戻りましょうか。",
  ui_story_5040_50400802_35_dialog_content = "でも…人前…出られない…",
  ui_story_5040_50400802_36_dialog_content = "セーブル？",
  ui_story_5040_50400802_37_dialog_content = "そんなことは言っちゃダメですよ。\nセーブルは普通の光霊と少し違うだけ、中身は心優しいんですから！",
  ui_story_5040_50400802_38_dialog_content = "じゃあ、パンでも買って帰りましょうか？",
  ui_story_5040_50400802_39_dialog_content = "うん…",
  ui_story_5040_50400802_40_dialog_content = "そういえば、セーブルは\n啓光で何か思いだしたことはないんですか？",
  ui_story_5040_50400802_41_dialog_content = "ない…",
  ui_story_5040_50400802_42_dialog_content = "気にしないでください。砂漠のことは思い出したんですから。\nR・W砂漠に着いたら、色々見て回りましょう。",
  ui_story_5040_50400802_43_dialog_content = "心配はいりません。",
  ui_story_5040_50400802_44_dialog_content = "ありがとう…",
  ui_story_5040_50400802_45_dialog_content = "そうだ、駅の向かいに手作りのオレンジパンを個人で売っている人を見ました。\n少しここで待っていてください。",
  ui_story_5040_50400802_46_dialog_content = "すぐに戻りますから、大人しくここにいてくださいね。",
  ui_story_5040_50400802_47_dialog_content = "…！",
  ui_story_5040_50400802_48_dialog_content = "今の…ことば…",
  ui_story_5040_50400802_49_dialog_content = "すぐに戻るから、ここで待っててくれ。",
  ui_story_5040_50400802_50_dialog_content = "すぐに戻るから、ここにいるんだ。",
  ui_story_5040_50400802_51_dialog_content = "エドワード、いつまで待たせるの？\nどうしてまだ戻ってこないの…",
  ui_story_5040_50400802_52_dialog_content = "どうして…どうして私を探しに来てくれないの？",
  ui_story_5040_50400802_53_dialog_content = "どうして？私のどこがいけなかったの？",
  ui_story_5040_50400802_54_dialog_content = "<size=45>戻ってきてよ！！</size>",
  ui_story_5040_50400802_55_dialog_content = "絶望してるのね？故郷を離れて、頼る人もいない…\nこのシードを受け入れなさい。そうすれば、もう何も怖くないわ。",
  ui_story_5040_50400802_56_dialog_content = "弱者の苦しみなんて二度と味わわなくて済む。\nあなたが想像するより、はるかに強くなれるわ。",
  ui_story_5040_50400802_57_dialog_content = "ああああっ！！！",
  ui_story_5040_50400802_58_dialog_content = "ラッキーでした、冠月祭のシナモンロールが買えるなんて。\nセーブルもきっと喜びます。",
  ui_story_5040_50400802_59_dialog_content = "セーブル…",
  ui_story_5040_50400802_60_dialog_content = "きゃああ！お姉ちゃん、暗鬼だよ！",
  ui_story_5040_50400802_61_dialog_content = "暗鬼が倒れてる！",
  ui_story_5040_50400802_62_dialog_content = "ちょっと待って。この人…本当に暗鬼？\nそれとも他の何か？",
  ui_story_5040_50400802_63_dialog_content = "誰かを呼んでくるか？",
  ui_story_5040_50400802_64_dialog_content = "！！！",
  ui_story_5040_50400802_65_dialog_content = "ちょっとすみません！",
  ui_story_5040_50400802_66_dialog_content = "セーブル！セーブル、どうしたんですか！？",
  ui_story_5040_50400802_67_dialog_content = "あ…",
  ui_story_5040_50400802_68_dialog_content = "セーブル、行きましょう！",
  ui_story_5040_50400802_69_dialog_content = "待ちなさい！\nあなたたち、いったい何者！？",
  ui_story_5040_50400802_70_dialog_content = "はぁ…はぁ…",
  ui_story_5040_50400802_71_dialog_content = "シーッ！",
  ui_story_5040_50400802_72_dialog_content = "…うぅ…",
  ui_story_5040_50400802_73_dialog_content = "見つかったら大変です…！",
  ui_story_5040_50400802_74_dialog_content = "この近くで変わった見た目の暗鬼を見ませんでしたか？\n女の子1人と一緒にいたはずです。",
  ui_story_5040_50400802_75_dialog_content = "あらあら、大変ねぇ。たぶん地上に逃げていったのを見たと思うわ。\n兵士さんを呼んだ方がいいかしらぁ？",
  ui_story_5040_50400802_76_dialog_content = "何ですって？もうそんなに遠くまで…？\n急ぎましょう！",
  ui_story_5040_50400802_77_dialog_content = "イェリア先輩…ありがとうございます…",
  ui_story_5040_50400802_78_dialog_content = "どうやら行ったようですね。\nセーブル、ケガはありませんか？見せてください。",
  ui_story_5040_50400802_79_dialog_content = "だ…大丈夫。",
  ui_story_5040_50400802_80_dialog_content = "ごめん…なさい…心配…かけた…",
  ui_story_5040_50400802_81_dialog_content = "何を言ってるんですか！？あなたがケガでもしていたら、\n一人で買い物に行ったことを一生後悔するところでした！",
  ui_story_5040_50400802_82_dialog_content = "…キア。",
  ui_story_5040_50400802_83_dialog_content = "私…思い出した。",
  ui_story_5040_50400802_84_dialog_content = "思い出した？何を思い出したんですか？",
  ui_story_5040_50400802_85_dialog_content = "誰か…昔…あなたと同じこと…言った…",
  ui_story_5040_50400802_86_dialog_content = "でも…戻って…来なかった。",
  ui_story_5040_50400802_87_dialog_content = "私は…遠いところ…行って、探した。",
  ui_story_5040_50400802_88_dialog_content = "その人…私のこと…好きだって、言った。",
  ui_story_5040_50400802_89_dialog_content = "でも…最後は…私を、捨てた。",
  ui_story_5040_50400802_90_dialog_content = "私…家を出て…こわかった、ひとりだった。",
  ui_story_5040_50400802_91_dialog_content = "その時…シードを…もらった。",
  ui_story_5040_50400802_92_dialog_content = "…強く…なれるって…言われた。",
  ui_story_5040_50400802_93_dialog_content = "やっぱり、もともと光霊だったんですね！",
  ui_story_5040_50400802_94_dialog_content = "それがどうしてこんなことに…",
  ui_story_5040_50400802_95_dialog_content = "あの…魔法の薬…私…意識を…取り戻した。",
  ui_story_5040_50400802_96_dialog_content = "何もかも…忘れた…何も…信じられない。",
  ui_story_5040_50400802_97_dialog_content = "今は…お家に、帰りたい…",
  ui_story_5040_50400802_98_dialog_content = "セーブル…",
  ui_story_5040_50400802_99_dialog_content = "私が連れて帰ってあげます。必ずです！",
  ui_story_5040_50400802_100_dialog_content = "明日R・W砂漠へ出発します。\nもしかしたら、そこがセーブルの家かもしれません。",
  ui_story_5040_50400802_101_dialog_content = "ありがとう…キア。",
  ui_story_5040_50400802_102_dialog_content = "私…意識…最近、はっきりしない。",
  ui_story_5040_50400802_103_dialog_content = "たぶん…長く…もたない…",
  ui_story_5040_50400802_104_dialog_content = "もし…意識が…なくなったら…",
  ui_story_5040_50400802_105_dialog_content = "大丈夫です！そうなる前に絶対に家を見つけます！\nそれに、他にも意識を保つ方法があるかもしれません！",
  ui_story_5040_50400802_106_dialog_content = "例のサンドワームの件だってあるでしょう？\nきっと方法はあります。",
  ui_story_5040_50400802_107_dialog_content = "キア…",
  ui_story_5040_50400802_108_dialog_content = "明日は一刻も早く出発しましょう！",
  ui_story_5040_50400802_109_dialog_content = "きっと家に帰れます！",
  ui_story_5040_50400901_1_dialog_content = "着いたわ。みんな、楽にして～。",
  ui_story_5040_50400901_2_dialog_content = "ここがクーリエ隊のR・W支部ですか？",
  ui_story_5040_50400901_3_dialog_content = "外から見た時はボロボロだと思いましたが、\n中はすごくきれいですね。",
  ui_story_5040_50400901_X3_dialog_content = "そうだよね。\nそれにここ、本当に分かりにくい場所にあるし…",
  ui_story_5040_50400901_X4_dialog_content = "R・Wのキャンプってもともと大雑把に散らばってるし、\n探すのは大変だけど…",
  ui_story_5040_50400901_X5_dialog_content = "路地を10分以上歩いて、\nやっと着くような場所だとは思ってなかったよ。",
  ui_story_5040_50400901_X6_dialog_content = "初めて来た時なんて、ずいぶん道に迷ったんだ。",
  ui_story_5040_50400901_X7_dialog_content = "それならまだマシよ！",
  ui_story_5040_50400901_X8_dialog_content = "あたしなんて、全然見つからないから、\nあきらめようかと思ったもの。",
  ui_story_5040_50400901_4_dialog_content = "それにしても…この部屋のインテリア、\n何度見ても驚かされるよ。",
  ui_story_5040_50400901_5_dialog_content = "きれいなだけじゃない。\n精巧に作られていて、数も目がくらむほどある。",
  ui_story_5040_50400901_6_dialog_content = "R・Wの雰囲気とは全然違うね！",
  ui_story_5040_50400901_7_dialog_content = "あら～？それってアタシのこと、\nその辺のヤバンな盗賊と一緒だと思ってたってことぉ？",
  ui_story_5040_50400901_8_dialog_content = "いや、そういう意味じゃないけど…",
  ui_story_5040_50400901_9_dialog_content = "ふふ、ちょっとからかっただけよ。",
  ui_story_5040_50400901_10_dialog_content = "…あの、イェリア先輩。\nセーブルと一緒に見せてもらいたいものが――",
  ui_story_5040_50400901_11_dialog_content = "構わないわよ、好きなだけ見るといいわ。",
  ui_story_5040_50400901_12_dialog_content = "えっ？",
  ui_story_5040_50400901_13_dialog_content = "ただし、見終わったらちゃんと元の位置に戻しといてね。",
  ui_story_5040_50400901_14_dialog_content = "はい、分かりました！",
  ui_story_5040_50400901_15_dialog_content = "セーブル、行きましょう！",
  ui_story_5040_50400901_16_dialog_content = "アタシも車と武器を用意してくるわ。",
  ui_story_5040_50400901_17_dialog_content = "もう日が暮れるから、今晩はここに泊まって。",
  ui_story_5040_50400901_18_dialog_content = "車…ですか？\n巨像の方が速いのではないでしょうか？",
  ui_story_5040_50400901_X18_dialog_content = "巨像の方が車より大きいですし、\nずっと安全では…？",
  ui_story_5040_50400901_19_dialog_content = "サンドワームが活動するのは地表と地下。",
  ui_story_5040_50400901_20_dialog_content = "地下に掘った穴を使って、高速で移動したり、\n身を隠したりするずる賢い生き物よ。",
  ui_story_5040_50400901_21_dialog_content = "見つけたらすぐに捕まえないと、\nあっという間に逃げられちゃうわ。",
  ui_story_5040_50400901_X21_dialog_content = "そうなんですか！？",
  ui_story_5040_50400901_X22_dialog_content = "イェリアの言う通りだね。",
  ui_story_5040_50400901_22_dialog_content = "巨像は確かに速いし安全だけど、\nサンドワームを見つけて攻撃するには時間がかかる。",
  ui_story_5040_50400901_X23_dialog_content = "そのせいで大変な目に遭ったこともあるよ。",
  ui_story_5040_50400901_23_dialog_content = "そうだったんですね…",
  ui_story_5040_50400901_24_dialog_content = "砂漠で暮らすなら勉強しなきゃいけないことが\nたくさんありそうね～。",
  ui_story_5040_50400901_25_dialog_content = "じゃ、アタシは先に失礼するわ。\n明日は朝一番からサンドワーム探しに出発よ。",
  ui_story_5040_50400901_26_dialog_content = "<color=#e8d9bb>グウゥ―…</color>",
  ui_story_5040_50400901_27_dialog_content = "あ！",
  ui_story_5040_50400901_28_dialog_content = "そういえば、1日中あちこち駆け回ってたから、\nきちんと食事してなかったね。",
  ui_story_5040_50400901_29_dialog_content = "<color=#e8d9bb>グウゥ――</color>",
  ui_story_5040_50400901_30_dialog_content = "僕もお腹が空いてきたよ。",
  ui_story_5040_50400901_31_dialog_content = "せっかくここまで来たんだから、\nあたしがR・W風の特製料理をごちそうしてあげるわ！",
  ui_story_5040_50400901_32_dialog_content = "外でたき火を燃やしてくるわ。\nバーベキューにしましょ。",
  ui_story_5040_50400901_33_dialog_content = "僕も手伝うよ！",
  ui_story_5040_50400901_34_dialog_content = "…取り残されちゃった…",
  ui_story_5040_50400901_35_dialog_content = "ターラとアドニスの邪魔はしちゃいけないよね。\nキアとセーブルの方も僕の助けは必要なさそうだし…",
  ui_story_5040_50400901_36_dialog_content = "そういえば、ピンクのサンドワームって\nすごく大きいはずだよね。僕たちだけで本当に大丈夫かな？",
  ui_story_5040_50400901_37_dialog_content = "イェリアはたぶん強そうだし、ターラが強いのは見たけど、\nやっぱり心配だな…",
  ui_story_5040_50400901_38_dialog_content = "何か助けが要らないか、\nイェリアに聞いてみよう。",
  ui_story_5040_50400901_39_dialog_content = "あら、空の末裔くんじゃな～い？\nアタシがいないと怖いの？",
  ui_story_5040_50400901_40_dialog_content = "その言い方はかなり問題があるかな…",
  ui_story_5040_50400901_41_dialog_content = "安心して。この砂漠は庭みたいなものだから。",
  ui_story_5040_50400901_42_dialog_content = "車は点検したし、消耗品も十分用意したわ。\nあなたたちは自分のことだけ考えてればいいの。",
  ui_story_5040_50400901_43_dialog_content = "でも、サンドワームは危険な生き物でしょ。\n僕たちだけで本当に太刀打ちできるか、心配なんだ。",
  ui_story_5040_50400901_44_dialog_content = "助っ人でも頼んだ方がいいんじゃない？\nサメヤマとかアズールとか…？",
  ui_story_5040_50400901_45_dialog_content = "必要ないわ。",
  ui_story_5040_50400901_46_dialog_content = "でも――",
  ui_story_5040_50400901_47_dialog_content = "アタシは誰かの助けなんて要らないの。",
  ui_story_5040_50400901_48_dialog_content = "アタシ一人で十分、たかがサンドワームよ？\n二、三発で倒せるわ。",
  ui_story_5040_50400901_49_dialog_content = "他に用がないなら、もう戻って休んでなさい。",
  ui_story_5040_50400901_50_dialog_content = "アタシはまだやることがあるの。\n子どもの気遣いなんていらないわ。",
  ui_story_5040_50400901_51_dialog_content = "…",
  ui_story_5040_50400901_52_dialog_content = "…分かったよ。",
  ui_story_5040_50400901_S52_dialog_content = "ソラヴァンに戻るね。",
  ui_story_5040_50400901_53_dialog_content = "はぁ…イェリアに追い払われちゃった…",
  ui_story_5040_50400901_54_dialog_content = "…まあ、いいや。\n構わないで欲しいって言うなら、構わなければいいんだ。",
  ui_story_5040_50400901_55_dialog_content = "…",
  ui_story_5040_50400901_X55_dialog_content = "（それにしても…イェリアはずっと他人事みたいな顔だ。\n皆を観察して楽しんでるようにも見える）",
  ui_story_5040_50400901_X56_dialog_content = "（クーリエ隊の中では高い地位みたいだけど、\nどうにも信用しきれない…）",
  ui_story_5040_50400901_X57_dialog_content = "（万が一のために、やっぱりR・Wに連絡してみよう）",
  ui_story_5040_50400901_X58_dialog_content = "（近くに誰かいればいいけど…）",
  ui_story_5040_50400901_56_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_5040_50400901_57_dialog_content = "こちらオティ。PlayerName、聞こえたら応答して。",
  ui_story_5040_50400901_58_dialog_content = "オティ！よかった！",
  ui_story_5040_50400901_59_dialog_content = "こちらPlayerName！\nよかった、反応してくれて！",
  ui_story_5040_50400901_60_dialog_content = "どうしたの？",
  ui_story_5040_50400901_61_dialog_content = "オティ、ピンクのサンドワームについて何か知らない？",
  ui_story_5040_50400901_62_dialog_content = "ピンクのサンドワーム…？\nうーん、どこかで聞いたことあるわね…",
  ui_story_5040_50400901_63_dialog_content = "そうだ、思い出した。1か月ぐらい前ね。\nサメヤマさんがピンクのサンドワームに遭遇したらしいわ。",
  ui_story_5040_50400901_64_dialog_content = "誰も見たことない色だったから捕まえようとしたけど、\n逃げられちゃったそうよ。",
  ui_story_5040_50400901_65_dialog_content = "でも、詳しいことは知らないわ。\n本人を呼んでくるから、直接聞いて。",
  ui_story_5040_50400901_66_dialog_content = "うん、ありがとう！",
  ui_story_5040_50400901_67_dialog_content = "おう、PlayerName。",
  ui_story_5040_50400901_68_dialog_content = "オティの話じゃ、\nピンクのサンドワームのことが知りてぇらしいな？",
  ui_story_5040_50400901_69_dialog_content = "そうなんだよ！何か覚えてる？",
  ui_story_5040_50400901_70_dialog_content = "そりゃ、覚えてるに決まってんだろ。\n俺から逃げられるサンドワームなんてそういねぇからな。",
  ui_story_5040_50400901_71_dialog_content = "1か月ぐれぇ前に狩ろうとしたんだが、\n逃げられちまって、残ったのはウロコ1枚だけだった。",
  ui_story_5040_50400901_72_dialog_content = "チッ、惜しいことしたぜ…ウロコ1枚にすげぇ値段が付いたんだ。\n1匹丸ごと捕まえてたら、今ごろ大もうけだったのによ。",
  ui_story_5040_50400901_73_dialog_content = "なんたって、この世に2匹いるかも分からねぇ、\nピンクのサンドワームだからな。",
  ui_story_5040_50400901_74_dialog_content = "…にしても、なんでお前がそんなもん探してんだ？\nまさか、イェリアも一緒か？",
  ui_story_5040_50400901_75_dialog_content = "どうして知ってるの！？",
  ui_story_5040_50400901_76_dialog_content = "どうしてって、イェリアの言霊がR・W砂漠じゅうの\nサンドワームの住みかを飛び回ってたからさ。",
  ui_story_5040_50400901_77_dialog_content = "このタイミングでサンドワーム探しってこたぁ、\nピンクのアイツを探してるとしか考えられねぇだろ。",
  ui_story_5040_50400901_78_dialog_content = "あんな強い光力術をあちこちで使いやがって、\n人騒がせもいい所だぜ。",
  ui_story_5040_50400901_79_dialog_content = "サメヤマはピンクのサンドワームが\nどこにいるか知ってるの？",
  ui_story_5040_50400901_80_dialog_content = "もちろん知ってるさ。だが…タダってワケにゃいかねえな。\n取引だ、何を出す？",
  ui_story_5040_50400901_81_dialog_content = "それは…ええと…",
  ui_story_5040_50400901_82_dialog_content = "ハハハ、そうビビんなって。\n取って食われるとでも思ったか？",
  ui_story_5040_50400901_83_dialog_content = "今度R・Wに来る時、\nイブにチョコレートを持って来い。",
  ui_story_5040_50400901_84_dialog_content = "イブのやつ、影ノ街で「ナントカ祭」に合わせて\n期間限定のチョコレートが出てるって聞いて、欲しがってるんだ。",
  ui_story_5040_50400901_85_dialog_content = "お前の巨像ならあっという間だろ？\nイブにそのチョコレートを買って来てくれ。",
  ui_story_5040_50400901_86_dialog_content = "それぐらいなら問題ないよ！",
  ui_story_5040_50400901_87_dialog_content = "じゃ、決まりだな。",
  ui_story_5040_50400901_88_dialog_content = "あのサンドワームだが、かなりずる賢いぞ。\n俺と戦った時もうろちょろ逃げ回られてな。",
  ui_story_5040_50400901_89_dialog_content = "逃げおおせる前にレンチを思いっきり食らわせて、\n左半分のウロコを粉々に砕いてやった。",
  ui_story_5040_50400901_90_dialog_content = "それから何日も後を追ったんだが、結局見失っちまったんだ。\n最後に見たのは砂漠の奥のオアシス近くだ。",
  ui_story_5040_50400901_91_dialog_content = "具体的な場所までは俺も分からねぇ。",
  ui_story_5040_50400901_92_dialog_content = "ヤツを探すってんなら、その辺りからだな。",
  ui_story_5040_50400901_93_dialog_content = "分かったよ！ありがとう、サメヤマ！",
  ui_story_5040_50400901_94_dialog_content = "イェリアもいるなら問題はねぇだろうが、油断するなよ。\nかなり手ごわいぞ。",
  ui_story_5040_50400901_95_dialog_content = "イェリアがいれば大丈夫って、どうして？\nよく知ってるの？",
  ui_story_5040_50400901_96_dialog_content = "いいや、あいつは一匹オオカミだからな。\nほとんど誰とも話さねぇ。",
  ui_story_5040_50400901_97_dialog_content = "だが、このR・W砂漠じゃ、\n一人で生きてるってこと自体が実力の証だ。",
  ui_story_5040_50400901_98_dialog_content = "それに、砂漠じゃ数少ないクーリエだからな。\n俺たちも普段からいろいろ世話になってんのさ。",
  ui_story_5040_50400901_99_dialog_content = "心配するな、安心して付いていけばいいと思うぜ。",
  ui_story_5040_50400901_100_dialog_content = "そうなんだ…？",
  ui_story_5040_50400901_101_dialog_content = "分かったよ。",
  ui_story_5040_50400901_102_dialog_content = "じゃ、話はここまでだ。\n早く休まねぇと、イブがうるさいからな。",
  ui_story_5040_50400901_103_dialog_content = "うん、また今度！",
  ui_story_5040_50400901_104_dialog_content = "イェリアは忙しくしてそうだし、\nまずはターラとアドニスに教えてあげよう。",
  ui_story_5040_50400901_105_dialog_content = "ちょうどお腹も空いたし…\n今日の晩ご飯は何になるかな？",
  ui_story_5040_50400901_106_dialog_content = "<color=#e8d9bb>その頃、クーリエ隊R・W支部</color>",
  ui_story_5040_50400901_107_dialog_content = "溜まっている手紙はこれで全部のはずです。",
  ui_story_5040_50400901_108_dialog_content = "砂漠は広いうえに、R・Wの人たちは\n居場所の定まらない人の集まりですから、配達不能の手紙も多いんです。",
  ui_story_5040_50400901_109_dialog_content = "探すにしても、かなり時間がかかるでしょうね。",
  ui_story_5040_50400901_110_dialog_content = "私も…手伝う。",
  ui_story_5040_50400901_111_dialog_content = "そうですね、一緒に頑張りましょう！\nまずは全部でどれぐらいあるのか、箱を開けて見てみましょう。",
  ui_story_5040_50400901_112_dialog_content = "手紙…たくさん！",
  ui_story_5040_50400901_113_dialog_content = "あ、ちょっと待ってください。\n手紙にラベルが貼られてますね。",
  ui_story_5040_50400901_114_dialog_content = "「受取人失踪」、「受取人不明」、「受取拒否」…",
  ui_story_5040_50400901_115_dialog_content = "ご丁寧に、分類までされてるようです。",
  ui_story_5040_50400901_116_dialog_content = "キア…見て…",
  ui_story_5040_50400901_117_dialog_content = "このラベル…「同一の切手」と書かれていますね。",
  ui_story_5040_50400901_118_dialog_content = "何か注釈があります。\n「おそらく送り主は同一人物」…",
  ui_story_5040_50400901_119_dialog_content = "この切手…セーブルが持っていたのと同じです！",
  ui_story_5040_50400901_120_dialog_content = "これ、私の…？",
  ui_story_5040_50400901_121_dialog_content = "こんなに早く見つかるとは思いませんでした！\nよかったですね！",
  ui_story_5040_50400901_122_dialog_content = "中を見てみましょうか。",
  ui_story_5040_50400901_123_dialog_content = "うん。",
  ui_story_5040_50400901_124_dialog_content = "「私と文通してくれてありがとう。\nあなたと知り合えてうれしいわ」",
  ui_story_5040_50400901_125_dialog_content = "「砂漠って、すごく暑いの。みんなバラバラに住んでるから、\nクーリエがいないと連絡も取れないし」",
  ui_story_5040_50400901_126_dialog_content = "「でも、あなたと一緒なら、砂漠を離れたって構わないわ」",
  ui_story_5040_50400901_127_dialog_content = "知り合ったばかりの頃に書いた手紙のようですね。",
  ui_story_5040_50400901_128_dialog_content = "送り先の住所が全部違いますね。差出人の住所もありません…",
  ui_story_5040_50400901_129_dialog_content = "セーブルの家は砂漠にあったんでしょうか？",
  ui_story_5040_50400901_130_dialog_content = "うう…",
  ui_story_5040_50400901_131_dialog_content = "うっ！！",
  ui_story_5040_50400901_132_dialog_content = "セーブル！？",
  ui_story_5040_50400901_133_dialog_content = "…思い出した…",
  ui_story_5040_50400901_134_dialog_content = "私の家…砂漠の…奥…",
  ui_story_5040_50400901_135_dialog_content = "でも…どこか、覚えてない…",
  ui_story_5040_50400901_136_dialog_content = "構いませんよ、それだけで十分有力な手がかりです！\n砂漠の人たちに聞いてみましょう。",
  ui_story_5040_50400901_137_dialog_content = "無理して思い出そうとしなくていいですよ。\nまずはゆっくり休みましょう。",
  ui_story_5040_50400901_138_dialog_content = "私はクーリエです。\n引き受けたことは、必ず責任をもってやり遂げます。",
  ui_story_5040_50400901_139_dialog_content = "うん…",
  ui_story_5040_50400901_140_dialog_content = "セーブル、どうしたんですか？\n元気がないみたいですね？",
  ui_story_5040_50400901_141_dialog_content = "ターラ、アドニス…仲がいい…",
  ui_story_5040_50400901_142_dialog_content = "お互い、大切…助け合ってる…",
  ui_story_5040_50400901_143_dialog_content = "うらやましい…",
  ui_story_5040_50400901_144_dialog_content = "（セーブルは昔、愛する人に大切にしてもらえず、\n愛が実ることもなかったのでしょうね…）",
  ui_story_5040_50400901_145_dialog_content = "（他の幸せそうなカップルを見ているのは、\n確かに辛いのかもしれません）",
  ui_story_5040_50400901_146_dialog_content = "悲しむことはありませんよ。\nあなたにヒドいことをした男はもう過去のものです！",
  ui_story_5040_50400901_147_dialog_content = "先輩から聞いた話だと、他人によくしてあげられない人は、\nかならず報いを受けると言います。",
  ui_story_5040_50400901_148_dialog_content = "もしアドニスさんとターラさんを見ているのが辛いなら、\nここを離れて2人だけで行動しましょうか？",
  ui_story_5040_50400901_149_dialog_content = "だ、大丈夫…",
  ui_story_5040_50400901_150_dialog_content = "2人を見て、いいことも…思い出した。",
  ui_story_5040_50400901_151_dialog_content = "家族、友だち、それから…愛…",
  ui_story_5040_50400901_152_dialog_content = "ずっとほしかった…ぬくもり…",
  ui_story_5040_50400901_153_dialog_content = "ぬくもり…とっても大切…\nだから…幸せに…なってほしい。",
  ui_story_5040_50400901_154_dialog_content = "そうですね…",
  ui_story_5040_50400901_155_dialog_content = "<color=#e8d9bb>グウゥ――</color>",
  ui_story_5040_50400901_156_dialog_content = "お腹、すいた…",
  ui_story_5040_50400901_157_dialog_content = "私もお腹が空きました、\n晩ご飯を食べに行きましょう！",
  ui_story_5040_50400901_158_dialog_content = "（もうこんな時間になっちゃった。\nご飯の支度はできてるかな？）",
  ui_story_5040_50400901_159_dialog_content = "ハクション――！",
  ui_story_5040_50400901_160_dialog_content = "（こ、この刺激的な臭いは――R・Wのバーベキュー！）",
  ui_story_5040_50400901_161_dialog_content = "あれ？キア、セーブル？\n辺りを見に行ったんじゃなかったの？",
  ui_story_5040_50400901_162_dialog_content = "それは終わりました。ちょうどお腹が空いたので、\n夕食を食べに戻ってきたところです！",
  ui_story_5040_50400901_163_dialog_content = "うん…",
  ui_story_5040_50400901_164_dialog_content = "（まさか、あれほどたくさんの郵便物が\nきれいに分類、整理されているとは思いませんでした）",
  ui_story_5040_50400901_165_dialog_content = "（しかも、特徴ごとに同じ送り主と思われるものを\nまとめてあるなんて…）",
  ui_story_5040_50400901_166_dialog_content = "（おかげで、すぐに目的のものが見つかりました）",
  ui_story_5040_50400901_167_dialog_content = "（きっとイェリア先輩の仕事ですね）",
  ui_story_5040_50400901_168_dialog_content = "あら～？ずいぶんにぎやかじゃない。",
  ui_story_5040_50400901_169_dialog_content = "この匂い…ふふ、R・Wの人たちって、\nバーベキューしか作れないの？",
  ui_story_5040_50400901_170_dialog_content = "砂漠に来たら砂漠の料理が一番でしょ。",
  ui_story_5040_50400901_171_dialog_content = "イェリア、もう用は済んだの？",
  ui_story_5040_50400901_172_dialog_content = "ええ。車も装備も準備できてるわよ。\nサンドワームの居場所も見当がついたわ。",
  ui_story_5040_50400901_173_dialog_content = "エモノはケガをして、砂漠の奥に逃げてるみたいね。",
  ui_story_5040_50400901_174_dialog_content = "（サメヤマのくれた情報と同じ…問題はなさそうだ）",
  ui_story_5040_50400901_175_dialog_content = "（それなら、さっきの話は黙っておこう。\nイェリアの機嫌を損ねてもいけないし…）",
  ui_story_5040_50400901_176_dialog_content = "ちょうどいいところに来たわね！\nトカゲの丸焼きができたところよ！",
  ui_story_5040_50400901_177_dialog_content = "これ…本当にバーベキューですか？\nトウガラシが多すぎて元の食材が何だか分かりませんよ…",
  ui_story_5040_50400901_178_dialog_content = "「激辛トカゲの丸焼き」ね。\n勇気のある者だけが食べられるR・W最高級の一品よ！",
  ui_story_5040_50400901_179_dialog_content = "うっ…本当にこれを食べなきゃいけないのかい？",
  ui_story_5040_50400901_180_dialog_content = "においを嗅いだだけでのどが痛くなってきたよ。",
  ui_story_5040_50400901_181_dialog_content = "食べるの？食べないの？",
  ui_story_5040_50400901_182_dialog_content = "た、食べるよ、もちろん！",
  ui_story_5040_50400901_183_dialog_content = "アドニス、無理しないで。",
  ui_story_5040_50400901_184_dialog_content = "もぐもぐ――",
  ui_story_5040_50400901_185_dialog_content = "…",
  ui_story_5040_50400901_186_dialog_content = "ま、まるごと1本食べちゃった！？",
  ui_story_5040_50400901_187_dialog_content = "…！",
  ui_story_5040_50400901_188_dialog_content = "<color=#e8d9bb>バタン！</color>",
  ui_story_5040_50400901_189_dialog_content = "アドニス！？",
  ui_story_5040_50400901_190_dialog_content = "あら大変、顔が紫色。",
  ui_story_5040_50400901_191_dialog_content = "か、辛い…",
  ui_story_5040_50400901_192_dialog_content = "<size=45>辛すぎる――！！</size>",
  ui_story_5040_50400901_193_dialog_content = "今にも気を失いそうです！",
  ui_story_5040_50400901_194_dialog_content = "急いでミルクを飲ませてあげて！\nミルクは辛さを緩和するって聞いたことがある！",
  ui_story_5040_50400901_195_dialog_content = "探してきます！",
  ui_story_5040_50400901_196_dialog_content = "…",
  ui_story_5040_50400901_197_dialog_content = "（ターラ、どうしてどこかに行ったのかしら？\n様子を見た方が良さそうねぇ）",
  ui_story_5040_50400901_198_dialog_content = "ミルクを持ってきました！",
  ui_story_5040_50400901_199_dialog_content = "アドニス、急いで飲んで！",
  ui_story_5040_50400901_200_dialog_content = "ゴクッ、ゴクッ――",
  ui_story_5040_50400901_201_dialog_content = "はぁ…はぁ…僕…まだ…生きてますか…？",
  ui_story_5040_50400901_202_dialog_content = "トカゲの丸焼きを丸ごと1本食べて、\nそのまま倒れちゃっただけだよ。",
  ui_story_5040_50400901_203_dialog_content = "そうでしたか…",
  ui_story_5040_50400901_204_dialog_content = "うっ…胃がひどく痛みます。\nまるで燃えている炭をそのまま飲み込んだみたいです…",
  ui_story_5040_50400901_205_dialog_content = "<size=45><anim type=Shake>オェッ…！</anim></size>",
  ui_story_5040_50400901_206_dialog_content = "アドニス！！",
  ui_story_5040_50400901_207_dialog_content = "<color=#e8d9bb>その頃――</color>",
  ui_story_5040_50400901_208_dialog_content = "恋人が気を失いそうになって吐いてるっていうのに、\n介抱してあげないの？",
  ui_story_5040_50400901_209_dialog_content = "それとも、また何か思いつき？",
  ui_story_5040_50400901_210_dialog_content = "体調が回復したら、アドニスを北境まで送ってあげて。",
  ui_story_5040_50400901_211_dialog_content = "あたし…もう疲れちゃった…これ以上続ける気はないわ。",
  ui_story_5040_50400901_212_dialog_content = "あたしたち、もともと一緒になるべきじゃなかったのよ。\n合わないもの。",
  ui_story_5040_50400901_213_dialog_content = "あら？",
  ui_story_5040_50400901_214_dialog_content = "最初は2人なら、\nどんな困難でも乗り越えられるって思ってた。",
  ui_story_5040_50400901_215_dialog_content = "だから、アドニスにも砂漠の生活を体験してもらいたくて…\nさっきのバーベキューもそう…",
  ui_story_5040_50400901_216_dialog_content = "でも、あたしの好きなものが\nアドニスを傷つけるなんて思わなかったわ。",
  ui_story_5040_50400901_217_dialog_content = "…アドニスはいつもあたしに合わせようとムリをして、\n傷付いてばかりよ。",
  ui_story_5040_50400901_218_dialog_content = "そんなの、愛じゃない。",
  ui_story_5040_50400901_X218_dialog_content = "ふ～ん…やっぱり恋愛中の小鳥ちゃんって、\n何でも考えすぎちゃうのねぇ。",
  ui_story_5040_50400901_X219_dialog_content = "どうしてそう思うの？",
  ui_story_5040_50400901_219_dialog_content = "あたしとアドニスは生き方も性格もまったく違う…\nきっと…彼の両親の言うことが正しかったのよ。",
  ui_story_5040_50400901_220_dialog_content = "北境育ちで羽毛もないし、地中から水を手に入れる方法も知らないのよ？\n砂漠で生きられないのは当然じゃない。",
  ui_story_5040_50400901_221_dialog_content = "…",
  ui_story_5040_50400901_222_dialog_content = "勇気があれば克服できるってことじゃないわ。\n身体の構造から違うんだもの。",
  ui_story_5040_50400901_223_dialog_content = "砂漠育ちのあなたには普通のことでも、\n北境の温室育ちの子にとっては危険でしかないの。",
  ui_story_5040_50400901_224_dialog_content = "でも…",
  ui_story_5040_50400901_225_dialog_content = "「でも」何よ？",
  ui_story_5040_50400901_226_dialog_content = "あの子ったら、辛いものが食べられないくせに、\nムリして食べて、結局倒れちゃったわねぇ。",
  ui_story_5040_50400901_227_dialog_content = "…それって、あなたに見せたかったってことじゃないの？\n勇気を出して、かじりつくところを。",
  ui_story_5040_50400901_228_dialog_content = "暮らし方なんて、\nゆっくり2人で探していけばいいんじゃない？",
  ui_story_5040_50400901_229_dialog_content = "砂漠で暮らすしかないって話でもないでしょ？",
  ui_story_5040_50400901_230_dialog_content = "…！",
  ui_story_5040_50400901_231_dialog_content = "ま、アタシの言いたいことはそれくらいねぇ。",
  ui_story_5040_50400901_232_dialog_content = "あなたたちがくっつこうと別れようと好きにすればいいけど、\nせっかくアタシの家にいるんだし、気分転換だとでも思えばいいわ。",
  ui_story_5040_50400901_233_dialog_content = "みんな楽しめばいいだけ、\n水を差さないで欲しいところね。",
  ui_story_5040_50400901_234_dialog_content = "…",
  ui_story_5040_50400901_235_dialog_content = "分かったわ。",
  ui_story_5040_50400901_236_dialog_content = "あたし、戻る。",
  ui_story_5040_50400901_237_dialog_content = "ふふふ…面白い子ねぇ。",
  ui_story_5040_50400901_238_dialog_content = "これからどうなるかしら？\n面白くなりそう。",
  ui_story_5040_50400901_239_dialog_content = "…それにしても、アタシったらどうしちゃったのかしらね？",
  ui_story_5040_50400901_240_dialog_content = "他人に興味を持つなんて。",
  ui_story_5040_50401001_1_dialog_content = "あら～？早いじゃない。",
  ui_story_5040_50401001_2_dialog_content = "今日はサンドワームを探しに行くんでしょ。\nだから、早起きしたんだ。",
  ui_story_5040_50401001_3_dialog_content = "昨日は結局、誰もバーベキューを食べる勇気がなくて、\nソラヴァンで作り直すことになったけど…",
  ui_story_5040_50401001_4_dialog_content = "あなたたちって、ほんと食のセンスがないわね。\nバーベキューはあたしが全部食べたから、安心して。",
  ui_story_5040_50401001_5_dialog_content = "食べ物は一切ムダにしてないわ！",
  ui_story_5040_50401001_6_dialog_content = "それはいいことね～。",
  ui_story_5040_50401001_7_dialog_content = "ところで、ゆうべはよく眠れたかしら？\n砂漠になじめないってことはなかった？",
  ui_story_5040_50401001_8_dialog_content = "アタシはよく眠れたけどね～。",
  ui_story_5040_50401001_9_dialog_content = "砂漠の夜って肌寒いんですね…\n先輩が厚めの毛布を用意してくださったので、私もセーブルもよく眠れました。",
  ui_story_5040_50401001_10_dialog_content = "イェリア、ありがとう。",
  ui_story_5040_50401001_11_dialog_content = "ふふ、どういたしまして。",
  ui_story_5040_50401001_12_dialog_content = "僕は…その…",
  ui_story_5040_50401001_13_dialog_content = "一晩中、腹痛で…",
  ui_story_5040_50401001_14_dialog_content = "（夜中に何度もトイレに駆け込む音がしたのは、\nアドニスだったのかな…）",
  ui_story_5040_50401001_15_dialog_content = "休まなくて大丈夫？",
  ui_story_5040_50401001_16_dialog_content = "だ、大丈夫です！",
  ui_story_5040_50401001_17_dialog_content = "何ともありません、皆さんとご一緒します！",
  ui_story_5040_50401001_18_dialog_content = "…",
  ui_story_5040_50401001_19_dialog_content = "（昨日の夕食から、ターラの表情がどこか浮かない。\n悩み事でもあるのかな？）",
  ui_story_5040_50401001_20_dialog_content = "じゃ、車に乗って。ターラは助手席にお願い。\n狭いでしょうけど、他のみんなは後ろよ～。",
  ui_story_5040_50401001_21_dialog_content = "<color=#e8d9bb>しばらくして</color>",
  ui_story_5040_50401001_22_dialog_content = "そろそろねぇ。\nサンドワームが出そうな辺りも近いわよ。",
  ui_story_5040_50401001_23_dialog_content = "今のうちに最後の休憩をとりましょ。",
  ui_story_5040_50401001_24_dialog_content = "テントや調理器具、食材は私とセーブルで\n車から下ろしておきました。",
  ui_story_5040_50401001_25_dialog_content = "いつでも食事を作れます！",
  ui_story_5040_50401001_26_dialog_content = "じゃあ、お願いするわ。",
  ui_story_5040_50401001_27_dialog_content = "荷物を下ろしたら、みんなは車に戻ってちょうだい。",
  ui_story_5040_50401001_28_dialog_content = "え？どうして？休憩するんじゃないの？",
  ui_story_5040_50401001_29_dialog_content = "その前にやっておくことがあるのよ。",
  ui_story_5040_50401001_30_dialog_content = "この先の砂丘は起伏がもっと激しいから、\n気分転換のドライブには絶好の場所よ～。",
  ui_story_5040_50401001_31_dialog_content = "それとこれと、何か関係があるんですか？",
  ui_story_5040_50401001_32_dialog_content = "今にわかるわ。",
  ui_story_5040_50401001_X32_dialog_content = "いいから、早く乗って。",
  ui_story_5040_50401001_X33_dialog_content = "ですが…",
  ui_story_5040_50401001_X34_dialog_content = "ほら、ごちゃごちゃ言ってないで、早く乗って！",
  ui_story_5040_50401001_X35_dialog_content = "空の末裔くんもいらっしゃい。",
  ui_story_5040_50401001_X36_dialog_content = "<color=#e8d9bb>車の中</color>",
  ui_story_5040_50401001_X37_dialog_content = "みんな、しっかり座ったかしら？",
  ui_story_5040_50401001_X38_dialog_content = "…イェリア、何をするつもり？",
  ui_story_5040_50401001_X39_dialog_content = "もちろん…ターラが喜びそうなことよ。",
  ui_story_5040_50401001_X40_dialog_content = "嫌な予感がしてきたんだけど…\n下ろしてもらえないかな！？",
  ui_story_5040_50401001_X41_dialog_content = "僕はご飯の準備を手伝うから――",
  ui_story_5040_50401001_X42_dialog_content = "ダメよ。空の末裔くんは欠かせないもの。",
  ui_story_5040_50401001_33_option_content = "欠かせない！？",
  ui_story_5040_50401001_34_dialog_content = "当然でしょ、大事な「ナビゲーター」だもの。",
  ui_story_5040_50401001_35_option_content = "僕はやめとく！",
  ui_story_5040_50401001_36_dialog_content = "今さら逃げ出すなんてカッコ悪いわよ～、空の末裔くん？",
  ui_story_5040_50401001_37_dialog_content = "あ、シートベルトはしっかり締めてね。",
  ui_story_5040_50401001_38_dialog_content = "<color=#e8d9bb>ブオン――！</color>",
  ui_story_5040_50401001_39_dialog_content = "うわあ！？",
  ui_story_5040_50401001_40_dialog_content = "は、速すぎない！？",
  ui_story_5040_50401001_41_dialog_content = "アハハ！気持ちいいわ！",
  ui_story_5040_50401001_42_dialog_content = "イェリア、もっと速く！",
  ui_story_5040_50401001_43_dialog_content = "た、助けてください！\n車が吹き飛びそうです！",
  ui_story_5040_50401001_44_dialog_content = "これが…飛ぶ…感覚？",
  ui_story_5040_50401001_X44_dialog_content = "ダメだよ！これ以上スピード上げないで！\nああああ、危ない！",
  ui_story_5040_50401001_X45_dialog_content = "い、胃が…ひっくり返りそうです…",
  ui_story_5040_50401001_45_dialog_content = "もっと速く、もっと風に向かって突っ込んで！\nそうじゃないと、飛ぶことの気持ちよさが分からないわ！",
  ui_story_5040_50401001_46_dialog_content = "グォォ――！！！",
  ui_story_5040_50401001_47_dialog_content = "気を付けて！暗鬼が車の音で寄ってきた！",
  ui_story_5040_50401001_48_dialog_content = "空の末裔くん、あなたの出番よ～。",
  ui_story_5040_50401001_49_dialog_content = "え！？",
  ui_story_5040_50401001_50_dialog_content = "目でも感知能力でもいいわ。\n暗鬼がどっちから来るのか教えてちょうだい。",
  ui_story_5040_50401001_51_dialog_content = "こんなスピードが出てるのに！？無理だよ！",
  ui_story_5040_50401001_52_dialog_content = "グォォ！",
  ui_story_5040_50401001_53_dialog_content = "うっ！左後方！",
  ui_story_5040_50401001_54_dialog_content = "了解～。",
  ui_story_5040_50401001_55_dialog_content = "<color=#e8d9bb>キィ――</color>",
  ui_story_5040_50401001_56_dialog_content = "<color=#e8d9bb>ドン！！</color>",
  ui_story_5040_50401001_57_dialog_content = "車で直接暗鬼をはじき飛ばした…！？",
  ui_story_5040_50401001_58_dialog_content = "も、もう…無理です…うっぷ！",
  ui_story_5040_50401001_59_dialog_content = "車の中に吐かないでね～。",
  ui_story_5040_50401001_60_dialog_content = "ところでほら、ターラは珍しく楽しそうでしょ。",
  ui_story_5040_50401001_61_dialog_content = "そ、そうなんですか？\nじゃ、じゃあ、我慢します…ターラのために…",
  ui_story_5040_50401001_62_dialog_content = "…",
  ui_story_5040_50401001_63_dialog_content = "グォォ！！！",
  ui_story_5040_50401001_64_dialog_content = "また来たよ、正面からだ！",
  ui_story_5040_50401001_65_dialog_content = "スピードと燃え上がる情熱の力を思い知らせてやりましょ。",
  ui_story_5040_50401001_66_dialog_content = "全速前進よ！",
  ui_story_5040_50401001_67_dialog_content = "アハハ、すっごく気持ちいい！",
  ui_story_5040_50401001_68_dialog_content = "も、もうダメ…うっ…！",
  ui_story_5040_50401001_69_dialog_content = "あらあら、この程度で酔っちゃったのぉ？\n砂漠の生活に慣れるまでは、まだまだ時間がかかりそうね。",
  ui_story_5040_50401001_70_dialog_content = "でも、砂漠の鳥は砂漠の風に吹かれてなきゃ、\n自由に空を飛べないのよ。",
  ui_story_5040_50401001_71_dialog_content = "そうね…",
  ui_story_5040_50401001_72_dialog_content = "決めたわ。",
  ui_story_5040_50401001_73_dialog_content = "やっと決心がついた？",
  ui_story_5040_50401001_74_dialog_content = "ええ。アドニス、実はあたし――",
  ui_story_5040_50401001_75_dialog_content = "え…？",
  ui_story_5040_50401001_76_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_5040_50401001_77_dialog_content = "イェリア先輩、暗鬼です！",
  ui_story_5040_50401001_78_dialog_content = "暗鬼が大量にこちらへ向かって来てます！",
  ui_story_5040_50401001_79_dialog_content = "まったく、空気の読めない子たちねぇ。",
  ui_story_5040_50401001_80_dialog_content = "イェリアが爆音あげて車を飛ばしてたからでしょ！\nたぶん音に引き付けられてきたんだ！",
  ui_story_5040_50401001_81_dialog_content = "2人とも、愛の告白はまた後ね。",
  ui_story_5040_50401001_82_dialog_content = "まずはこっちを片づけて、\nその後ゆっくりお昼にしましょ。",
  ui_story_5040_50401001_83_dialog_content = "はぁ…",
  ui_story_5040_50401001_84_dialog_content = "ぼ、僕も手伝います！",
  ui_story_5040_50401002_1_dialog_content = "暗鬼はやっぱり、\n地面に転がってる時の方がかわいらしいわねぇ。",
  ui_story_5040_50401002_2_dialog_content = "グオオォ――",
  ui_story_5040_50401002_3_dialog_content = "怖い…",
  ui_story_5040_50401002_4_dialog_content = "怖くありませんよ。イェリア先輩はあなたに手を出したりは…\nほら、先輩が暗鬼を全部倒してくれました！",
  ui_story_5040_50401002_5_dialog_content = "ちがう…私、イェリア、こわくない…",
  ui_story_5040_50401002_6_dialog_content = "イェリア、いい人。みんなを守ってる…",
  ui_story_5040_50401002_7_dialog_content = "あーあ、暗鬼が暴れたせいで、\n準備してた食材がダメになっちゃったわ。",
  ui_story_5040_50401002_8_dialog_content = "影ノ街風の料理を作ろうと思ってたのに…\nこれじゃ何も作れないわ！",
  ui_story_5040_50401002_9_dialog_content = "あらあら、どうしましょうねぇ？",
  ui_story_5040_50401002_10_dialog_content = "（今、イェリアがアドニスの方をちらっと見た…？）",
  ui_story_5040_50401002_11_dialog_content = "僕に考えがある。",
  ui_story_5040_50401002_12_dialog_content = "えっ？",
  ui_story_5040_50401002_13_dialog_content = "こっちの食材は少し手を入れれば、まだ使えそうだよ。",
  ui_story_5040_50401002_14_dialog_content = "影ノ街風とは行かないけど…\n簡単な煮込み料理ぐらいなら何とかなりそうだ！",
  ui_story_5040_50401002_15_dialog_content = "僕に任せて！",
  ui_story_5040_50401002_16_dialog_content = "（アドニスが飛ぶような速さで調理を始めた…）",
  ui_story_5040_50401002_17_dialog_content = "まずはダメになった部分を取り除いて、\n使える部分だけ残す…",
  ui_story_5040_50401002_18_dialog_content = "それから食べやすい大きさに切って、\n沸騰したお湯の中に入れる…",
  ui_story_5040_50401002_19_dialog_content = "ターラ、そっちのを僕にくれる？",
  ui_story_5040_50401002_20_dialog_content = "はい。",
  ui_story_5040_50401002_21_dialog_content = "ありがとう。それから塩を少し入れて…",
  ui_story_5040_50401002_22_dialog_content = "いい香りだね！",
  ui_story_5040_50401002_23_dialog_content = "はい、ターラ。君の分だよ。\nニンジンは入ってないから安心して。",
  ui_story_5040_50401002_24_dialog_content = "ありがと…",
  ui_story_5040_50401002_25_dialog_content = "私とセーブルの分もお願いします！",
  ui_story_5040_50401002_26_dialog_content = "分かりました。\n待ってください、今よそいますね。",
  ui_story_5040_50401002_27_dialog_content = "はい、みんなの食器を持ってきたわ。",
  ui_story_5040_50401002_28_dialog_content = "うーん、今日の昼ご飯は大満足よ！",
  ui_story_5040_50401002_29_dialog_content = "砂漠で煮込み料理はちょっと暑苦しかったけど、\nおいしかったからよしとするわ！",
  ui_story_5040_50401002_30_dialog_content = "君に喜んでもらえたなら嬉しいよ！",
  ui_story_5040_50401002_31_dialog_content = "洗い物も任せて。",
  ui_story_5040_50401002_32_dialog_content = "分かったわ。じゃあ、あたしは辺りをパトロールしてくる。\nまた暗鬼が出てくるといけないし。",
  ui_story_5040_50401002_33_dialog_content = "あ、ちょっと待って。\nそういえば、さっき何か言おうとしてたよね？",
  ui_story_5040_50401002_34_dialog_content = "暗鬼が出たせいで、忘れるところだったよ。",
  ui_story_5040_50401002_35_dialog_content = "…あれは何でもないの。パトロールに行ってくるわ。",
  ui_story_5040_50401002_36_dialog_content = "私もセーブルと一緒に、\n風景でも見てきます！",
  ui_story_5040_50401002_37_dialog_content = "（妙だな…ターラ、何か隠してるみたいだ）",
  ui_story_5040_50401002_38_dialog_content = "（そういえば、さっきはまだ何も言ってないのに、\nターラが塩を渡してくれた）",
  ui_story_5040_50401002_39_dialog_content = "（もしかして、記憶が戻り始めてる！？）",
  ui_story_5040_50401002_40_dialog_content = "（…そう考えてみると、\nターラの言動はずっと不自然なところがあった…）",
  ui_story_5040_50401002_41_dialog_content = "（さっき口にしかけたこと…\n何かを謝ろうとするような様子だった…）",
  ui_story_5040_50401002_42_dialog_content = "（妙だな…まさか…最初から記憶を失くしてなんていなかった…？）",
  ui_story_5040_50401002_43_dialog_content = "（でも…だとしたら、どうしてそんなことを…）",
  ui_story_5040_50401002_44_dialog_content = "（…記憶喪失になったふりをして、\n僕を北境から連れ出して…勇気を出させるため…？）",
  ui_story_5040_50401002_45_dialog_content = "（…ターラ…分かったよ。\n僕は証明してみせる！絶対に！）",
  ui_story_5040_50401002_46_dialog_content = "アドニス、何か考え事？",
  ui_story_5040_50401002_47_dialog_content = "あ…な、何でもありません！\nPlayerNameさん、何かご用でしたか？",
  ui_story_5040_50401002_48_dialog_content = "手伝おうか？",
  ui_story_5040_50401002_49_dialog_content = "いいえ、大丈夫です。一人で片付けられます。",
  ui_story_5040_50401002_50_dialog_content = "休んでいてください。",
  ui_story_5040_50401002_51_dialog_content = "そう？じゃあ、お言葉に甘えるよ。",
  ui_story_5040_50401002_52_dialog_content = "（…とは言ったものの、1人でやることがない…\nバイスとカレンがいれば話し相手になってくれるのに…）",
  ui_story_5040_50401002_53_dialog_content = "（イェリアも1人みたいだけど、退屈じゃないのかな？）",
  ui_story_5040_50401002_54_dialog_content = "（別に怒ってるわけじゃないよね？ちょっと聞いてみよう）",
  ui_story_5040_50401002_55_dialog_content = "ふぅ、なんだか眠くなってきたわねぇ。\nそれにしても…",
  ui_story_5040_50401002_56_dialog_content = "ターラとアドニス…ふふ、なかなか面白い2人じゃない。",
  ui_story_5040_50401002_57_dialog_content = "イェリア！",
  ui_story_5040_50401002_58_dialog_content = "あら～？空の末裔くんじゃない、どうしたの？",
  ui_story_5040_50401002_59_dialog_content = "まさか、お友達がいなくて、寂しくなっちゃった？",
  ui_story_5040_50401002_60_dialog_content = "ち、違うよ！",
  ui_story_5040_50401002_61_dialog_content = "じゃあ、アタシが一人で\nかわいそうだと思って来てくれたのかしら～？",
  ui_story_5040_50401002_62_dialog_content = "それも違うよ…",
  ui_story_5040_50401002_63_dialog_content = "ただ、聞きたいことがあるんだ。",
  ui_story_5040_50401002_64_dialog_content = "ふ～ん？",
  ui_story_5040_50401002_65_option_content = "何か隠してるよね？",
  ui_story_5040_50401002_66_dialog_content = "どういう意味かしら？",
  ui_story_5040_50401002_67_dialog_content = "朝、昨日はよく寝たって言ってたよね。",
  ui_story_5040_50401002_68_dialog_content = "でも、僕が聞いてた話と違うんだ。",
  ui_story_5040_50401002_69_option_content = "どうして強がってるの？",
  ui_story_5040_50401002_70_dialog_content = "強がってる？\n何がどうしたらそんな話になるのかしら？",
  ui_story_5040_50401002_71_dialog_content = "ゆうべの君はサンドワームを見つけるために、\n言霊にずっと砂漠じゅうを探させてたはずだよね。",
  ui_story_5040_50401002_72_dialog_content = "…",
  ui_story_5040_50401002_73_dialog_content = "だったら、何？",
  ui_story_5040_50401002_74_dialog_content = "無理をしすぎだよ！",
  ui_story_5040_50401002_75_dialog_content = "長時間フルパワーで光力術を使ってたんでしょ。\n今日だって早起きして、さっきまで戦ってた…",
  ui_story_5040_50401002_76_dialog_content = "もう少し自分をいたわって！",
  ui_story_5040_50401002_77_dialog_content = "…だから？",
  ui_story_5040_50401002_78_dialog_content = "僕はただ、ひとりでそんなに無理することはないって言いたいんだ。\nたまには他人に頼ったっていいと思う。",
  ui_story_5040_50401002_79_dialog_content = "誰かに頼らなくたって、\nアタシは一人で十分楽しく砂漠で暮らしていけるわ。",
  ui_story_5040_50401002_80_dialog_content = "サンドワーム探しだってアタシ一人で十分よ。\nクーリエ隊の仕事もおろそかにしてない。砂漠中に手紙を届けられるわ。",
  ui_story_5040_50401002_81_dialog_content = "あなたに能力を疑われる筋合いはないと思うけど？",
  ui_story_5040_50401002_82_dialog_content = "そういうことじゃないよ。",
  ui_story_5040_50401002_83_dialog_content = "僕は空の末裔で、光力術なんて使えないし、\n暗鬼を前にしたら、抵抗する力もない。",
  ui_story_5040_50401002_84_dialog_content = "だからずっと仲間たちに頼って、\n皆のおかげでここまで来られたんだ。",
  ui_story_5040_50401002_85_dialog_content = "僕は自分が弱いからこそ、よく分かってる。\n自分の力だけでこの世界を生きていくなんて無理だよ。",
  ui_story_5040_50401002_86_dialog_content = "ふ～ん？",
  ui_story_5040_50401002_87_dialog_content = "どんなに強くたって、\nいつか必ず自分の力を超える問題にぶつかる時が来る。",
  ui_story_5040_50401002_88_dialog_content = "自分が成長したり、努力したりで\n何とか乗り越えられるものもあるだろうけど…",
  ui_story_5040_50401002_89_dialog_content = "それじゃどうにもならない問題もあるんだ。",
  ui_story_5040_50401002_90_dialog_content = "空の末裔は貧弱な種族だから、\n僕はそんな経験ばかりしてきたよ。",
  ui_story_5040_50401002_91_dialog_content = "他人に頼っても、別に恥じゃないって言いたいの？",
  ui_story_5040_50401002_92_dialog_content = "ふふ…あなた、本当に純粋ねぇ。",
  ui_story_5040_50401002_93_dialog_content = "1回や2回のことならいいけど、\n何度も他人に頼れば、作った借りが重い負担になるわ。",
  ui_story_5040_50401002_94_dialog_content = "それが空を飛ぶ鳥にとって、足かせや鎖になる…\nもう二度と自由に飛び回ることができなくなってしまうの。",
  ui_story_5040_50401002_95_dialog_content = "大勢に借りのあるあなたなら、\nアタシの言ってることも、よく理解できるんじゃない？",
  ui_story_5040_50401002_96_option_content = "分かるよ",
  ui_story_5040_50401002_97_dialog_content = "確かに、誰かに助けてもらうたびに、\n申し訳ない気持ちになる。",
  ui_story_5040_50401002_98_dialog_content = "でしょ？アタシはそういうのがイヤ。\nそもそも、他人とは関わりたくないのよ。",
  ui_story_5040_50401002_99_dialog_content = "一人で自由気ままに生きることの、\n何がいけないのかしら？",
  ui_story_5040_50401002_100_dialog_content = "もちろん、自由に生きられるのはいいことだと思うよ。\n好きなことをやれるし、あれこれ考える必要もない。",
  ui_story_5040_50401002_101_dialog_content = "でも、誰かと関わることは、\n血の通わない、ただの重りじゃないんだ。",
  ui_story_5040_50401002_102_option_content = "分からない",
  ui_story_5040_50401002_103_dialog_content = "僕は確かにたくさんの人に助けてもらってきた。\nでも、それが負担だと感じたことは一度もないよ。",
  ui_story_5040_50401002_104_dialog_content = "…",
  ui_story_5040_50401002_105_dialog_content = "得意不得意は人それぞれ…\nだからこそ、協力してお互いに補完し合うんだよ。",
  ui_story_5040_50401002_106_dialog_content = "僕の仲間は光力術を使えて、僕は光の軌跡が見える。\n協力して戦えば、暗鬼に立ち向かえる。",
  ui_story_5040_50401002_107_dialog_content = "イェリアの過去に何があって、\n人との関わりをそこまで拒むようになったのかは知らないけど…",
  ui_story_5040_50401002_108_dialog_content = "関係って言うのは一方通行じゃないんだ。\n助けたもらったかわりに、僕も力の限り皆を助ける。",
  ui_story_5040_50401002_109_dialog_content = "…",
  ui_story_5040_50401002_110_dialog_content = "へぇ、そんな風に考えてたのね。",
  ui_story_5040_50401002_111_dialog_content = "あなたとお友達も、\nあの2人と同じ関係みたいねぇ。",
  ui_story_5040_50401002_112_dialog_content = "え…！？",
  ui_story_5040_50401002_113_dialog_content = "ち、違うよ、僕たちは普通の友だちで、恋人とかじゃ…",
  ui_story_5040_50401002_114_dialog_content = "あら～？いったい何の話かしら。\nアタシはそんなこと、一言も言ってないわよ。",
  ui_story_5040_50401002_115_dialog_content = "うっ…",
  ui_story_5040_50401002_116_dialog_content = "あの2人もうまく補完し合ってると思わない？",
  ui_story_5040_50401002_117_dialog_content = "戻ったわ。今のところ近くに暗鬼はいないみたい。",
  ui_story_5040_50401002_118_dialog_content = "お疲れ様！はい、水でも飲んで、一息ついて。",
  ui_story_5040_50401002_119_dialog_content = "そうだね…",
  ui_story_5040_50401002_120_dialog_content = "ターラは社交的で明るい。\n厳しい環境で生きることや暗鬼との戦いに慣れてる。",
  ui_story_5040_50401002_121_dialog_content = "アドニスはそれを後ろで支えるような感じだね。\nターラの苦手な細かい作業も地道に続けられる。",
  ui_story_5040_50401002_122_dialog_content = "そうねぇ。R・W出身の女の子と\nうまくやれる男の子がいるなんて意外だったわ。",
  ui_story_5040_50401002_123_dialog_content = "イェリアはR・Wが嫌いなの？",
  ui_story_5040_50401002_124_dialog_content = "嫌い？ふふ…そうかもしれないわねぇ。",
  ui_story_5040_50401002_125_dialog_content = "アタシから見ればあいつらなんて、\n無謀でバカなロクデナシの集まりだもの。",
  ui_story_5040_50401002_126_dialog_content = "楽しむこと以外、何にも興味ない人たち。",
  ui_story_5040_50401002_127_dialog_content = "でも、君が言霊にサンドワームを探させてたことは、\nサメヤマが教えてくれたんだよ。",
  ui_story_5040_50401002_128_dialog_content = "え？",
  ui_story_5040_50401002_129_dialog_content = "きのう君に追い払われた後、サメヤマに連絡したんだ。\nピンクのサンドワームのことを聞こうと思って。",
  ui_story_5040_50401002_130_dialog_content = "君の言霊がサンドワームを探してるのをみんなが見たって言ってた。",
  ui_story_5040_50401002_131_dialog_content = "みんな、君のことを心配してるし、気に掛けてるんだよ。",
  ui_story_5040_50401002_132_dialog_content = "それはアタシがこの砂漠の数少ないクーリエで、\n必要な情報を届けてあげてるからにすぎないわ。",
  ui_story_5040_50401002_133_dialog_content = "そうじゃないよ！",
  ui_story_5040_50401002_134_dialog_content = "さ、休憩はそろそろ終わりにしましょ。",
  ui_story_5040_50401002_135_dialog_content = "ちょっと、イェリア？",
  ui_story_5040_50401002_136_dialog_content = "片づけて、出発するわよ。",
  ui_story_5040_50401002_137_dialog_content = "置いてかれちゃった…",
  ui_story_5040_50401002_138_dialog_content = "イェリアはいつもあんな感じだ。\n逃げたり、強がったりして自分をごまかそうとしてるのかな？",
  ui_story_5040_50401101_1_dialog_content = "どう？片づいた？",
  ui_story_5040_50401101_2_dialog_content = "全部終わりました。いつでも出発できますよ。",
  ui_story_5040_50401101_3_dialog_content = "あたしも準備できたわ。",
  ui_story_5040_50401101_4_dialog_content = "荷物は全部確認しました。何もなくなっていません。\nたき火もしっかり消しましたよ。",
  ui_story_5040_50401101_5_dialog_content = "キア、細かいことまで気が付くね！",
  ui_story_5040_50401101_6_dialog_content = "ありがとうございます。\nそれもこれも、エメラルド先生の教えです。",
  ui_story_5040_50401101_7_dialog_content = "エメラルド先生？",
  ui_story_5040_50401101_8_dialog_content = "クーリエ隊の先輩です。\n今はもう退職されてしまいましたが。",
  ui_story_5040_50401101_9_dialog_content = "私がクーリエになる前は、\nエメラルド先生が故郷のファル村と近くの村を担当してたんです。",
  ui_story_5040_50401101_10_dialog_content = "私の故郷はへんぴな所にありますから、\n外の世界とはほとんど往来がないんです。",
  ui_story_5040_50401101_11_dialog_content = "村の人たちにとって外の世界を知る唯一の方法が、\nエメラルド先生の配達する手紙でした。",
  ui_story_5040_50401101_12_dialog_content = "きっと責任感の強い人だったんだろうね。",
  ui_story_5040_50401101_13_dialog_content = "もちろんです。私はエメラルド先生の背中を見て、\nクーリエになろうと決心したんですから！",
  ui_story_5040_50401101_14_dialog_content = "辺境に住む人たちが外の世界とつながることが\nいかに大変か分かっているからこそ、その橋渡しになりたいと思ったんです。",
  ui_story_5040_50401101_15_dialog_content = "りっぱな考えだね。",
  ui_story_5040_50401101_16_dialog_content = "ふふ、私なんてまだまだです。",
  ui_story_5040_50401101_17_dialog_content = "エメラルド先生からもらったノートがあると言うのに、\nまだまだよくミスをしてしまいますし…",
  ui_story_5040_50401101_18_dialog_content = "ノートに書かれている通りにやっているはずなのに、\n思っていたようにできないことも多いんです。",
  ui_story_5040_50401101_19_dialog_content = "何もかも書いてある通りにやらなくてもいいんじゃないかな。\n臨機応変に対応することも大事だよ。",
  ui_story_5040_50401101_20_dialog_content = "はぁ…臨機応変っていうのは、私の一番苦手なことなんですよね…",
  ui_story_5040_50401101_21_dialog_content = "グアォオオ――",
  ui_story_5040_50401101_22_dialog_content = "…今、遠くで何か聞こえなかった？",
  ui_story_5040_50401101_23_dialog_content = "あれは…",
  ui_story_5040_50401101_24_dialog_content = "グオオ――！！！",
  ui_story_5040_50401101_25_dialog_content = "暗鬼です！皆さん、気を付けてください！",
  ui_story_5040_50401101_26_dialog_content = "どうしてこんなにたくさん！？",
  ui_story_5040_50401101_27_dialog_content = "チッ…いったいどこから湧いてきたの！？",
  ui_story_5040_50401101_28_dialog_content = "また暗鬼が出るなんて、おかしいわね…",
  ui_story_5040_50401101_29_dialog_content = "とにかく、まずは目の前のお邪魔虫を倒しちゃいましょ。\nがんばってね～。",
  ui_story_5040_50401102_1_dialog_content = "グオオォ――",
  ui_story_5040_50401102_2_dialog_content = "何かヘンだね。\nどうしてこんなに早く逃げ出したんだろう？",
  ui_story_5040_50401102_3_dialog_content = "普通なら、ここで暗鬼はそう見ないわ。",
  ui_story_5040_50401102_4_dialog_content = "それが今日は、連続で2つの群れ…\n何かがおかしいわね。",
  ui_story_5040_50401102_5_dialog_content = "暗鬼、逃げてる…",
  ui_story_5040_50401102_6_dialog_content = "え？何か言った？",
  ui_story_5040_50401102_7_dialog_content = "セーブルが暗鬼は何かから逃げてる、\n何かを避けてると言ってます。",
  ui_story_5040_50401102_8_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_5040_50401102_9_dialog_content = "地震…？",
  ui_story_5040_50401102_10_dialog_content = "みんな、散らばって！\n何か来るわ！",
  ui_story_5040_50401102_11_dialog_content = "ターラ、危ない！",
  ui_story_5040_50401102_12_dialog_content = "<color=#e8d9bb>ドカン――！</color>",
  ui_story_5040_50401102_13_dialog_content = "<size=50>グオォ――！！</size>",
  ui_story_5040_50401102_14_dialog_content = "ピ、ピンクのサンドワーム！\n本当に出て来るなんて！？",
  ui_story_5040_50401102_15_dialog_content = "砂漠の奥へ逃げたんじゃなかったの？\nここってまだ、奥っていう程じゃないでしょ？",
  ui_story_5040_50401102_16_dialog_content = "もしかしたら、急いで何かを食べる必要ができたのかしらねぇ。",
  ui_story_5040_50401102_17_dialog_content = "それで、暗鬼を食べようとしてたってこと？",
  ui_story_5040_50401102_18_dialog_content = "そういうこと。\nま、今はアタシたちが食事のメニューみたいね。",
  ui_story_5040_50401102_19_dialog_content = "<size=50>グオ！</size>",
  ui_story_5040_50401102_20_dialog_content = "何をそんなに急いでるのかしらねぇ？",
  ui_story_5040_50401102_21_dialog_content = "<color=#e8d9bb>バキン――！</color>",
  ui_story_5040_50401102_22_dialog_content = "硬い！？",
  ui_story_5040_50401102_23_dialog_content = "ふふ…そのピンクのウロコ、\n見た目ほど可愛いものじゃなさそうねぇ。",
  ui_story_5040_50401102_24_dialog_content = "でも、ウロコがいくら硬くたって、\nしょせんはただのサンドワームよ。",
  ui_story_5040_50401102_25_dialog_content = "行って、言霊！",
  ui_story_5040_50401102_26_dialog_content = "グゥ…",
  ui_story_5040_50401102_27_dialog_content = "すごい、効いてる！",
  ui_story_5040_50401102_28_dialog_content = "あたしも手を貸すわ！",
  ui_story_5040_50401102_29_dialog_content = "ターラ、前に出すぎだ、危ないよ！",
  ui_story_5040_50401102_30_dialog_content = "ダメよ！遠距離じゃ弾丸の威力が半減するわ。\nそれじゃウロコを貫けない。",
  ui_story_5040_50401102_31_dialog_content = "力が強いだけなら、怖がる必要なんてないわ！",
  ui_story_5040_50401102_32_dialog_content = "グゥ…ガァ…！",
  ui_story_5040_50401102_33_dialog_content = "次は――頭！",
  ui_story_5040_50401102_34_dialog_content = "グォォ！",
  ui_story_5040_50401102_35_dialog_content = "え！？",
  ui_story_5040_50401102_36_dialog_content = "銃に噛みつかれた！？\nまさか、銃の方をわざわざ狙った…？",
  ui_story_5040_50401102_37_dialog_content = "放しなさい！",
  ui_story_5040_50401102_38_dialog_content = "サンドワームなのに、思ったより賢いみたいね？\n良くないわ…",
  ui_story_5040_50401102_39_dialog_content = "今のアタシたちじゃ、てこずりそうね…",
  ui_story_5040_50401102_40_dialog_content = "たぶん長期戦に持ち込んで、僕たちの消耗を待つ気だ！",
  ui_story_5040_50401102_41_dialog_content = "そうはいかないわ…幻惑の魔典！\nあなたの力を思い知らせてあげなさい！",
  ui_story_5040_50401102_42_dialog_content = "グォォ――！",
  ui_story_5040_50401102_43_dialog_content = "サンドワームが…消えた！？",
  ui_story_5040_50401102_44_dialog_content = "砂の中よ、足元に気を付けて！",
  ui_story_5040_50401102_45_dialog_content = "<size=50>グォオオ！！！</size>",
  ui_story_5040_50401102_46_dialog_content = "<color=#e8d9bb>バン――ドサッ！</color>",
  ui_story_5040_50401102_47_dialog_content = "あ――！",
  ui_story_5040_50401102_48_dialog_content = "ターラが飛ばされた！",
  ui_story_5040_50401102_49_dialog_content = "ターラ！！",
  ui_story_5040_50401102_50_dialog_content = "大丈夫よ！",
  ui_story_5040_50401102_51_dialog_content = "この辺りの砂は柔らかいの。\nサンドワームが潜り込んで奇襲できるぐらいにね…",
  ui_story_5040_50401102_52_dialog_content = "みんな、車に乗って！",
  ui_story_5040_50401102_53_dialog_content = "手前の岩石砂漠まで退がるわよ！\nあそこなら地面が岩石だから、サンドワームも素早く潜れないわ！",
  ui_story_5040_50401102_54_dialog_content = "分かりました。セーブル、行きましょう！\nまずは車に乗りますよ！",
  ui_story_5040_50401102_55_dialog_content = "アドニス、急いで！",
  ui_story_5040_50401102_56_dialog_content = "分かった…\nターラ、気を付けて！",
  ui_story_5040_50401102_57_dialog_content = "グオ――",
  ui_story_5040_50401102_58_dialog_content = "うっ――！",
  ui_story_5040_50401102_59_dialog_content = "ターラ！",
  ui_story_5040_50401102_60_dialog_content = "うっ…",
  ui_story_5040_50401102_61_dialog_content = "まずい、ターラが足をやられた！",
  ui_story_5040_50401102_62_dialog_content = "グォォ！",
  ui_story_5040_50401102_63_dialog_content = "（ここからじゃ遠すぎる。止める方法が…）",
  ui_story_5040_50401102_64_dialog_content = "ターラから離れろ！汚い虫けらめ！",
  ui_story_5040_50401102_65_dialog_content = "グオ――",
  ui_story_5040_50401102_66_dialog_content = "こっちだ！毛虫め！僕はここだ！",
  ui_story_5040_50401102_67_dialog_content = "サンドワームの注意がアドニスにそれた！？",
  ui_story_5040_50401102_68_dialog_content = "アドニスの攻撃なんて、効くはずは…",
  ui_story_5040_50401102_69_dialog_content = "カレが攻撃したところ、\nまだ治りきってない傷があるわ…",
  ui_story_5040_50401102_70_dialog_content = "そうか、サメヤマが前に負わせた傷口だ！",
  ui_story_5040_50401102_71_dialog_content = "グォォ！",
  ui_story_5040_50401102_72_dialog_content = "うっ…！！！",
  ui_story_5040_50401102_73_dialog_content = "サンドワームの注意がアドニスに向いてる！\nターラから離れた！",
  ui_story_5040_50401102_74_dialog_content = "イェリア、今だよ！",
  ui_story_5040_50401102_75_dialog_content = "分かってるわ。",
  ui_story_5040_50401102_76_dialog_content = "ホーク、行って！狙いはあの傷よ！",
  ui_story_5040_50401102_77_dialog_content = "グ…グォッ！？",
  ui_story_5040_50401102_78_dialog_content = "今のうちです！",
  ui_story_5040_50401102_79_dialog_content = "ターラさん、大丈夫ですか！？",
  ui_story_5040_50401102_80_dialog_content = "あたしは大丈夫。早くアドニスを！",
  ui_story_5040_50401102_81_dialog_content = "分かりました！",
  ui_story_5040_50401102_82_dialog_content = "私も…手伝う！",
  ui_story_5040_50401102_83_dialog_content = "<color=#e8d9bb>ビュンッ！</color>",
  ui_story_5040_50401102_84_dialog_content = "グォォ！！！",
  ui_story_5040_50401102_85_dialog_content = "た、助かった…！",
  ui_story_5040_50401102_86_dialog_content = "後ろに隠れてください！\n巻き込まれないように気を付けてくださいよ！",
  ui_story_5040_50401102_87_dialog_content = "グォォ！",
  ui_story_5040_50401102_88_dialog_content = "<color=#e8d9bb>ゴウッ！</color>",
  ui_story_5040_50401102_89_dialog_content = "きゃあ！？どうして急に砂嵐が！？",
  ui_story_5040_50401102_90_dialog_content = "砂嵐じゃないわ。\nサンドワームが砂を巻き上げたのよ。",
  ui_story_5040_50401102_91_dialog_content = "アタシたちの視界を奪って、\n弱点を隠そうとしてるんだわ。",
  ui_story_5040_50401102_92_dialog_content = "まずい…キアたちを見失った！",
  ui_story_5040_50401102_93_dialog_content = "ターラ！どこだ！？",
  ui_story_5040_50401102_94_dialog_content = "アドニス！ここよ！",
  ui_story_5040_50401102_95_dialog_content = "私たちもすぐ行きます！",
  ui_story_5040_50401102_96_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5040_50401102_97_dialog_content = "あっ！！",
  ui_story_5040_50401102_98_dialog_content = "アドニス！？",
  ui_story_5040_50401102_99_dialog_content = "連れ戻してくるわ！",
  ui_story_5040_50401102_100_dialog_content = "<size=50>グオォ――！！</size>",
  ui_story_5040_50401102_101_dialog_content = "うっ！",
  ui_story_5040_50401102_102_dialog_content = "イェリア、サンドワームが逃げそうだ！",
  ui_story_5040_50401102_103_dialog_content = "逃がさないわよ！",
  ui_story_5040_50401102_104_dialog_content = "<size=50>グォオオ！！！</size>",
  ui_story_5040_50401102_105_dialog_content = "うっ！！",
  ui_story_5040_50401102_106_dialog_content = "PlayerName！？",
  ui_story_5040_50401102_107_dialog_content = "うう…",
  ui_story_5040_50401201_1_dialog_content = "PlayerName、しっかりしなさい！",
  ui_story_5040_50401201_2_dialog_content = "うう、イテテ！",
  ui_story_5040_50401201_3_dialog_content = "ペッペッ！口の中が砂だらけだ！",
  ui_story_5040_50401201_4_dialog_content = "ふぅ、無事ならよかったわ。\nケガはない？",
  ui_story_5040_50401201_5_dialog_content = "ゴホゴホ…大丈夫だよ。\n頭のてっぺんが痛むぐらい、たぶん大したことないよ。",
  ui_story_5040_50401201_6_dialog_content = "サンドワームに飛ばされて、\n頭から砂の中に突っ込んだから、もうダメかと思ったわ。",
  ui_story_5040_50401201_7_dialog_content = "アタシとターラでなんとか砂の中から引っ張り出したのよ。\n感謝してよね～、空の末裔くん？",
  ui_story_5040_50401201_8_dialog_content = "ありがとう…",
  ui_story_5040_50401201_9_dialog_content = "他の皆は？無事？",
  ui_story_5040_50401201_10_dialog_content = "足だけ出てるあなたが見えたから、\nとりあえず先に助けたの。",
  ui_story_5040_50401201_11_dialog_content = "とんでもない勢いの砂だったわ。\nサンドワームどころか、アドニスたちともはぐれたのよ。",
  ui_story_5040_50401201_12_dialog_content = "感知能力で探してみるよ！",
  ui_story_5040_50401201_13_option_content = "感知！",
  ui_story_5040_50401201_14_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5040_50401201_15_dialog_content = "近くにアドニスたちの気配がない…",
  ui_story_5040_50401201_16_dialog_content = "大丈夫よ。言霊たちが探してるわ。\n予想通りなら、すぐに知らせがくるはずよ。",
  ui_story_5040_50401201_17_dialog_content = "砂に埋もれてようと、\nホークなら地表のわずかな動きを察知できるわ。",
  ui_story_5040_50401201_18_dialog_content = "アドニス、絶対無事でいてよ…！",
  ui_story_5040_50401201_19_dialog_content = "ピュー！",
  ui_story_5040_50401201_20_dialog_content = "帰ってきたわ。",
  ui_story_5040_50401201_21_dialog_content = "どう？見つかった？",
  ui_story_5040_50401201_22_dialog_content = "ピュー…",
  ui_story_5040_50401201_23_dialog_content = "…なんですって？近くに見当たらない？",
  ui_story_5040_50401201_24_dialog_content = "捜索範囲を広げて。\n光力の消耗は気にしなくていいわ。",
  ui_story_5040_50401201_25_dialog_content = "行きなさい！",
  ui_story_5040_50401201_26_dialog_content = "ピュー！",
  ui_story_5040_50401201_27_dialog_content = "あたしも近くを探してみる。",
  ui_story_5040_50401201_28_dialog_content = "ダメだよ、足をケガしてるでしょ！",
  ui_story_5040_50401201_29_dialog_content = "でも、じっとしてなんていられないわ！",
  ui_story_5040_50401201_30_dialog_content = "やみくもに動いても力をムダづかいするだけよ。\nホークに見つけられないものが、あなたの目で見つけられるはずないわ。",
  ui_story_5040_50401201_31_dialog_content = "だから、ここで休んでなさい。\n傷が悪化したら大変よ。",
  ui_story_5040_50401201_32_dialog_content = "…",
  ui_story_5040_50401201_33_dialog_content = "あたしが記憶喪失のフリなんてしなければ、\nアドニスも危険な目に遭わずにすんだのよね…？",
  ui_story_5040_50401201_34_dialog_content = "実は…君が記憶喪失のフリしてるってこと、\nだいぶ前から感知能力で気づいてたんだ。",
  ui_story_5040_50401201_35_dialog_content = "あの時はきっと事情があるんだと思って、\n何も言わずにいたけど…",
  ui_story_5040_50401201_36_dialog_content = "ええ…",
  ui_story_5040_50401201_37_dialog_content = "今思えば、あの時放っておかなければ、\nこんな危険なことにはならなかったのかもしれない。",
  ui_story_5040_50401201_38_dialog_content = "どうしてそんなことを…\nいったい何がしたいの！？",
  ui_story_5040_50401201_39_dialog_content = "こうすれば、アドニスが外の世界への\n恐怖を克服できるかもって思ったのよ。",
  ui_story_5040_50401201_40_dialog_content = "アドニスはずっと北境を離れるのを怖がってた。\nだから、ちょっと強引に背中を押そうと思ったの。",
  ui_story_5040_50401201_41_option_content = "だとしても、やりすぎだよ！",
  ui_story_5040_50401201_42_dialog_content = "僕が巻き込まれたことは置いとくとしても…\nアドニスは君にとって大事な人でしょ？",
  ui_story_5040_50401201_43_dialog_content = "どんな理由であろうと、\n危険の中に放り込もうとするのはおかしいよ！",
  ui_story_5040_50401201_44_dialog_content = "今はキアとセーブルも行方が分からないし…\nそのせいで何人もの命が危険にさらされてるんだ！",
  ui_story_5040_50401201_45_dialog_content = "ごめんなさい…",
  ui_story_5040_50401201_46_option_content = "気持ちは分かるよ",
  ui_story_5040_50401201_47_dialog_content = "時どき、僕も自分で勇気が出せなくて、\n誰かに背中を押してほしいって思うことがあるんだ。",
  ui_story_5040_50401201_48_dialog_content = "気持ちは分かるよ。でも…こんなやり方は良くない。",
  ui_story_5040_50401201_49_dialog_content = "問題に向き合う勇気のない友だちがいたなら、\nするべき事はそばに寄り添ってあげること…",
  ui_story_5040_50401201_50_dialog_content = "自分の行動と言葉ではげまして、\n一緒に困難と向き合うのが一番いいんだ。",
  ui_story_5040_50401201_51_dialog_content = "何もかもあたしがいけないの…\nあたしの考えが甘かったのよ…",
  ui_story_5040_50401201_52_dialog_content = "あのサンドワームは見た目が変わってること以外、\n普通のと変わらないって思ってたから…",
  ui_story_5040_50401201_53_dialog_content = "普通のサンドワームなら何回も倒したことがあったから、\nアドニスを守ることくらい、あたし一人で十分だって思ってたの…",
  ui_story_5040_50401201_54_dialog_content = "でも、アイツが…あんなにずる賢くて、\n強いとは思わなかった…",
  ui_story_5040_50401201_55_dialog_content = "アタシにも責任があるわ。",
  ui_story_5040_50401201_56_dialog_content = "あれだけ目立つ色で、この砂漠を生き抜いてるんだもの。\n「タダモノじゃない」って気付くべきだったわ。",
  ui_story_5040_50401201_57_dialog_content = "…あたしのわがままのせいで、みんなを危険にさらしたわ。\n責任はとるわ、何をしてでも埋め合わせする…",
  ui_story_5040_50401201_58_dialog_content = "…とにかく、まずはアドニスたちを見つけないと。",
  ui_story_5040_50401201_59_dialog_content = "無事を祈るしかないわ…",
  ui_story_5040_50401201_60_dialog_content = "（キアたちは楽観できるような状況じゃない…）",
  ui_story_5040_50401201_61_dialog_content = "（万が一イェリアの言霊でも見つけられなかったら、\nどうすればいいんだろう…）",
  ui_story_5040_50401201_62_dialog_content = "ホークが帰ってきたわ。",
  ui_story_5040_50401201_63_dialog_content = "え？どこ？",
  ui_story_5040_50401201_64_dialog_content = "こっちよ！",
  ui_story_5040_50401201_65_dialog_content = "ピュウ――！",
  ui_story_5040_50401201_66_dialog_content = "グォォ…",
  ui_story_5040_50401201_67_dialog_content = "あら？おまけがついて来たみたいね…",
  ui_story_5040_50401201_68_dialog_content = "まずは暗鬼を倒そう！",
  ui_story_5040_50401201_69_dialog_content = "あたしも戦うわ。足のケガくらい…\n砂漠育ちだもの、大したことじゃないわ！",
  ui_story_5040_50401202_1_dialog_content = "ゲホ、ゲホ…",
  ui_story_5040_50401202_2_dialog_content = "はぁ…けっこうキツイわ。",
  ui_story_5040_50401202_3_dialog_content = "こいつらもサンドワームから逃げてきたのかしら？",
  ui_story_5040_50401202_4_dialog_content = "いや、あわてた様子はなかったし、\nたぶん逃げて来たんじゃないよ…",
  ui_story_5040_50401202_5_dialog_content = "おおかた、ホークが大量に光力をまき散らしながら飛び回ってるのを見て、\n今が襲い時とでも思ったんでしょ。",
  ui_story_5040_50401202_6_dialog_content = "で、何か見つかった？",
  ui_story_5040_50401202_7_dialog_content = "ピュウッ！",
  ui_story_5040_50401202_8_dialog_content = "見つからなかった…？",
  ui_story_5040_50401202_9_dialog_content = "近くにサンドワームの痕跡がないってことは、\nきっと地下のトンネルを通って逃げたのね。",
  ui_story_5040_50401202_10_dialog_content = "そうだとしたら、アドニスとキアたちも\nサンドワームに地下まで巻きこまれたかもしれないわ…",
  ui_story_5040_50401202_11_dialog_content = "そんな！だったら相当まずいじゃない！？",
  ui_story_5040_50401202_12_dialog_content = "あのサンドワームはアドニスたちだけじゃ倒せないわ。\nサンドワームのトンネルなんて複雑だし、迷うに決まってる。",
  ui_story_5040_50401202_13_dialog_content = "急いで探さなきゃ！",
  ui_story_5040_50401202_14_dialog_content = "心配しないで。\nホークに砂漠全体を捜索させるわ。",
  ui_story_5040_50401202_15_dialog_content = "ホー…ゴホゴホッ、ホーク！",
  ui_story_5040_50401202_16_dialog_content = "イェリア、ダメだ！",
  ui_story_5040_50401202_17_dialog_content = "ずいぶん顔色が悪い、これ以上は倒れちゃうよ！",
  ui_story_5040_50401202_18_dialog_content = "ふふ…空の末裔くん、見くびってもらっちゃ困るわね。\nアタシ、そんなにヤワじゃないの。",
  ui_story_5040_50401202_19_dialog_content = "長い間、どんなに大変なことも、\n一人で乗り越えてきたんだから。",
  ui_story_5040_50401202_20_dialog_content = "今度も必ず…",
  ui_story_5040_50401202_21_dialog_content = "R・Wに助けてもらおう。",
  ui_story_5040_50401202_22_dialog_content = "え？",
  ui_story_5040_50401202_23_dialog_content = "ソラヴァンに戻って、通信機でサメヤマたちに連絡しよう。\nR・Wに助けてもらうんだ。",
  ui_story_5040_50401202_24_dialog_content = "1人で見つけられなくても、\n砂漠にいるみんなが一緒に探せば、きっと見つけられるよ。",
  ui_story_5040_50401202_25_dialog_content = "イェリア、クーリエ隊のエルダーなんでしょ。\n君が頼めば、きっと手伝ってくれるよ。",
  ui_story_5040_50401202_26_dialog_content = "アタシが？ふん、空の末裔くんって単純ねぇ…",
  ui_story_5040_50401202_27_dialog_content = "アタシはいつだって仕事は仕事としてやってきた。\n貸しを作ったことも、借りも作ったこともないの。",
  ui_story_5040_50401202_28_dialog_content = "こんな態度の悪いクーリエより、\nもっと責任感のある人が来た方が、みんな喜ぶんじゃないかしら？",
  ui_story_5040_50401202_29_dialog_content = "あなたはそんなに軽い存在じゃないわ！",
  ui_story_5040_50401202_30_dialog_content = "この砂漠に生きる人にとって、\nクーリエはみんなを結ぶ大切な橋渡し役なの。",
  ui_story_5040_50401202_31_dialog_content = "あたしとアドニスだって、\nクーリエ隊のおかげで連絡を取り合うことができたのよ。",
  ui_story_5040_50401202_32_dialog_content = "そうだよ。人と人との関係って、\n上っ面で語れることじゃない。",
  ui_story_5040_50401202_33_dialog_content = "皆のために手紙を届け、送り続けてきた。\nそれだけでもう、皆と深い絆でつながってるんだ。",
  ui_story_5040_50401202_34_dialog_content = "…",
  ui_story_5040_50401202_35_dialog_content = "まったく…あなたにはかなわないわねぇ。",
  ui_story_5040_50401202_36_dialog_content = "じゃあ、空の末裔くんの言う通り、\n助けを求めてみましょ。",
  ui_story_5040_50401202_37_dialog_content = "…助けてほしい時だけ他人を思い出すような人に、\nR・Wが協力してくれるなんて、アタシは思えないけど。",
  ui_story_5040_50401202_38_dialog_content = "試してみなきゃ分からないよ。",
  ui_story_5040_50401202_39_dialog_content = "とにかく、急いでソラヴァンに戻ろう！",
  ui_story_5040_50401202_40_dialog_content = "そうあわてないで。\nあなたの通信機より早く連絡を取れる方法があるわ。",
  ui_story_5040_50401202_41_dialog_content = "えっ？",
  ui_story_5040_50401202_42_dialog_content = "消耗が激しい術だから、\n一度使えば当分は力を蓄え直さないといけないけど…",
  ui_story_5040_50401202_43_dialog_content = "今以上の使い時は無いわ。",
  ui_story_5040_50401202_44_dialog_content = "え？まだ切り札を隠してたの？",
  ui_story_5040_50401202_45_dialog_content = "切り札ってほどじゃないわ。",
  ui_story_5040_50401202_46_dialog_content = "いつでもクーリエたちと連絡が取れるように、\n万一の備えを用意してあるってだけ。",
  ui_story_5040_50401202_47_dialog_content = "この力を使えば、ホークを通じて小鳥ちゃんたちに動いてもらえるわ。\n近くにいるR・Wの人たちに、すぐ伝言が伝わるでしょう。",
  ui_story_5040_50401202_48_dialog_content = "今まで使ったことは？",
  ui_story_5040_50401202_49_dialog_content = "ないわねぇ。\n今日が初めてよ。",
  ui_story_5040_50401202_50_dialog_content = "さあ、みんな…\nアタシの伝言を近くの人たちに伝えてちょうだい…",
  ui_story_5040_50401202_51_dialog_content = "ピュウ！",
  ui_story_5040_50401202_52_dialog_content = "行って！",
  ui_story_5040_50401202_53_dialog_content = "ピュウ――！",
  ui_story_5040_50401202_54_dialog_content = "きれいな小鳥ちゃんたち…\nどうかいい知らせを持ってきて…",
  ui_story_5040_50401202_55_dialog_content = "<color=#e8d9bb>10数分後</color>",
  ui_story_5040_50401202_56_dialog_content = "まだ返事はないの…？",
  ui_story_5040_50401202_57_dialog_content = "伝言だって、一瞬とは行かないわよ。",
  ui_story_5040_50401202_58_dialog_content = "あ、戻って来た！",
  ui_story_5040_50401202_59_dialog_content = "ほんとだわ！イェリアのホーク！",
  ui_story_5040_50401202_60_dialog_content = "ピュウ――！",
  ui_story_5040_50401202_61_dialog_content = "足に何かつかんでる…\nうわっ、こっちに落とした！？",
  ui_story_5040_50401202_62_dialog_content = "これは…手紙？",
  ui_story_5040_50401202_63_dialog_content = "ほんとだわ、手紙よ！\n手紙が雪みたいに空から降ってくる…",
  ui_story_5040_50401202_64_dialog_content = "たくさんあるね。メモ書きもあるみたいだよ？",
  ui_story_5040_50401202_65_dialog_content = "うわっ、これ何？\nどうしてイタズラ書きが…",
  ui_story_5040_50401202_66_dialog_content = "見せて…",
  ui_story_5040_50401202_67_dialog_content = "ああ、これはR・W式の連絡方法よ。\n砂漠の西北部では人らしい影もサンドワームも見なかった、ってことね。",
  ui_story_5040_50401202_68_dialog_content = "R・Wの全員が読み書きできるわけじゃないから…\n絵で連絡する時もあるのよ。",
  ui_story_5040_50401202_69_dialog_content = "本当に返事が来たようね…",
  ui_story_5040_50401202_70_dialog_content = "ピュウ！",
  ui_story_5040_50401202_71_dialog_content = "ピンクのサンドワームの目撃情報もあったの？",
  ui_story_5040_50401202_72_dialog_content = "ということは…それをたどってピンクのサンドワームを見つければ、\n巻き込まれたアドニスたちも見つかる可能性が高いってことだね！？",
  ui_story_5040_50401202_73_dialog_content = "ええ…",
  ui_story_5040_50401202_74_dialog_content = "だったら、すぐに見てみましょ！",
  ui_story_5040_50401202_75_dialog_content = "しっぽ街付近は目撃情報ナシ、赤眼谷付近もナシ。",
  ui_story_5040_50401202_76_dialog_content = "啓光寄りの地帯でも目撃情報はナシ…あら？",
  ui_story_5040_50401202_77_dialog_content = "あったわ。",
  ui_story_5040_50401202_78_dialog_content = "どこ！？",
  ui_story_5040_50401202_79_dialog_content = "南の端よ、砂漠の奥地のオアシス。",
  ui_story_5040_50401202_80_dialog_content = "確かにあそこはもともとサンドワームの活動範囲ね。\n時どきR・Wの人たちがサンドワーム狩りに行くところよ。",
  ui_story_5040_50401202_81_dialog_content = "ついさっき、ピンクのサンドワームが\n地下から飛び出してくるところを見たそうね。",
  ui_story_5040_50401202_82_dialog_content = "じゃあ、急いで行きましょ！\nアドニスたちの居場所も分かるかもしれないわ！",
  ui_story_5040_50401202_83_dialog_content = "車に乗って！",
  ui_story_5040_50401202_84_dialog_content = "<color=#e8d9bb>ブォン――</color>",
  ui_story_5040_50401202_85_dialog_content = "うわ！！",
  ui_story_5040_50401202_86_dialog_content = "イ、イェリア、スピード落として！",
  ui_story_5040_50401202_87_dialog_content = "<size=45>空の末裔く～ん！</size>",
  ui_story_5040_50401202_88_dialog_content = "<size=45>何か言ったかしら～？</size>",
  ui_story_5040_50401202_89_option_content = "スピード、落として！",
  ui_story_5040_50401202_90_dialog_content = "何言ってるの！今は「一刻を争う」のよ！",
  ui_story_5040_50401202_91_option_content = "スピード違反だよ！",
  ui_story_5040_50401202_92_dialog_content = "アハハ、空の末裔くん、\nユーモアのセンスが有るわね。",
  ui_story_5040_50401202_93_dialog_content = "砂漠に制限速度なんてないわ！",
  ui_story_5040_50401202_94_dialog_content = "グォォ――！",
  ui_story_5040_50401202_95_dialog_content = "暗鬼が追ってきてる！",
  ui_story_5040_50401202_96_dialog_content = "振り切るわよ！",
  ui_story_5040_50401202_97_dialog_content = "吹き飛ばされないように、しっかりつかまってなさい！",
  ui_story_5040_50401202_98_dialog_content = "<color=#e8d9bb>ブオン――！！！</color>",
  ui_story_5040_50401301_1_dialog_content = "<color=#e8d9bb>キーッ！</color>",
  ui_story_5040_50401301_2_dialog_content = "うわ――！",
  ui_story_5040_50401301_3_dialog_content = "イェリア！みごとなドリフトね！",
  ui_story_5040_50401301_4_dialog_content = "R・Wでも一、二を争うドラテクだわ！",
  ui_story_5040_50401301_5_dialog_content = "そう？ほめ言葉として受け取っておくわぁ。",
  ui_story_5040_50401301_6_dialog_content = "暗鬼はもう振り切れたみたいだよ。\n姿も見えない。",
  ui_story_5040_50401301_7_dialog_content = "それなら、さっきみたいな走り方をする必要はもうないわね。",
  ui_story_5040_50401301_8_dialog_content = "ふぅ…やっと終わった…",
  ui_story_5040_50401301_9_dialog_content = "そろそろじゃない？",
  ui_story_5040_50401301_10_dialog_content = "もう少しよ。",
  ui_story_5040_50401301_11_dialog_content = "砂丘ばっかりの砂漠じゃどこも似たような景色だから、\n距離感や方向感覚がマヒしやすいの。",
  ui_story_5040_50401301_12_dialog_content = "ま、あなたがいるから安心ね。",
  ui_story_5040_50401301_13_dialog_content = "前にも誰かが似たようなことを言ってたっけ…？",
  ui_story_5040_50401301_14_dialog_content = "心配するな、安心して付いていけばいいと思うぜ。",
  ui_story_5040_50401301_15_dialog_content = "昨日までは少し疑ってたけど、\n今はイェリアのこと、僕も信じてるよ。",
  ui_story_5040_50401301_16_dialog_content = "サメヤマに連絡した時、言われてたんだ。\n安心して君に付いていけばいいって。",
  ui_story_5040_50401301_17_dialog_content = "そんなことを言われたの？",
  ui_story_5040_50401301_18_dialog_content = "当たり前じゃない。\nR・Wのみんなはイェリアに感謝してるし、信頼してるのよ。",
  ui_story_5040_50401301_19_dialog_content = "あなたがR・Wの悪口ばかり言ってるのは、\n個人的に言いたいこともあるけどね。",
  ui_story_5040_50401301_20_dialog_content = "そう…ふふ、ありがと。",
  ui_story_5040_50401301_21_dialog_content = "そうだわ、空の末裔くん。\n昨日はごめんなさい。",
  ui_story_5040_50401301_22_dialog_content = "え？どうして急に謝るの？",
  ui_story_5040_50401301_23_dialog_content = "きのう助けを呼ぼうかって聞かれた時、\nずいぶんひどい態度で追い返しちゃったでしょ？",
  ui_story_5040_50401301_24_dialog_content = "ああ、そのこと？\n僕は全然気にしてないよ。",
  ui_story_5040_50401301_25_dialog_content = "でも、分からないな。\nどうしてそんなにR・Wが嫌いなの？",
  ui_story_5040_50401301_26_dialog_content = "そうよ。イェリアだって砂漠出身でしょ。\nR・Wとは長い付き合いなんじゃないの？",
  ui_story_5040_50401301_27_dialog_content = "まさか、どこかの命知らずがお頭の命令を無視して、\nあなたの村を襲ったとか？",
  ui_story_5040_50401301_28_dialog_content = "いいえ…むしろ、その反対よ。\n両親は2人ともR・Wのメンバーだし、あたしも昔はそうだった。",
  ui_story_5040_50401301_29_dialog_content = "でも、ずいぶん昔に両方と縁を切ったの。",
  ui_story_5040_50401301_30_dialog_content = "どうして？",
  ui_story_5040_50401301_31_dialog_content = "あら？空の末裔くんって、\n誰に対しても聞きたがり屋さんなのかしらぁ？",
  ui_story_5040_50401301_32_dialog_content = "ご、ごめん！言いたくないならいいんだ…",
  ui_story_5040_50401301_33_dialog_content = "ふふ、からかいがいがあるわねぇ。",
  ui_story_5040_50401301_34_dialog_content = "別に秘密にしてるわけじゃないわ。\n単にR・Wとは合わないってだけのことよ。",
  ui_story_5040_50401301_35_dialog_content = "両親はR・Wのメンバーだったから、\n他の大勢と同じで自由気ままに生きてたわ。",
  ui_story_5040_50401301_36_dialog_content = "物心ついた頃からほとんど構ってもらった記憶がないし、\n2人から教えてもらったのは砂漠で生きていくための知識だけ。",
  ui_story_5040_50401301_37_dialog_content = "それ以外の時は、ずっと一人だったのよ。",
  ui_story_5040_50401301_38_dialog_content = "ずっと1人？",
  ui_story_5040_50401301_39_dialog_content = "想像できない？",
  ui_story_5040_50401301_40_option_content = "想像できない",
  ui_story_5040_50401301_41_dialog_content = "…僕も地下で長い間暮らしてたけど、\nその時がソラヴァンがずっとそばにいてくれたから…",
  ui_story_5040_50401301_42_dialog_content = "退屈な日々だったけど、孤独ではなかった。",
  ui_story_5040_50401301_43_dialog_content = "僕には想像もできないよ。",
  ui_story_5040_50401301_44_dialog_content = "うらやましい人生だわ。",
  ui_story_5040_50401301_45_dialog_content = "きっと、ソラヴァンはあなたを守ってくれてたんでしょ？",
  ui_story_5040_50401301_46_dialog_content = "そうだよ。ソラヴァンは大切な家族なんだ。",
  ui_story_5040_50401301_47_option_content = "想像できる",
  ui_story_5040_50401301_48_dialog_content = "地下に閉じ込められてた17年間、\n僕のそばにはソラヴァンしかいなかったんだ。",
  ui_story_5040_50401301_49_dialog_content = "ソラヴァンが僕の先生で、家族でもあるんだ。",
  ui_story_5040_50401301_50_dialog_content = "ソラヴァンがいてくれなかったら、\n今の僕はいなかったよ。",
  ui_story_5040_50401301_51_dialog_content = "ソラヴァンはいい先生だったみたいね。",
  ui_story_5040_50401301_52_dialog_content = "そうだよ！",
  ui_story_5040_50401301_53_dialog_content = "あなたはラッキーね。\nでも、すべての人がそうとは限らないの。",
  ui_story_5040_50401301_54_dialog_content = "砂漠は広いわ。\n人同士の距離を、この砂の海と同じくらい遠くしてしまうの。",
  ui_story_5040_50401301_55_dialog_content = "両親はこういう環境での生活に慣れていたから、\n当然アタシも一人で生きていけるって思ったんでしょうね。",
  ui_story_5040_50401301_56_dialog_content = "小さい頃から、ほとんどアタシには構わず、\n自分たちの好きなように生きてたわ。",
  ui_story_5040_50401301_57_dialog_content = "確かに、R・Wには時どきそういう人がいるわね…",
  ui_story_5040_50401301_58_dialog_content = "あの2人は熱い人たちだったって言うのかしら。\nでも、アタシが無事に大きくなれたのは、他のみんなが面倒を見てくれたおかげ。",
  ui_story_5040_50401301_59_dialog_content = "R・Wの皆はよくしてくれたけど、\nそれでもアタシは、親に大切にされてる子たちがうらやましかった。",
  ui_story_5040_50401301_60_dialog_content = "親に守られて、何の心配もなく\n笑ったり泣いたりできる子どもたちがうらやましかった…",
  ui_story_5040_50401301_61_dialog_content = "大勢に囲まれて暮らすのはにぎやかではあったけど、\nいつも誰かと一緒じゃないといけないから、自分だけの時間や居場所がなかったわ。",
  ui_story_5040_50401301_62_dialog_content = "R・Wってにぎやかだし、うるさすぎるのよ。\nでも、アタシは一人の静かな場所が欲しかった。",
  ui_story_5040_50401301_63_dialog_content = "だから、アタシは両親ともR・Wとも縁を切ったの。\nその時から、アタシはもうあの人たちの仲間じゃない。",
  ui_story_5040_50401301_64_dialog_content = "アタシはただ、どこにも属さず、誰とも付き合わず、\n自由な鳥になりたいだけ。",
  ui_story_5040_50401301_65_dialog_content = "クーリエ隊の仕事だって、\nただ生きていくためにやってることよ。",
  ui_story_5040_50401301_66_dialog_content = "…ほんとにそう？",
  ui_story_5040_50401301_67_dialog_content = "初めてあなたの部屋に入った時は、\nアクセサリーやインテリアがいっぱいあってびっくりしたわ。",
  ui_story_5040_50401301_68_dialog_content = "そこら中に放り出されてて、ろくに整理もしてないみたいだし、\nホコリをかぶってるのもあった。",
  ui_story_5040_50401301_69_dialog_content = "全部アタシの大切な仲間なの。あげないわよ～？",
  ui_story_5040_50401301_70_dialog_content = "別に欲しいわけじゃないわ。\nそれに、あたしは他人のものを何でも欲しがるほどいやしい性格じゃないの！",
  ui_story_5040_50401301_71_dialog_content = "あたしが言いたいのは…あれ、確かに大切なものなんだろうけど、\n実はそんなに気に掛けてないんでしょ？",
  ui_story_5040_50401301_72_dialog_content = "…",
  ui_story_5040_50401301_73_dialog_content = "あなたはただR・Wらしくない物を集めて、\n自分はR・Wじゃないって証にしたいだけなんじゃない？",
  ui_story_5040_50401301_74_dialog_content = "でも、きっとあなた自身も分かってないのよ。\nR・Wを離れて、いったいどこに自分の居場所があるのか。",
  ui_story_5040_50401301_75_dialog_content = "（確かに、イェリアが部屋を華やかに飾ってたのは…）",
  ui_story_5040_50401301_76_dialog_content = "（心の空白を埋めようとしてたって事かも知れない）",
  ui_story_5040_50401301_77_dialog_content = "じゃ、あなたの思うアタシってどんな光霊？",
  ui_story_5040_50401301_78_dialog_content = "いつも強がって底知れない態度だけど、\n結局のところ、愛することが怖いんじゃないかしら。",
  ui_story_5040_50401301_79_dialog_content = "愛されることも、愛することも拒んでる。",
  ui_story_5040_50401301_80_dialog_content = "あなたは愛が何かも知らず、愛情を受けたこともない光霊が、\n他人を愛せると思ってるの？",
  ui_story_5040_50401301_81_dialog_content = "そういう意味じゃ…",
  ui_story_5040_50401301_82_dialog_content = "ねぇ…イェリア、\nそんな自虐的になることはないんじゃないかな？",
  ui_story_5040_50401301_83_dialog_content = "自虐的？",
  ui_story_5040_50401301_84_dialog_content = "僕はイェリアが愛がどういうものか知らないとは思えないよ。",
  ui_story_5040_50401301_85_dialog_content = "口ではそう言ってるけど、\n今回もターラとアドニスをちゃんと助けてるでしょ。",
  ui_story_5040_50401301_86_dialog_content = "白夜城では切手の売り方を\n親切に教えてあげてたし…",
  ui_story_5040_50401301_87_dialog_content = "それが巡り巡って、\n2人は記憶喪失を治せるかもしれない人を紹介してもらえた。",
  ui_story_5040_50401301_88_dialog_content = "ターラの記憶喪失は最初からウソだったけど、\n君がずっと2人を助けてたのは確かでしょ。",
  ui_story_5040_50401301_89_dialog_content = "それもこれも、本当は君だってターラとアドニスが\nこのままケンカ別れするのを見たくないからだよね？",
  ui_story_5040_50401301_90_dialog_content = "…",
  ui_story_5040_50401301_91_dialog_content = "アタシはただ、アストラ大陸の広さにも負けずに\n一緒になろうって決心した2人が珍しいと思っただけよ。",
  ui_story_5040_50401301_92_dialog_content = "それって空を飛ぶトリが\n土の中に住んでるウサギと恋に落ちるくらい、不思議なことでしょう？",
  ui_story_5040_50401301_93_dialog_content = "そんなカップルめったにいないもの。\n2人がどうなるのか、気になったから付いてきたまでのことよ。",
  ui_story_5040_50401301_94_dialog_content = "それだったら、ただ見てるだけで助ける必要はないでしょ？",
  ui_story_5040_50401301_95_dialog_content = "でも、イェリアはそうじゃなかった。\n仮に自分で認めたくなくても、ずっと2人を助けてきたのは事実だよ。",
  ui_story_5040_50401301_96_dialog_content = "昔は誰からも愛されてなかったとしても、\nイェリアは強くてまじめなんだから、大事に思ってくれる人はできるはずだよ。",
  ui_story_5040_50401301_97_dialog_content = "…そうかしら…",
  ui_story_5040_50401301_98_dialog_content = "アタシはただ機械的に仕事をこなしてるだけで、\nどこにでもいるクーリエよ。",
  ui_story_5040_50401301_99_dialog_content = "自分のことを軽く見るものじゃないよ。",
  ui_story_5040_50401301_100_dialog_content = "君はクーリエで、それは砂漠に暮らす人たちにとって、\nなくてはならない存在なんだ。",
  ui_story_5040_50401301_101_dialog_content = "君はとても大切な存在なんだよ。",
  ui_story_5040_50401301_102_dialog_content = "…！",
  ui_story_5040_50401301_103_dialog_content = "そうよ！イェリア、あなたは大切な存在よ！",
  ui_story_5040_50401301_104_dialog_content = "砂漠は残酷なところだもの。\n生きていこうと思ったら、お互いに助け合うしかないわ。",
  ui_story_5040_50401301_105_dialog_content = "一人ひとりは砂の海に浮かぶ小舟みたいなものよ。\n簡単にひっくり返っちゃう…",
  ui_story_5040_50401301_106_dialog_content = "でも、小さい舟だって、お互いにつながっていれば、\n簡単にはひっくり返らない。",
  ui_story_5040_50401301_107_dialog_content = "そのつながりを作って、守ってくれてるのが、\nクーリエ隊でしょ！",
  ui_story_5040_50401301_108_dialog_content = "…",
  ui_story_5040_50401301_109_dialog_content = "…ふふ…アドニスがどうして北境を出る気になれたのか、\nやっとわかった気がするわ。",
  ui_story_5040_50401301_110_dialog_content = "え？",
  ui_story_5040_50401301_111_dialog_content = "どうして？",
  ui_story_5040_50401301_112_dialog_content = "それは自分で考えることね、空の末裔くん。",
  ui_story_5040_50401301_113_dialog_content = "え？もったいぶらずに教えてよ！",
  ui_story_5040_50401301_114_dialog_content = "今はそれどころじゃなさそうよ？",
  ui_story_5040_50401301_115_dialog_content = "グォォ――！！！",
  ui_story_5040_50401301_116_dialog_content = "え？暗鬼！？どこから！？",
  ui_story_5040_50401301_117_dialog_content = "サンドワームが掘った穴を隠れ家にしてるんじゃないかしら。",
  ui_story_5040_50401301_118_dialog_content = "エモノが近いわ。",
  ui_story_5040_50401301_119_dialog_content = "一気に片付けちゃいましょ！",
  ui_story_5040_50401302_1_dialog_content = "<color=#e8d9bb>キキーッ！</color>",
  ui_story_5040_50401302_2_dialog_content = "ここがサンドワームの逃げたオアシス？",
  ui_story_5040_50401302_3_dialog_content = "サンドワームが棲みついてなかったら、\n集落にでもなってたでしょうねぇ。",
  ui_story_5040_50401302_4_dialog_content = "でも、今は人もいないし、荒れ放題よ。",
  ui_story_5040_50401302_5_dialog_content = "このままでもいいんじゃない？\nいい自然環境だと思うよ。",
  ui_story_5040_50401302_6_dialog_content = "きれいな湖の周りに、\nサンドワームに襲われた動物や光霊の骨が山ほど転がってるとしても？",
  ui_story_5040_50401302_7_dialog_content = "えっ！？",
  ui_story_5040_50401302_8_dialog_content = "砂漠じゃ、美しいものほど危険な一面を持ってるのよ。",
  ui_story_5040_50401302_9_dialog_content = "きれいだからといって、\n裏に隠れてる危険なものを見落とさないようにしなさい。",
  ui_story_5040_50401302_10_dialog_content = "そ、そうだね…",
  ui_story_5040_50401302_11_dialog_content = "おかしいわね。\nサンドワームの気配がないし、ウロコ一枚見当たらないわ。",
  ui_story_5040_50401302_12_dialog_content = "まさか、もう住みかを変えた？",
  ui_story_5040_50401302_13_dialog_content = "もう一つ、可能性があるわ――",
  ui_story_5040_50401302_14_dialog_content = "ピンクのサンドワームが他のサンドワームを追い払って、\nオアシスを独り占めしてる、とかね。",
  ui_story_5040_50401302_15_dialog_content = "この辺りにピンクのサンドワームの手がかりがないか、\n急いで探しましょ！",
  ui_story_5040_50401302_16_dialog_content = "またあなたにお願いしなきゃいけないみたいね、ホーク。",
  ui_story_5040_50401302_17_dialog_content = "ピュウッ！",
  ui_story_5040_50401302_18_dialog_content = "じゃあ僕も感知能力で探してみるよ。",
  ui_story_5040_50401302_19_option_content = "強制感知！",
  ui_story_5040_50401302_20_dialog_content = "（どうか…ピンクのサンドワームでも、\nキアでもアドニスでもいいから…感知できますように）",
  ui_story_5040_50401302_21_dialog_content = "これは…！",
  ui_story_5040_50401302_22_dialog_content = "イェリア、ターラ！キアとアドニスの気配だ！",
  ui_story_5040_50401302_23_dialog_content = "あら、ホークより早いわねぇ？",
  ui_story_5040_50401302_24_dialog_content = "どこ！？",
  ui_story_5040_50401302_25_dialog_content = "この先だよ！",
  ui_story_5040_50401302_26_dialog_content = "それじゃ分からないわよ、\n茂み以外は何も…",
  ui_story_5040_50401302_27_dialog_content = "僕の感知に間違いはないよ！2人はきっとこの近くにいるはずだ。\n気を失ってるか、聞こえてないのか…",
  ui_story_5040_50401302_28_dialog_content = "おーい――！",
  ui_story_5040_50401302_29_dialog_content = "キア！アドニス！セーブル！",
  ui_story_5040_50401302_30_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5040_50401302_31_dialog_content = "ちょっと待って。あの茂み、何かおかしいわ。\nあの低木は上に伸びる種類のはずだけど、横に倒れてるわね。",
  ui_story_5040_50401302_32_dialog_content = "きっと人が触った痕跡だわ…",
  ui_story_5040_50401302_33_dialog_content = "アドニス！？",
  ui_story_5040_50401302_34_dialog_content = "キアもいるよ！…セーブルは？",
  ui_story_5040_50401302_35_dialog_content = "2人とも息はあるわ。気を失ってるだけよ。",
  ui_story_5040_50401302_36_dialog_content = "アドニス、しっかりして！",
  ui_story_5040_50401302_37_dialog_content = "ううっ…ぼ、僕は…どうしたんだっけ…",
  ui_story_5040_50401302_38_dialog_content = "無事だったのね！よかった！",
  ui_story_5040_50401302_39_dialog_content = "う！ターラ、そんなに力を入れないで。\nあばらが折れちゃうよ…いや、もう折れてるのかな…",
  ui_story_5040_50401302_40_dialog_content = "ごめんなさい。うれしくて、つい…\n無事でほんとによかった！",
  ui_story_5040_50401302_41_dialog_content = "どうやってここまで来たか、覚えてる？\nセーブルは一緒じゃないの？",
  ui_story_5040_50401302_42_dialog_content = "ええと、確か…",
  ui_story_5040_50401302_43_dialog_content = "ものすごい砂嵐が起こった時、地面が崩れたんだ…\nそれから、ピンクのサンドワームが向かってきて…",
  ui_story_5040_50401302_44_dialog_content = "僕はただ砂と風に飛ばされないようにと思って、\nとっさにウロコをつかんでサンドワームにしがみついたんだ。",
  ui_story_5040_50401302_45_dialog_content = "その後はサンドワームに、\n洞窟みたいな、真っ暗な所に連れ込まれて…",
  ui_story_5040_50401302_46_dialog_content = "大声でキアとセーブルの名前を呼んだけど、返事がなくて…",
  ui_story_5040_50401302_47_dialog_content = "サンドワームはまだ動いてたから、手を放すわけにもいかなくて…\n必死にしがみついてるうちに、気を失ったってことかな。",
  ui_story_5040_50401302_48_dialog_content = "サンドワームにしがみつくなんて、\n次からはやめておくことね。",
  ui_story_5040_50401302_49_dialog_content = "危ない行為だったのよ？\n今回は助かったけど、運が良かっただけ。",
  ui_story_5040_50401302_50_dialog_content = "サンドワームなんて、\n今まで見たこともなかったもので…",
  ui_story_5040_50401302_51_dialog_content = "とにかく、無事でよかったわ。\n今はそれだけで十分よ。",
  ui_story_5040_50401302_52_dialog_content = "うん、僕は本当に運が良かった。",
  ui_story_5040_50401302_53_dialog_content = "そうだ！これを見て！",
  ui_story_5040_50401302_54_dialog_content = "ピンクのサンドワームのウロコ！？",
  ui_story_5040_50401302_55_dialog_content = "はい！サンドワームにしがみついていた時、\n偶然とれたんです！",
  ui_story_5040_50401302_56_dialog_content = "1枚しかないので、足りるかは分かりませんが…",
  ui_story_5040_50401302_57_dialog_content = "（…でも、ターラはそもそも記憶喪失じゃない…\nアドニスに本当のことを言った方がいいかな？）",
  ui_story_5040_50401302_58_dialog_content = "アドニス…そのことだけど…",
  ui_story_5040_50401302_59_dialog_content = "え？ターラ、どうしたんだい？",
  ui_story_5040_50401302_60_dialog_content = "記憶、失くしてないの。",
  ui_story_5040_50401302_61_dialog_content = "全部ウソだったの。あなたを試そうとして…\n北境を出る決心をしてもらいたくて…",
  ui_story_5040_50401302_62_dialog_content = "ターラ、どうしてそんなことを…",
  ui_story_5040_50401302_63_dialog_content = "ごめんなさい…",
  ui_story_5040_50401302_64_dialog_content = "こんなことまでするべきじゃなかった…\n命の危険まで冒させて…何を言われても仕方ないわ…",
  ui_story_5040_50401302_65_dialog_content = "もう無理に不慣れな環境で暮らしてなんて言わないわ…\nあたしたち…これからは北境で暮らしましょ。",
  ui_story_5040_50401302_66_dialog_content = "でも、北境は不便な所だよ。\n君が遺跡探検に出ていくのだってままならなくなる。",
  ui_story_5040_50401302_67_dialog_content = "もう…行かないわ。",
  ui_story_5040_50401302_68_dialog_content = "あなたのほうが遺跡よりずっと大切だもの。",
  ui_story_5040_50401302_69_dialog_content = "…",
  ui_story_5040_50401302_70_dialog_content = "許さないよ。",
  ui_story_5040_50401302_71_dialog_content = "え！？",
  ui_story_5040_50401401_1_dialog_content = "僕は今、ものすごく怒ってる。",
  ui_story_5040_50401401_2_dialog_content = "ごめんなさい…",
  ui_story_5040_50401401_3_dialog_content = "謝る前に、理由をしっかり聞いてくれるかな。",
  ui_story_5040_50401401_4_dialog_content = "今までの僕は実際、北境を出ることもできない意気地なしだった。\n暗鬼に立ち向かうなんてなおさらだ。",
  ui_story_5040_50401401_5_dialog_content = "そんな僕になんとか勇気を振り絞らせて、決心させようって、\n君もいろいろ考えた末にこうしたんだよね。",
  ui_story_5040_50401401_6_dialog_content = "アドニス…",
  ui_story_5040_50401401_7_dialog_content = "つまり、記憶喪失のフリをしてたことに\n腹を立ててるワケじゃないってこと？",
  ui_story_5040_50401401_8_dialog_content = "そうです。昨日の夜にはもう、記憶喪失が\nウソなんじゃないかとは気づいていました。でも、腹は立ちませんでした。",
  ui_story_5040_50401401_9_dialog_content = "むしろ、ほっとしました。",
  ui_story_5040_50401401_10_dialog_content = "だって、ターラが僕のことを嫌いになって、\n忘れてしまったわけではなかったんですから。",
  ui_story_5040_50401401_11_dialog_content = "じゃあ、怒ってるって言うのはなんで？",
  ui_story_5040_50401401_12_dialog_content = "それが「妥協」だからね？",
  ui_story_5040_50401401_13_dialog_content = "「妥協」って、何を？",
  ui_story_5040_50401401_14_dialog_content = "さすがはイェリアさんです。\n僕の考えをあっさり見抜くなんて。",
  ui_story_5040_50401401_15_dialog_content = "いったいどういうこと？\n僕にもわかるように教えてもらえない？",
  ui_story_5040_50401401_16_dialog_content = "僕が怒ったのは、\nターラが北境で僕と暮らすために探検をあきらめると言ったからです。",
  ui_story_5040_50401401_17_option_content = "ターラを縛り付けたくないってこと？",
  ui_story_5040_50401401_18_dialog_content = "そうです！",
  ui_story_5040_50401401_19_option_content = "まさかターラを嫌いになったの？",
  ui_story_5040_50401401_20_dialog_content = "そんなはずないでしょう？\nターラを嫌いになったりはしません。",
  ui_story_5040_50401401_21_dialog_content = "僕は彼女のことをよく分かっています。\nターラが北境で穏やかな一生を送りたいなんて、本気で思うはずはない。",
  ui_story_5040_50401401_22_dialog_content = "僕のために北境に留まるという気持ちにウソはないとしても、\nそれが妥協で、本当はそうしたくないことはすぐに分かります。",
  ui_story_5040_50401401_23_dialog_content = "僕のためにターラが自分の気持ちを殺すなんてこと、僕は望みません！",
  ui_story_5040_50401401_24_dialog_content = "アドニス…？",
  ui_story_5040_50401401_25_dialog_content = "僕が好きなのは、いつでも果敢に、\n遺跡を冒険し続けるターラなんだ。",
  ui_story_5040_50401401_26_dialog_content = "ターラがいたから、ずっと北境にこもっていた僕でも、\nアストラ大陸がどんなに広い所か知ることができたんだ。",
  ui_story_5040_50401401_27_dialog_content = "今でも覚えてるよ。R・W砂漠から啓光の防衛線を眺めたら、\n地平線に連なるシェルターの影が見えたって話してくれた時のこと…",
  ui_story_5040_50401401_28_dialog_content = "それから、アストラ大陸の広大な山脈も平原も、\n白夜城から眺めると、時と共に姿が変わる雲の下にあるんだって話も…",
  ui_story_5040_50401401_29_dialog_content = "ふふっ…それから、スリに間違えられて\n白夜城の兵士にしつこく尋問されたこと？",
  ui_story_5040_50401401_30_dialog_content = "あの時はほんとに大変だったわ。\n兵士たちと一緒に真犯人を追いかけるハメになったんだから。",
  ui_story_5040_50401401_31_dialog_content = "アハハ、そうそう。でも結局捕まえられたんだよね。\n君は目が効くし、足も速かったから。",
  ui_story_5040_50401401_32_dialog_content = "濡れ衣を晴らすの、そうとう苦労したのよ！",
  ui_story_5040_50401401_33_dialog_content = "…とにかく、話がそれたけど、\n僕が伝えたいのはごく簡単なことだよ――",
  ui_story_5040_50401401_34_dialog_content = "ターラ、君に会うまで、\n僕の世界は雪原みたいに白一色だった。",
  ui_story_5040_50401401_35_dialog_content = "そんな変わり映えのしない毎日に\n美しい色を添えてくれたのが、ターラ、君なんだ。",
  ui_story_5040_50401401_36_dialog_content = "僕は今のままの君が好きだ。\n君を束縛したり、世界中を飛び回ることの邪魔になりたくない。",
  ui_story_5040_50401401_37_dialog_content = "僕も勇気を出して、君と一緒に冒険するよ！",
  ui_story_5040_50401401_38_dialog_content = "<size=45>アドニス――！</size>",
  ui_story_5040_50401401_39_dialog_content = "イタタタ――！\n痛いよ…そんなにきつく抱きしめないでくれるかい？",
  ui_story_5040_50401401_40_dialog_content = "そんな風に考えてたんだ…",
  ui_story_5040_50401401_41_dialog_content = "感知能力で他人の思考が読める空の末裔くんでも、\n人の心を理解できるとは限らないのねぇ。",
  ui_story_5040_50401401_42_dialog_content = "感知能力は万能じゃないよ。",
  ui_story_5040_50401401_43_dialog_content = "そうでしょうね。だからこそ、人同士の関係には誤解も生まれるし、\n誤解のせいでヒビが入って、つながりが切れることだってあるものと言えるわ。",
  ui_story_5040_50401401_44_dialog_content = "でも、お互いに理解しあうことでヒビを埋めて、\nもう一度つながりを持つことができた時には――",
  ui_story_5040_50401401_45_dialog_content = "その関係は前よりずっと強く、堅くなるの。",
  ui_story_5040_50401401_46_dialog_content = "うう…騒がしいですね…",
  ui_story_5040_50401401_47_dialog_content = "キア！やっと気が付いた！",
  ui_story_5040_50401401_48_dialog_content = "PlayerNameさん、イェリア先輩？\nそれに…ターラさんとアドニスさん…仲直りしたんですか？",
  ui_story_5040_50401401_49_dialog_content = "いろいろあったけど、仲直りしたみたいだよ。",
  ui_story_5040_50401401_50_dialog_content = "それはよかったです！私とセーブルも\nサンドワームの巻き添えになった時、アドニスさんのことを心配していました。",
  ui_story_5040_50401401_51_dialog_content = "そうだ、セーブルは？セーブルはどこですか？",
  ui_story_5040_50401401_52_dialog_content = "僕たちがここに来た時には君とアドニスしかいなかったよ。\n感知もしたけど、セーブルがこの辺にいる気配はなかった。",
  ui_story_5040_50401401_53_dialog_content = "気を失う前に何があったか覚えてる？",
  ui_story_5040_50401401_54_dialog_content = "わ、私とセーブルは砂嵐で吹き飛ばされて…\nセーブルは確か、サンドワームの角をつかんでいたような…",
  ui_story_5040_50401401_55_dialog_content = "その後、サンドワームが私たちごと地下に潜ったんです。\n私はその時に石に頭をぶつけてしまって…後は分かりません。",
  ui_story_5040_50401401_56_dialog_content = "キアが気を失ってたなら、\n君たちを茂みの中に隠したのは誰？",
  ui_story_5040_50401401_57_dialog_content = "まさか…",
  ui_story_5040_50401401_58_dialog_content = "セーブル？",
  ui_story_5040_50401401_59_dialog_content = "もしセーブルが2人を隠したっていうなら、\nどうして近くにいないの？",
  ui_story_5040_50401401_60_dialog_content = "一人でサンドワームを引き付けて、\nキアたちを守ったのかもしれないわね。あるいは――",
  ui_story_5040_50401401_61_dialog_content = "限界が来たと感じた…",
  ui_story_5040_50401401_62_dialog_content = "限界？また何か、僕の知らない話？",
  ui_story_5040_50401401_63_dialog_content = "PlayerNameさん。セーブルは光霊ではありません…\nですが…昔は光霊だったんです…",
  ui_story_5040_50401401_64_dialog_content = "え！？",
  ui_story_5040_50401401_65_dialog_content = "やっぱり…",
  ui_story_5040_50401401_66_dialog_content = "空の末裔くん、驚いてないみたいねぇ？",
  ui_story_5040_50401401_67_dialog_content = "うん…何となく気づいてたからね。\n確信はなかったけど…",
  ui_story_5040_50401401_68_dialog_content = "恋人に捨てられて絶望していた時、\n暗鬼の誘惑に負けて、ああなったんだそうです…",
  ui_story_5040_50401401_69_dialog_content = "見た目は変わってしまいましたし、心も影響を受けてはいますが、\nずっと自分の意志で破壊衝動を抑えていたそうです。",
  ui_story_5040_50401401_70_dialog_content = "でも、少し前に言ってました。\nそろそろ限界かもしれないと…",
  ui_story_5040_50401401_71_dialog_content = "そんな、どうして…",
  ui_story_5040_50401401_72_dialog_content = "（こういう状況、経験したことある気がする…）",
  ui_story_5040_50401401_73_dialog_content = "空の末裔くん、セーブルをどう思ってるの？",
  ui_story_5040_50401401_74_option_content = "いい人だと思う",
  ui_story_5040_50401401_75_dialog_content = "見た目は変わってるけど、\n誰に対しても優しいし、いい人のはずだよ。",
  ui_story_5040_50401401_76_dialog_content = "セーブルが困ってるなら、\n僕たちは助けてあげるべきだ。",
  ui_story_5040_50401401_77_option_content = "あまりよく知らないけど…",
  ui_story_5040_50401401_78_dialog_content = "そうとう恥ずかしがり屋みたいだね。\nほとんど話したこともないけど、心のきれいな人だろうと思うよ。",
  ui_story_5040_50401401_79_dialog_content = "セーブルさえよければ、友だちになりたいね。",
  ui_story_5040_50401401_80_dialog_content = "だったら、何とかしてセーブルを見つけましょ。",
  ui_story_5040_50401401_81_dialog_content = "うん！",
  ui_story_5040_50401401_82_dialog_content = "ピュウ――！",
  ui_story_5040_50401401_83_dialog_content = "ホークが知らせを持ち帰ったようね。\nお疲れ様～。",
  ui_story_5040_50401401_84_dialog_content = "ピュー、ピュー！",
  ui_story_5040_50401401_85_dialog_content = "セーブルを見つけたの？",
  ui_story_5040_50401401_86_dialog_content = "どこですか！？",
  ui_story_5040_50401401_87_dialog_content = "ピュウ――",
  ui_story_5040_50401401_88_dialog_content = "アタシたちの足下？",
  ui_story_5040_50401401_89_dialog_content = "足下？",
  ui_story_5040_50401401_90_dialog_content = "確かに、下の方から弱い暗力が近づいてくる気配がする…",
  ui_story_5040_50401401_91_dialog_content = "<color=#e8d9bb>ドカン――！！！</color>",
  ui_story_5040_50401401_92_dialog_content = "うっ！？すごい震動…サンドワーム！？",
  ui_story_5040_50401401_93_dialog_content = "<size=45>グォオオ――！！</size>",
  ui_story_5040_50401401_94_dialog_content = "ターラ、危ない！",
  ui_story_5040_50401401_95_dialog_content = "やっぱり、まだ近くにいたのね。",
  ui_story_5040_50401401_96_dialog_content = "<size=45>グオォォ――！</size>",
  ui_story_5040_50401401_97_dialog_content = "サンドワームを追って何かが飛び出してきてます！\nあれは…セーブル！？",
  ui_story_5040_50401401_98_dialog_content = "行かせ、ない！",
  ui_story_5040_50401401_99_dialog_content = "セーブル！？でも、あの姿は…",
  ui_story_5040_50401401_100_dialog_content = "暗鬼だろうと何だろうと、\n私たちの味方であることに変わりありません！",
  ui_story_5040_50401401_101_dialog_content = "PlayerNameさん、助けてあげてください！",
  ui_story_5040_50401401_102_dialog_content = "…",
  ui_story_5040_50401401_103_dialog_content = "分かった。",
  ui_story_5040_50401401_104_dialog_content = "準備はいい、空の末裔くん？\nピンクの厄介者を片づけましょ！",
  ui_story_5040_50401401_105_dialog_content = "大丈夫なの？ずっと戦いっぱなしだよ。\n今までにさんざん光力を使ってるし…",
  ui_story_5040_50401401_106_dialog_content = "ふふ、優しいのねぇ。",
  ui_story_5040_50401401_107_dialog_content = "心配いらないわ。\n車にいる間に回復してるから。",
  ui_story_5040_50401401_108_dialog_content = "行きましょ。",
  ui_story_5040_50401401_109_dialog_content = "うん、セーブルを助けよう！",
  ui_story_5040_50401402_1_dialog_content = "私の記憶は、もうはっきりしていない。",
  ui_story_5040_50401402_2_dialog_content = "切り刻まれたフィルムのように…\n断片的な記憶が頭に浮かんで来るだけ。",
  ui_story_5040_50401402_3_dialog_content = "最初の記憶は、広い砂漠…\n生まれ育った場所…",
  ui_story_5040_50401402_4_dialog_content = "クーリエが届けてくれた、あの手紙を開けるまで、\n私は大勢の中の一人…ありふれた存在…",
  ui_story_5040_50401402_5_dialog_content = "手紙が砂漠の外のキラキラした世界を教えてくれた。\nそして…「あの人」を知った。",
  ui_story_5040_50401402_6_dialog_content = "名前はもう忘れた。\nでも、手紙を交わすたびに気持ちが強くなったことは…まだ覚えてる。",
  ui_story_5040_50401402_7_dialog_content = "手紙で告白して、その気持ちを受けとめてもらえた時…",
  ui_story_5040_50401402_8_dialog_content = "あふれる喜びで、踊り出しそうになったほどだった。",
  ui_story_5040_50401402_9_dialog_content = "でも、その日からだんだん返事が減っていった。",
  ui_story_5040_50401402_10_dialog_content = "自分の書く手紙に心がこもってないのかと思った。\nだから、手紙に贈り物を添えるようになった。",
  ui_story_5040_50401402_11_dialog_content = "最初は砂漠では珍しいお花と、貴重な古代の遺物。",
  ui_story_5040_50401402_12_dialog_content = "それから、贈り物の量はどんどん増えて、高価になって…\n最後には白夜コインを直接贈るようになった。",
  ui_story_5040_50401402_13_dialog_content = "それなのに、返事は減るばかり…\n内容ももっと多くの贈り物を要求されるだけ。",
  ui_story_5040_50401402_14_dialog_content = "私には理解できなかった。でも彼を疑うこともなかった。\n会いたいと言ったら、手紙で住所を教えてくれた。",
  ui_story_5040_50401402_15_dialog_content = "だから私は勇気を振り絞って、\n生まれて初めて砂漠を出た。",
  ui_story_5040_50401402_16_dialog_content = "手紙の通りに、啓光まで行って…",
  ui_story_5040_50401402_17_dialog_content = "白夜城にも行って…",
  ui_story_5040_50401402_18_dialog_content = "最後は鏡湖にたどり着いた。",
  ui_story_5040_50401402_19_dialog_content = "あの人は言っていた。\n私と北境で盛大な結婚式を挙げてくれるって。",
  ui_story_5040_50401402_20_dialog_content = "でも、どこにも彼の姿はなかった。",
  ui_story_5040_50401402_21_dialog_content = "私は絶望して泣きわめいた。\nもうどこへ行ったらいいのかも、家に帰れるのかも分からない。",
  ui_story_5040_50401402_22_dialog_content = "そんな時、声をかけられた…",
  ui_story_5040_50401402_23_dialog_content = "この「シード」を受け入れなさい。\n願いをかなえる力を与えてくれるわ。",
  ui_story_5040_50401402_24_dialog_content = "私は希望をその「シード」に託した。\nでも…その結果、すべてを失ってしまった…",
  ui_story_5040_50401402_25_dialog_content = "記憶も考える力も失って、\n野獣同然の化け物になり、あちこちを放浪した…",
  ui_story_5040_50401402_26_dialog_content = "でも、アドニスとターラを見て私は知った。\nこの世にはまだ、愛が存在するということ。",
  ui_story_5040_50401402_27_dialog_content = "それから、キアを見て…\n責任を負うと言うこと、約束を守ることの尊さを知った。",
  ui_story_5040_50401402_28_dialog_content = "イェリアも…\n無関心を装っているけど、実は頼りになる。",
  ui_story_5040_50401402_29_dialog_content = "彼女は私に自由とは何かを教えてくれた。",
  ui_story_5040_50401402_30_dialog_content = "だから…今の私にできることは、1つだけ…",
  ui_story_5040_50401402_31_dialog_content = "――絶対に、行かせ、ない！",
  ui_story_5040_50401402_32_dialog_content = "<size=45>グォオオ――！！</size>",
  ui_story_5040_50401402_33_dialog_content = "うっ…！？",
  ui_story_5040_50401402_34_dialog_content = "セーブル！",
  ui_story_5040_50401402_35_dialog_content = "あのサンドワーム、セーブルを狙ってます！\nイェリア先輩、頭を攻撃して、注意を引いてください！",
  ui_story_5040_50401402_36_dialog_content = "私のことは、いい！",
  ui_story_5040_50401402_37_dialog_content = "弱点、狙って！",
  ui_story_5040_50401402_38_dialog_content = "…",
  ui_story_5040_50401402_39_dialog_content = "分かったわ――",
  ui_story_5040_50401402_40_dialog_content = "<color=#e8d9bb>ドカン――！</color>",
  ui_story_5040_50401402_41_dialog_content = "グォォ…",
  ui_story_5040_50401402_42_dialog_content = "うっ…",
  ui_story_5040_50401402_43_dialog_content = "（サンドワームが倒れた…）",
  ui_story_5040_50401402_44_dialog_content = "（イェリアの光力術がサンドワームの古傷を貫いた）",
  ui_story_5040_50401402_45_dialog_content = "（でも、セーブルはサンドワームに深々と噛みつかれ、\nそのまま投げ捨てられた…）",
  ui_story_5040_50401402_46_dialog_content = "セーブル！大丈夫ですか！？",
  ui_story_5040_50401402_47_dialog_content = "いたい…",
  ui_story_5040_50401402_48_dialog_content = "セーブル、セーブル！\nしっかりしてください！",
  ui_story_5040_50401402_49_dialog_content = "これは…かなりの重傷じゃ…？",
  ui_story_5040_50401402_50_dialog_content = "いくら生命力の強い暗鬼でも、たぶん…",
  ui_story_5040_50401402_51_dialog_content = "光力術で治せるか試してみます！",
  ui_story_5040_50401402_52_dialog_content = "…ダメです、まったく効きません…",
  ui_story_5040_50401402_53_dialog_content = "ムダね。あなたの光力術で治せるような傷じゃなさそうだわ…",
  ui_story_5040_50401402_54_dialog_content = "イェリア先輩！\nどうしてセーブルを助けてあげなかったんですか！？",
  ui_story_5040_50401402_55_dialog_content = "アタシは彼女の願いをかなえてあげただけよ。",
  ui_story_5040_50401402_56_dialog_content = "あなただって分かってることでしょう？\n助けたところで、彼女はそのうち意識のない怪物になるって。",
  ui_story_5040_50401402_57_dialog_content = "…",
  ui_story_5040_50401402_58_dialog_content = "キア…",
  ui_story_5040_50401402_59_dialog_content = "セーブル！？ここにいますよ！",
  ui_story_5040_50401402_60_dialog_content = "イェリアを…責めない…で…",
  ui_story_5040_50401402_61_dialog_content = "私…自分が…みんなを…傷つけてるのが、怖くて…\n立ち去ろうと…決めた。でも…サンドワームが…",
  ui_story_5040_50401402_62_dialog_content = "最後に…キアと…みんなと…出会えて…",
  ui_story_5040_50401402_63_dialog_content = "自分が…光霊だったって…思い出せて…",
  ui_story_5040_50401402_64_dialog_content = "ほんとに、よかった…",
  ui_story_5040_50401402_65_dialog_content = "で…でも、依頼はまだ終わっていません！\nあなたを家に連れていく約束だったでしょう！？",
  ui_story_5040_50401402_66_dialog_content = "依頼…変える。",
  ui_story_5040_50401402_67_dialog_content = "これを…私の、家に…",
  ui_story_5040_50401402_68_dialog_content = "家族に…ごめんって、伝えて…",
  ui_story_5040_50401402_69_dialog_content = "…",
  ui_story_5040_50401402_70_dialog_content = "依頼を確かに承りました。",
  ui_story_5040_50401402_71_dialog_content = "クーリエ・キア、使命は必ずやり遂げます！",
  ui_story_5040_50401402_72_dialog_content = "おねがい、ね…",
  ui_story_5040_50401402_73_dialog_content = "セーブル…ううっ…",
  ui_story_5040_50401402_74_dialog_content = "キア、そんなに泣いたら、体に悪いわよ…",
  ui_story_5040_50401402_75_dialog_content = "な、涙を拭けるもの、持ってくるよ。",
  ui_story_5040_50401402_76_dialog_content = "…",
  ui_story_5040_50401402_77_dialog_content = "泣きたいだけ泣けばいいわ。",
  ui_story_5040_50401402_78_dialog_content = "その悲しみを前に進む力に変えるの。",
  ui_story_5040_50401402_79_dialog_content = "イェリア…？",
  ui_story_5040_50401402_80_dialog_content = "…大丈夫？どうして急にいなくなったの？",
  ui_story_5040_50401402_81_dialog_content = "アタシだって、気持ちの整理が必要な時はあるのよ。",
  ui_story_5040_50401402_82_dialog_content = "そうだよね、ごめん。\n君ならどんなことでも軽く流せちゃうかと思ってた。",
  ui_story_5040_50401402_83_dialog_content = "ほめ言葉だと思っておくわ。",
  ui_story_5040_50401402_84_dialog_content = "本当はずっと前から気づいてたのよ。\nセーブルはもう長く持たないって…",
  ui_story_5040_50401402_85_dialog_content = "今までみたいに他人事だって流せるかと思ってたけど、ダメみたいね。",
  ui_story_5040_50401402_86_dialog_content = "最初から気づいてたの？\nどうして皆に言わなかったの？",
  ui_story_5040_50401402_87_dialog_content = "どうして話す必要があるの？",
  ui_story_5040_50401402_88_dialog_content = "それは…話してくれたら、\nもっと何かしてあげられたかもしれない。",
  ui_story_5040_50401402_89_dialog_content = "ターラとアドニスなら、\nセーブルを拒絶したりしないよ。",
  ui_story_5040_50401402_90_dialog_content = "あの2人は確かにそうね。でも、それ以外の人は？",
  ui_story_5040_50401402_91_dialog_content = "秘密って知ってる人が多くなるほど、\n漏れやすいのよ。",
  ui_story_5040_50401402_92_dialog_content = "暗鬼に恨みを持ってる光霊だって多いの。",
  ui_story_5040_50401402_93_dialog_content = "それに…あの子はもう二度と出られない嵐に飛び込んだ後だった…",
  ui_story_5040_50401402_94_dialog_content = "秘密がどこかで漏れれば、彼女の大切な「最後の旅」が、\n起こさなくて済んだはずの面倒で台無しになったかもしれないわ。",
  ui_story_5040_50401402_95_dialog_content = "そうだね…",
  ui_story_5040_50401402_96_dialog_content = "空の末裔くん。\nきちんと肝に銘じておきなさい。",
  ui_story_5040_50401402_97_dialog_content = "人と人とのつながりは確かに大切よ。\nでも、多ければ多いほど、近ければ近いほどいいってワケじゃないの。",
  ui_story_5040_50401402_98_dialog_content = "ほどほどの距離を保って、\n秘密を守ることが最良の選択ってことも多いのよ。",
  ui_story_5040_50401402_99_dialog_content = "人同士のつながりは、はばたく鳥を助ける風になってこそ価値がある。\n翼を縛り付ける網になっては意味が無いの。",
  ui_story_5040_50401402_100_dialog_content = "うん…",
  ui_story_5040_50401402_101_dialog_content = "イェリア先輩、さっきは申し訳ありません…",
  ui_story_5040_50401402_102_dialog_content = "長いこと泣いてしまって、ご迷惑をおかけしました…",
  ui_story_5040_50401402_103_dialog_content = "迷惑なんかじゃないわよ！いつも気持ちを抑えてばかりじゃダメ！\n発散するべき時には発散しなきゃ！",
  ui_story_5040_50401402_104_dialog_content = "ターラの言う通りです。",
  ui_story_5040_50401402_105_dialog_content = "決心がついたみたいね、キア。",
  ui_story_5040_50401402_106_dialog_content = "はい、もう泣きません。私にはまだ使命が残っていますから。\nセーブルから託された切手を彼女の故郷に届けます。",
  ui_story_5040_50401402_107_dialog_content = "今はまだ彼女の故郷がどこかも分かりませんが…\nこれが終わったら、R・W支部に異動願いを出します。",
  ui_story_5040_50401402_108_dialog_content = "仕事をしながら、砂漠のことを知って、\nセーブルの故郷を探します。",
  ui_story_5040_50401402_109_dialog_content = "たとえ砂漠中を探すことになっても、\n私は絶対あきらめません！",
  ui_story_5040_50401402_110_dialog_content = "どんなに遠くても目的に向かって、\n必ず最後までやり遂げる、そういうことね？",
  ui_story_5040_50401402_111_dialog_content = "はい！",
  ui_story_5040_50401402_112_dialog_content = "で、あなたたちはどうなの？",
  ui_story_5040_50401402_113_dialog_content = "気持ちはもう決まってるわ。\nあたしは心からアドニスを愛してる。",
  ui_story_5040_50401402_114_dialog_content = "試練も証明も、もう必要ないわ。",
  ui_story_5040_50401402_115_dialog_content = "僕も同じです。外の世界は確かに危険ですが、\n想像していたほどではありませんでした。",
  ui_story_5040_50401402_116_dialog_content = "僕は外の世界が怖かったのではなく、\n未知の世界が怖かっただけだと言うことも分かりました。",
  ui_story_5040_50401402_117_dialog_content = "今はこうして、ターラのおかげで、\nその恐怖も克服できました。",
  ui_story_5040_50401402_118_dialog_content = "あたし、二度とアドニスに\nできないことを無理強いしたりしないわ。",
  ui_story_5040_50401402_119_dialog_content = "だいぶ遠回りして、色々危険な目にも遭ったし、\n悲しいこともあったけど…",
  ui_story_5040_50401402_120_dialog_content = "最後には2人が理解し合えて、本当によかったよ…",
  ui_story_5040_50401402_121_dialog_content = "不幸中の幸いってやつかしらねぇ。",
  ui_story_5040_50401402_122_dialog_content = "でも、もしアドニスがウロコを手に入れられずに、\n「試練」を失敗してたら、あなたはどうするつもりだったの？",
  ui_story_5040_50401402_123_dialog_content = "記憶喪失のフリを続けるつもりだったなんて、\n言わないわよねぇ？",
  ui_story_5040_50401402_124_dialog_content = "それは…",
  ui_story_5040_50401402_125_dialog_content = "他に何か考えてあったんでしょ？",
  ui_story_5040_50401402_126_dialog_content = "そうよ…イェリアの目はごまかせないわね。",
  ui_story_5040_50401402_127_dialog_content = "ウロコがもう1枚！？",
  ui_story_5040_50401402_128_dialog_content = "これはお頭がアイツと戦った時に拾ったウロコよ。\n競り落としたの、結構な値段になっちゃったけど。",
  ui_story_5040_50401402_129_dialog_content = "買ったの、君だったのかい！？",
  ui_story_5040_50401402_130_dialog_content = "それであの魔法の万能薬のことを疑ってたんだね。\n霊媒師の言った原料を君が持ってたんだから。",
  ui_story_5040_50401402_131_dialog_content = "それ以前の問題でしょ…\n「魔法の万能薬」なんて、聞いただけで怪しいって分かるわよ。",
  ui_story_5040_50401402_132_dialog_content = "あんなインチキに引っかかるのは、\nあなたみたいに単純な人だけよ。",
  ui_story_5040_50401402_133_dialog_content = "そ、そんな…僕は…",
  ui_story_5040_50401402_134_dialog_content = "実は最初に記憶喪失のフリをしようって決めた時、\nこうなることも想定してたの。",
  ui_story_5040_50401402_135_dialog_content = "もし試練を達成できなかったら…",
  ui_story_5040_50401402_135X1_dialog_content = "このウロコをイェリアに渡して、\n「別の方法」で手に入れられるように考えてもらおうと思ってたの。",
  ui_story_5040_50401402_136_dialog_content = "そういうことだったんだ。\nところで、どうしてそのウロコを買ったの？",
  ui_story_5040_50401402_137_dialog_content = "…！",
  ui_story_5040_50401402_138_dialog_content = "…レア物だし、ピンク色だから、その…",
  ui_story_5040_50401402_139_dialog_content = "アドニスにも見せてあげたいと思って、\nつい衝動買いしちゃって…",
  ui_story_5040_50401402_140_dialog_content = "…本当は、結婚指輪に加工してもらって、\nアドニスに渡そうと思ってたの…！",
  ui_story_5040_50401402_141_dialog_content = "あら～？面白いわねぇ。\nサンドワームもきれいなピンク色のウロコを生やしたかいがあるわ。",
  ui_story_5040_50401402_142_dialog_content = "でも、このウロコ、硬いのは中心だけねぇ。\nせいぜい指輪1つ分にしかならないわ。",
  ui_story_5040_50401402_143_dialog_content = "たまたまもう1枚手に入ったけど、たった1枚のウロコをアドニスにあげちゃったら、\nあなたの分はどうするつもりだったの？",
  ui_story_5040_50401402_144_dialog_content = "それは…考えてなかったわ。",
  ui_story_5040_50401402_145_dialog_content = "でも、どうでもいいじゃない！\n別の材料で適当に作ればいいのよ。",
  ui_story_5040_50401402_146_dialog_content = "ターラ、昔から自分のことは二の次だね。\nでも、それは良くないよ。",
  ui_story_5040_50401402_147_dialog_content = "結婚指輪は2つで1つなんだから。\nまあ――",
  ui_story_5040_50401402_148_dialog_content = "今は気にしなくて良くなったけどね。",
  ui_story_5040_50401402_149_dialog_content = "<color=#e8d9bb>キーッ！！</color>",
  ui_story_5040_50401402_150_dialog_content = "サンドワームは！？\nおい、サンドワームはどこだ？",
  ui_story_5040_50401402_151_dialog_content = "落ち着け、ヘール。\nあそこだよ。",
  ui_story_5040_50401402_152_dialog_content = "ピンク色だ！マジでいやがったんだな！\n…あれ、あいつ動かねぇぞ…",
  ui_story_5040_50401402_153_dialog_content = "もう死んでるんじゃないか！？",
  ui_story_5040_50401402_154_dialog_content = "フェラール、ヘール？\nどうしてここに？",
  ui_story_5040_50401402_155_dialog_content = "PlayerNameか。無事ならよかった。",
  ui_story_5040_50401402_156_dialog_content = "ボスからキミたちが\nピンクのサンドワームを探してるって聞いて、心配になってね。",
  ui_story_5040_50401402_157_dialog_content = "すぐに飛び出して来たんだが、\n応援は必要なかったみたいだな。",
  ui_story_5040_50401402_158_dialog_content = "あら、R・Wにもずいぶん仲間思いの人がいるのねぇ。\nでも残念ね…少し遅かったわ。",
  ui_story_5040_50401402_159_dialog_content = "そうみたいだな…\n次はもっと早く駆け付けられるようにするさ。",
  ui_story_5040_50401402_160_dialog_content = "まあ、もう片付いてるなら、\n俺たちはこれで失礼するよ。",
  ui_story_5040_50401402_161_dialog_content = "今回は出遅れちまったが、\n次は必ずコイツよりも強えヤツを俺様が仕留めてやる！",
  ui_story_5040_50401402_162_dialog_content = "…そういや、そのデカいサンドワーム、どうすんだ？\n運ぶの手伝ってやろうか？ウロコが高値で売れるんだろ？",
  ui_story_5040_50401402_163_dialog_content = "キアの友人が命と引き換えに仕留めた獲物よ。\n簡単に渡すワケにはいかないわ。",
  ui_story_5040_50401402_164_dialog_content = "少なくともキアの意見を聞かないとね？",
  ui_story_5040_50401402_165_dialog_content = "…サンドワームの処分については、\n何の意見もありません。",
  ui_story_5040_50401402_166_dialog_content = "ターラさんとアドニスさんが指輪を作れるだけのウロコさえ残してもらえれば、\nあとは好きなように処分してください。",
  ui_story_5040_50401402_167_dialog_content = "きっと…セーブルもそう望むでしょう。",
  ui_story_5040_50401402_168_dialog_content = "…何があったのかは知らないけどよ、\nあんたもそう落ち込むな。",
  ui_story_5040_50401402_169_dialog_content = "サンドワームはキッチリ使い切ってやるよ。\nゼッタイ無駄にはしねぇ。",
  ui_story_5040_50401402_170_dialog_content = "じゃあ、俺たちは先に戻って人を呼んでくるよ。\nこれだけのデカブツ、大勢が必要になる。",
  ui_story_5040_50401402_171_dialog_content = "またな、PlayerName。",
  ui_story_5040_50401402_172_dialog_content = "うん、またね！",
  ui_story_5040_50401402_173_dialog_content = "まったく…一日中駆けずり回って大変だったけど、\nピンクのサンドワームは見事に倒せたわね。",
  ui_story_5040_50401402_174_dialog_content = "…ということで、アドニスは最後の「試練」にも\n合格したってことになるわ。",
  ui_story_5040_50401402_175_dialog_content = "セーブルのことは本当に残念だったけど…",
  ui_story_5040_50401402_176_dialog_content = "あたしはこの旅で、\nアドニスの気持ちをはっきり知ることができたわ。",
  ui_story_5040_50401402_177_dialog_content = "僕もだ。ターラのことを理解できたよ。\n外の世界と向き合う勇気も湧いた。",
  ui_story_5040_50401402_178_dialog_content = "収穫があったってことね。じゃ、最後の儀式といきましょ。\n印章を押してあげるわ。",
  ui_story_5040_50401402_179_dialog_content = "<color=#e8d9bb>ポン！</color>",
  ui_story_5040_50401402_180_dialog_content = "おめでとう、2人とも。",
  ui_story_5040_50401402_181_dialog_content = "おめでとうございます！",
  ui_story_5040_50401402_182_option_content = "おめでとう",
  ui_story_5040_50401402_183_dialog_content = "ありがとう！",
  ui_story_5040_50401402_184_dialog_content = "ありがとうございます！",
  ui_story_5040_50401402_185_dialog_content = "皆さんの助けがなかったら、僕は今も外に出るのを怖がって、\n北境に閉じこもっていたことでしょう。",
  ui_story_5040_50401402_186_dialog_content = "でも、その恐怖は克服したんでしょ？",
  ui_story_5040_50401402_187_dialog_content = "うん。ようやく、君の側にいるための勇気ができたよ。",
  ui_story_5040_50401402_188_dialog_content = "オホン、オホン…水を差すようで悪いんだけど、\nイチャつく前に、山ほどやることがあるんじゃないかしら？",
  ui_story_5040_50401402_189_dialog_content = "…！",
  ui_story_5040_50401402_190_dialog_content = "そうですよ！まだ一番大事なことが解決していません！",
  ui_story_5040_50401402_191_dialog_content = "小鳥ちゃんも重大な問題に気付いたようね。",
  ui_story_5040_50401402_192_dialog_content = "え？何だろう？",
  ui_story_5040_50401402_193_dialog_content = "そんなのもちろん――",
  ui_story_5040_50401402_194_dialog_content = "結婚式よ／です！",
  ui_story_5040_50401501_1_dialog_content = "<color=#e8d9bb>数日後、北境</color>",
  ui_story_5040_50401501_2_dialog_content = "アドニスとターラ、遅いなぁ…",
  ui_story_5040_50401501_3_dialog_content = "ハクション――！",
  ui_story_5040_50401501_4_dialog_content = "寒い…あとどのくらい待たなきゃいけないのかな？",
  ui_story_5040_50401501_5_dialog_content = "辛抱がないのねぇ。大切な儀式なんだから、\nじっくり時間をかけて準備させてあげましょ。",
  ui_story_5040_50401501_6_dialog_content = "うーん、それはそうだね…",
  ui_story_5040_50401501_7_dialog_content = "ところで、ここって前にアドニスが\n式場にしようとしてたところじゃないよね…？",
  ui_story_5040_50401501_8_dialog_content = "当然じゃな～い？",
  ui_story_5040_50401501_9_dialog_content = "今回は駆け落ちするワケじゃないから、\n堂々と式を挙げるのよ。",
  ui_story_5040_50401501_10_dialog_content = "それとも…空の末裔くんは\n背徳感のある方が好きなのかしら～？",
  ui_story_5040_50401501_11_dialog_content = "こっちの方がいいよ！\n家族や友だちに祝福された方がいいに決まってる！",
  ui_story_5040_50401501_12_dialog_content = "おや、これはこれは…？",
  ui_story_5040_50401501_13_dialog_content = "ここでお会いできるとは思いませんでした。",
  ui_story_5040_50401501_14_dialog_content = "ノーヴィオ！君も出席するの？",
  ui_story_5040_50401501_15_dialog_content = "ええ、アドニスから招待を受けましたので。",
  ui_story_5040_50401501_16_dialog_content = "アドニスは私の教え子です。\n氷の宮殿からの祝福を届けに参りました。",
  ui_story_5040_50401501_17_dialog_content = "あ、思い出した。アドニスの両親とナルセールが、\nそんなことを言ってた気がする。",
  ui_story_5040_50401501_18_dialog_content = "アドニスはおとなしく慎重な性格ですから、\n今まで北境を離れたことはありませんでした。",
  ui_story_5040_50401501_19_dialog_content = "ですので、R・W出身の方と結婚すると聞いた時は、\n正直なところ、実に意外でした。",
  ui_story_5040_50401501_20_dialog_content = "ですが、北境の者が外の世界と交流し、\n視野を広げることには、女王陛下もきっとお喜びでしょう。",
  ui_story_5040_50401501_21_dialog_content = "そうだね！",
  ui_story_5040_50401501_22_dialog_content = "女王陛下にもどうかよろしく伝えておいて。",
  ui_story_5040_50401501_23_dialog_content = "もちろんです。",
  ui_story_5040_50401501_24_dialog_content = "では、新郎新婦に贈り物を渡しに行きますので、\n私は失礼させていただきます。",
  ui_story_5040_50401501_25_dialog_content = "うん、またね！",
  ui_story_5040_50401501_26_dialog_content = "またお会い出来る時を楽しみにしております。",
  ui_story_5040_50401501_27_dialog_content = "そういえば、キアはまだかな？",
  ui_story_5040_50401501_28_dialog_content = "影ノ街を通り過ぎる時、急用があるって言い出して、\nあわてて巨像を着陸させたんだけど…",
  ui_story_5040_50401501_29_dialog_content = "停まってもいないうちから飛び降りて行っちゃったんだ。\n何の用か聞いたけど、聞こえてなかったみたいだったし。",
  ui_story_5040_50401501_30_dialog_content = "まさかターラとアドニスの結婚式、\n出席するつもりがないのかな？",
  ui_story_5040_50401501_31_dialog_content = "キアは約束を守る子よ。",
  ui_story_5040_50401501_32_dialog_content = "な、なんとか…間に合いました！！",
  ui_story_5040_50401501_33_dialog_content = "はぁ、はぁ…遅刻ではないみたいですね！",
  ui_story_5040_50401501_34_dialog_content = "キア！？そんなに息を切らしてどうしたの？",
  ui_story_5040_50401501_35_dialog_content = "水でも飲んで落ち着くといいわ。\n式はもうすぐ始まるわよ～。",
  ui_story_5040_50401501_36_dialog_content = "ありがとうございます、先輩！",
  ui_story_5040_50401501_37_dialog_content = "<color=#e8d9bb>ゴクッゴクッ――</color>",
  ui_story_5040_50401501_38_dialog_content = "はぁ…間に合って本当によかったです…\n万が一遅れでもしたら大変なことでした。",
  ui_story_5040_50401501_39_dialog_content = "ここ数日どこに行ってたの？",
  ui_story_5040_50401501_40_dialog_content = "そういえば、PlayerNameさんにはまだ\nお話ししてませんでしたね。",
  ui_story_5040_50401501_41_dialog_content = "ターラさんとアドニスさんに頼まれて、\nサンドワームのウロコを指輪に仕立ててもらってきたんです。",
  ui_story_5040_50401501_42_dialog_content = "見てください！",
  ui_story_5040_50401501_43_dialog_content = "わぁ、きれいだね。\nサンドワームのウロコが材料なんて思えないよ！",
  ui_story_5040_50401501_44_dialog_content = "職人さんが予定よりだいぶ時間をかけて\nやっと仕上がったんですよ。",
  ui_story_5040_50401501_45_dialog_content = "エメラルド先生のノートに書かれた近道がなかったら、\n遅刻していたところでした。",
  ui_story_5040_50401501_46_dialog_content = "へぇ、近道があるの？\nこのアタシが知らないなんて…",
  ui_story_5040_50401501_47_dialog_content = "空の近道ですからね。\n北境行きの馬車に間に合わせるために、何時間も飛び続けたんですから！",
  ui_story_5040_50401501_48_dialog_content = "今でも翼が筋肉痛です！",
  ui_story_5040_50401501_49_dialog_content = "あら、知らなかった？緊急配達の任務があるクーリエは、\n影ノ街で報告すれば、交通手段を用意してもらえるはずよ～？",
  ui_story_5040_50401501_50_dialog_content = "え！？",
  ui_story_5040_50401501_51_dialog_content = "そんな…全然知りませんでした！\nエメラルド先生のノートにはそんなこと、まったく…",
  ui_story_5040_50401501_52_dialog_content = "最近始まったことだもの。\n先生のノートにはなくて当然よ。",
  ui_story_5040_50401501_53_dialog_content = "うう…どうやら他の支部のことも、\nしっかり勉強しておくべきみたいですね。",
  ui_story_5040_50401501_54_dialog_content = "自力でちゃんと間に合っただけでもすごいことだよ。\nまずは少し休んで。もうすぐ式が始まるよ。",
  ui_story_5040_50401501_55_dialog_content = "はい！",
  ui_story_5040_50401501_56_dialog_content = "私がいない間、準備の方は順調でしたか？",
  ui_story_5040_50401501_57_dialog_content = "特にあのインチキ霊媒師にきちんとお説教して、\n二度と同じことを繰り返さないように言いましたか？",
  ui_story_5040_50401501_58_dialog_content = "ふふ、当然でしょ。",
  ui_story_5040_50401501_59_dialog_content = "戻ってきて一番にあの霊媒師のところに行ったんだ――",
  ui_story_5040_50401501_60_dialog_content = "いました、あの霊媒師です！",
  ui_story_5040_50401501_61_dialog_content = "おや…！？ど、どうかしたのかな？",
  ui_story_5040_50401501_62_dialog_content = "数日前にあなたから「魔法の万能薬」を買った者です。\nあれはニセモノだったんですね。",
  ui_story_5040_50401501_63_dialog_content = "おお！思い出した、あんただったか。",
  ui_story_5040_50401501_64_dialog_content = "だが、言いがかりをつけてもらっちゃ困るねぇ。\nあの万能薬は正真正銘、貴重な材料で作った、効き目の高い薬なんだ。",
  ui_story_5040_50401501_65_dialog_content = "ピンクのサンドワームのウロコで作られてるんだぞ！",
  ui_story_5040_50401501_66_dialog_content = "こないだだって、あんたが自分で言ってたじゃないか？\nあの薬のせいで婚約者が記憶喪失になったとかならないとか…",
  ui_story_5040_50401501_67_dialog_content = "あたしがその婚約者よ、記憶喪失なんてウソ。\nあなたの薬にはなんの効き目もないわ。",
  ui_story_5040_50401501_68_dialog_content = "それに、ピンクのサンドワームのウロコなんて\n入ってやしないでしょ！",
  ui_story_5040_50401501_69_dialog_content = "何の証拠があって、そんな言いがかりをつけるんだ？",
  ui_story_5040_50401501_70_dialog_content = "じゃ、教えてちょうだい。\n材料のウロコはどこで手に入れたの？",
  ui_story_5040_50401501_71_dialog_content = "あ、あれはちょっと前にオークションで競り落としたんだ。\nアストラ中探しても、たった一枚しかないウロコだ。",
  ui_story_5040_50401501_72_dialog_content = "あら、それは奇遇ね。\nあたしもオークションでピンクのサンドワームのウロコを買ったの。",
  ui_story_5040_50401501_73_dialog_content = "なんだって！？",
  ui_story_5040_50401501_74_dialog_content = "オークションで競り落とした時に\nサインした証明書があるけど、見たい？",
  ui_story_5040_50401501_75_dialog_content = "あれにあんな値段を付けたのは、あんただったのか…！？",
  ui_story_5040_50401501_76_dialog_content = "そう、あっさり認めちゃうのねぇ。",
  ui_story_5040_50401501_77_dialog_content = "北境ではこういうイカサマに\nどういう罰を受けさせるのか知らないけど…",
  ui_story_5040_50401501_78_dialog_content = "R・W砂漠式のやり方、知りたいかしら？",
  ui_story_5040_50401501_79_dialog_content = "うーん…い、言わなくていいよ…",
  ui_story_5040_50401501_80_dialog_content = "す、すまなかった！",
  ui_story_5040_50401501_81_dialog_content = "金はすぐに返す！そ、それからきちんと自首する！",
  ui_story_5040_50401501_82_dialog_content = "よかった、無事解決したんですね。",
  ui_story_5040_50401501_83_dialog_content = "アドニスのご両親の方は？\n結婚は認められたんですか？",
  ui_story_5040_50401501_84_dialog_content = "アドニスが変わったって知って、何も言わなかったよ。",
  ui_story_5040_50401501_85_dialog_content = "あっさりアドニスとターラの結婚を認めてくれたんだ！",
  ui_story_5040_50401501_86_dialog_content = "本当ですか！？何だか信じられませんね！",
  ui_story_5040_50401501_87_dialog_content = "以前は駆け落ちしようとしていたことに、\nあれだけ腹を立てていたのに…",
  ui_story_5040_50401501_88_dialog_content = "それはあなたがアドニスの両親の本当の気持ちを\n見抜けてなかっただけねぇ。",
  ui_story_5040_50401501_89_dialog_content = "それが簡単に見抜けるのは、\nイェリア先輩くらいだと思いますけど…",
  ui_story_5040_50401501_90_dialog_content = "感知能力を使えば空の末裔くんにだって、\n簡単なことじゃな～い？",
  ui_story_5040_50401501_91_dialog_content = "能力で勝手に他人の考えを読むなんて失礼なこと、僕はしないよ！",
  ui_story_5040_50401501_92_dialog_content = "人を理解したいなら、交流することが一番だ。",
  ui_story_5040_50401501_93_dialog_content = "それで、アドニスさんのご両親は、\nいったいどんな考えだったんでしょうか？",
  ui_story_5040_50401501_94_dialog_content = "とっても単純なことよ。世間にいる大半の親と同じ。",
  ui_story_5040_50401501_95_dialog_content = "北境を一度も離れたことさえないような息子じゃ、\n外の世界でやっていけないんじゃないかって心配してただけよ。",
  ui_story_5040_50401501_96_dialog_content = "それでアドニスが北境を出ることに反対してただけ。",
  ui_story_5040_50401501_97_dialog_content = "でも、それじゃ悪循環だね。",
  ui_story_5040_50401501_98_dialog_content = "そうよ。だからアタシが「ちょっと」説得して、\nアドニスに外へ出るチャンスを与えてもらったの。",
  ui_story_5040_50401501_99_dialog_content = "まさか霊媒師の時みたいに脅したとか…？",
  ui_story_5040_50401501_100_dialog_content = "あら、空の末裔くん？\nアタシがそんなことするって思ってるの？",
  ui_story_5040_50401501_101_dialog_content = "いや、そうじゃないけど…",
  ui_story_5040_50401501_102_dialog_content = "相手が違えば、交渉の技も方法も変えるわよ。",
  ui_story_5040_50401501_103_dialog_content = "あの2人は道理のわかる人たちだったわ。\n大切な家族のことになると、視野が狭くなっちゃうだけ。",
  ui_story_5040_50401501_104_dialog_content = "問題の所在がはっきりすれば、\n自分たちの何が間違ってるのか、すぐに理解してもらえたわ。",
  ui_story_5040_50401501_105_dialog_content = "アドニスはいいご両親を持ったわねぇ。",
  ui_story_5040_50401501_106_dialog_content = "やっぱり、裏で色々動いてくれてたんだね！",
  ui_story_5040_50401501_107_dialog_content = "ほんのちょっと背中を押しただけよ。\nアタシも出身地の離れたカップルがどういう結末になるのか興味あったしね～。",
  ui_story_5040_50401501_108_dialog_content = "ま、なかなか悪くない結末だわ。",
  ui_story_5040_50401501_109_dialog_content = "あ！来ましたよ！",
  ui_story_5040_50401501_110_dialog_content = "アドニスさんとターラさんです！",
  ui_story_5040_50401501_111_dialog_content = "2人とも礼服を着てるね！",
  ui_story_5040_50401501_112_dialog_content = "ターラさん、きれいですね～。\n礼服を着たアドニスさん…結構カッコいいじゃないですか！？",
  ui_story_5040_50401501_113_dialog_content = "ターラ、アドニス、おめでとう。",
  ui_story_5040_50401501_114_dialog_content = "ご結婚おめでとうございます！",
  ui_story_5040_50401501_115_dialog_content = "結婚おめでとう！",
  ui_story_5040_50401501_116_dialog_content = "ありがとうございます！",
  ui_story_5040_50401501_117_dialog_content = "待たせちゃってごめんなさい！",
  ui_story_5040_50401501_118_dialog_content = "2人もクーリエに立ち会ってもらえるなんて、\nあたしたち、アストラで一番幸せなカップルね！",
  ui_story_5040_50401501_119_dialog_content = "それじゃ、始めるわよ。",
  ui_story_5040_50401501_120_dialog_content = "ターラ、あなたはこの者を生涯の伴侶とし――",
  ui_story_5040_50401501_121_dialog_content = "健やかなる時も病める時も、富める時も貧しい時も――",
  ui_story_5040_50401501_122_dialog_content = "夫を愛し、敬い、共に助け合い、\nその命ある限り真心を尽くすことを誓いますか？",
  ui_story_5040_50401501_123_dialog_content = "誓います！",
  ui_story_5040_50401501_124_dialog_content = "アドニス、あなたはこの者を生涯の伴侶とし――",
  ui_story_5040_50401501_125_dialog_content = "健やかなる時も病める時も、富める時も貧しい時も――",
  ui_story_5040_50401501_126_dialog_content = "妻を愛し、敬い、共に助け合い、\nその命ある限り真心を尽くすことを誓いますか？",
  ui_story_5040_50401501_127_dialog_content = "誓います！",
  ui_story_5040_50401501_128_dialog_content = "それでは、はるかな距離と無数の困難を乗り越え、\n今日ここで二人が結ばれる証として…",
  ui_story_5040_50401501_129_dialog_content = "指輪を交換してください。",
  ui_story_5040_50401501_130_dialog_content = "ふぅ…やっと式が終わったわね！",
  ui_story_5040_50401501_131_dialog_content = "ドレスを脱いで、楽な服に着替えられるわ！",
  ui_story_5040_50401501_132_dialog_content = "ドレス、気に入らなかったのかい？",
  ui_story_5040_50401501_133_dialog_content = "もちろん、気に入ってるわ！\n一緒に選んだドレスだもの。",
  ui_story_5040_50401501_134_dialog_content = "でも、重すぎて身動きがとれないわ！",
  ui_story_5040_50401501_135_dialog_content = "あなたに手を引かれて上がっていく時、\n何度も裾が引っかかって転びそうになったもの。",
  ui_story_5040_50401501_136_dialog_content = "アハハ、実は僕もそう思ってたんだ。\nドレスを着てる君はどこか窮屈そうだった。",
  ui_story_5040_50401501_137_dialog_content = "やっぱり好きな服を着て、\n好きなことをしてる君が一番きれいだよ！",
  ui_story_5040_50401501_138_dialog_content = "でも、アドニスは礼服がすっごくなじんでたわねぇ。\nきちんと着こなしてるみたいだったわ。",
  ui_story_5040_50401501_139_dialog_content = "不思議よねぇ。\n北境の人たちが普段着てる服だって、礼服とは全然違うのに。",
  ui_story_5040_50401501_140_dialog_content = "何か理由が有るのかしらぁ？",
  ui_story_5040_50401501_141_dialog_content = "オホン、それは…",
  ui_story_5040_50401501_142_dialog_content = "アドニスはずっと、こっそり式の準備をしていたんだ。",
  ui_story_5040_50401501_143_dialog_content = "父さん、母さん！？",
  ui_story_5040_50401501_144_dialog_content = "そうなんです。夜中に私たちが寝静まってから、\nこっそり礼服を着て、鏡の前で練習していました。",
  ui_story_5040_50401501_145_dialog_content = "式の事を本当に大事に思っていたみたいで。\nあの子のためにも、ステキな思い出にしたかったのでしょうね。",
  ui_story_5040_50401501_146_dialog_content = "だが、大きな物音を立てるものだから、\nこっちも毎回目を覚ましてしまってな。",
  ui_story_5040_50401501_147_dialog_content = "…知ってたんだね？",
  ui_story_5040_50401501_148_dialog_content = "当然だ。",
  ui_story_5040_50401501_149_dialog_content = "もともと、結婚することに反対はしてなかったものね。\n誰と結婚するかだって、あなたの自由だわ。",
  ui_story_5040_50401501_150_dialog_content = "私たちが心配していたのは、大した覚悟もないのに\nいっときの衝動で駆け落ちしようとしていたことだけよ。",
  ui_story_5040_50401501_151_dialog_content = "外の世界がどんなものかまるで知らないうえに、\nおかしな魔法の薬なんぞに頼って勇気を出そうなどと…",
  ui_story_5040_50401501_152_dialog_content = "もしあのまま結婚を許していたら、\nお前の親として無責任がすぎる！",
  ui_story_5040_50401501_153_dialog_content = "そうよ。やっぱり外の世界は自分に合わないなんて思って、\n北境を離れたことを後悔でもしだしたら…",
  ui_story_5040_50401501_154_dialog_content = "あなたを連れ出したターラのせいにしないとも限らないわ。",
  ui_story_5040_50401501_155_dialog_content = "そうなったら、彼女に対しても無責任になってしまうもの。",
  ui_story_5040_50401501_156_dialog_content = "父さん、母さん…ごめん、僕がいけなかったんだ…",
  ui_story_5040_50401501_157_dialog_content = "でも、今は外の世界がどんなものか、はっきり分かったよ。\nそのうえで、僕はターラと結婚したい。",
  ui_story_5040_50401501_158_dialog_content = "ええ、分かってるわ。アドニス…あなた、本当に変わったわね。\nもう反対なんてしないわ。",
  ui_story_5040_50401501_159_dialog_content = "おめでとう。幸せになるんだぞ。",
  ui_story_5040_50401501_160_dialog_content = "今はもう、ここは私たちだけの家じゃない。\nターラの家でもあるんだ。",
  ui_story_5040_50401501_161_dialog_content = "これから先、アストラ中を飛び回るんでしょうけど、忘れないで。\n北境にはいつだって帰る場所があるわ。",
  ui_story_5040_50401501_162_dialog_content = "父さん、母さん…ありがとう！",
  ui_story_5040_50401501_163_dialog_content = "これであたしたち、ほんとの家族になったのね！",
  ui_story_5040_50401501_164_dialog_content = "<color=#e8d9bb>2日後、ソラヴァン内部</color>",
  ui_story_5040_50401501_165_dialog_content = "ずいぶんかかっちゃったな…",
  ui_story_5040_50401501_166_dialog_content = "R・W砂漠から北境まで人を送っていくだけの話だと思ってたら、\n結局アストラ大陸を何周もしちゃったよ！",
  ui_story_5040_50401501_167_dialog_content = "バイスとカレンの休暇が終わる前に戻れてよかった。\nナルセールからもらった報酬で目当てのレコードプレーヤーも買えたし。",
  ui_story_5040_50401501_168_dialog_content = "いつも助けてもらってばかりだけど、\n今回は自分の力で2人にサプライズしてあげられるね。",
  ui_story_5040_50401501_169_dialog_content = "PlayerName、ただいま！",
  ui_story_5040_50401501_170_dialog_content = "冠月祭は例年通り忙しく過ごしたけれど、\n今年も穏やかに過ぎてよかったわ。",
  ui_story_5040_50401501_171_dialog_content = "私たちがいない間、何してたの？",
  ui_story_5040_50401501_172_dialog_content = "いつも通りだよ",
  ui_story_5040_50401501_173_dialog_content = "ソラヴァンであちこちを回って、\nいろんな場所の冠月祭の空気を味わってきたんだ。",
  ui_story_5040_50401501_174_dialog_content = "ついでにクーリエ隊の依頼も受けて、\nおこづかいも稼いだよ。",
  ui_story_5040_50401501_175_dialog_content = "そうらしいわね、聞いたわ！\nジョラさんにどうして一緒じゃなかったのかって聞かれたもの。",
  ui_story_5040_50401501_176_dialog_content = "私も白夜城の衛兵から\nあなたがクーリエ隊の手伝いをしていると聞いたわ。お疲れ様。",
  ui_story_5040_50401501_177_dialog_content = "大したことはしてないよ。",
  ui_story_5040_50401501_178_dialog_content = "忙しかった",
  ui_story_5040_50401501_179_dialog_content = "クーリエ隊の依頼を受けて、\nおこづかいを稼ごうと思ったら…",
  ui_story_5040_50401501_180_dialog_content = "すぐに終わる予定だったのに、\n結局ずいぶん時間がかかっちゃったよ！",
  ui_story_5040_50401501_181_dialog_content = "聞いたわ。白夜城にも来ていたし、啓光にも行ったようね？",
  ui_story_5040_50401501_182_dialog_content = "R・W砂漠と北境にも行ったって聞いたけど？\nずいぶん長旅だったみたいね。",
  ui_story_5040_50401501_183_dialog_content = "ちょっと待って。どこでそんなこと聞いたの？",
  ui_story_5040_50401501_184_dialog_content = "どこでって、ソラヴァンは目立つもの。\nどこに行ったって注目の的よ！",
  ui_story_5040_50401501_185_dialog_content = "確かにそうだね…",
  ui_story_5040_50401501_186_dialog_content = "まぁ、とにかく。\n2人にそのお金で用意したサプライズが有るんだ！",
  ui_story_5040_50401501_187_dialog_content = "ジャジャジャジャーン！",
  ui_story_5040_50401501_188_dialog_content = "これって、あのレコードプレーヤーじゃない！？",
  ui_story_5040_50401501_189_dialog_content = "確か、けっこうな値段だったはずね。",
  ui_story_5040_50401501_190_dialog_content = "この前影ノ街で買い物してた時、\nショーウィンドウに飾ってあったのをじっと見てたでしょ。",
  ui_story_5040_50401501_191_dialog_content = "気に入ったのかなと思って、こっそり値段を見ておいたんだ。\n正直言うと、本当にびっくりしたよ。",
  ui_story_5040_50401501_192_dialog_content = "でも、今までずっと助けてもらってきたし、\nちゃんとお礼を伝える機会もなかったから…",
  ui_story_5040_50401501_193_dialog_content = "このレコードプレーヤーを買って、\n2人に使ってもらおうって決めたんだ！",
  ui_story_5040_50401501_194_dialog_content = "それでこっそり色々と仕事をしてたんだけど、\nやっと十分な金額がたまったんだよ！",
  ui_story_5040_50401501_195_dialog_content = "PlayerName…",
  ui_story_5040_50401501_196_dialog_content = "私たちがそれを見ていたことには、理由があるの…",
  ui_story_5040_50401501_197_dialog_content = "カレンと相談してたのよ。\n一緒に旅をしてきたPlayerNameに何かプレゼントしたいねって。",
  ui_story_5040_50401501_198_dialog_content = "私たちが影ノ街でそれを見てたのは\nあなたへのプレゼントに良さそうって思ったからだったの。",
  ui_story_5040_50401501_199_dialog_content = "空の末裔は音楽を愛する一族って言うでしょ。\nいい道具があれば、もっと音楽を楽しめると思って。",
  ui_story_5040_50401501_200_dialog_content = "それで私たちも一緒にお金を貯めて、\nプレゼントしようって決めたの。",
  ui_story_5040_50401501_201_dialog_content = "それで冠月祭の間に色々と依頼を引き受けていたのよ。",
  ui_story_5040_50401501_202_dialog_content = "冠月祭に依頼…休んでたんじゃなかったんだ！",
  ui_story_5040_50401501_203_dialog_content = "ええ…あなたには内緒にしてたけど…",
  ui_story_5040_50401501_204_dialog_content = "ただ、影ノ街に戻ってみたら、\nレコードプレイヤーが売れてしまっていて…",
  ui_story_5040_50401501_205_dialog_content = "それで結局、影ノ街でお菓子と新しい本を買って来たのよ。\nあなたも一緒に楽しめると思って。",
  ui_story_5040_50401501_206_dialog_content = "レコードプレイヤーが欲しかったわけじゃなかったの！？",
